    public static readonly (string Key, string Ru, string En)[] Texts =
    {
        ("PolarCaravan_NAME", "Полярный караван (чёрный чай, крупный лист)", "Polar Caravan (black tea, large leaf)"),
        ("PolarCaravan_DESC", "Этот чай везли через тундру на оленях, и олени всю дорогу завидовали. Крупный лист, крепкий настой. На Великом Медведе караванов нет, зато есть ты, жестянка и шесть километров до ближайшей печки. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "This tea crossed the tundra by reindeer, and the reindeer were jealous the whole way. Large leaf, strong brew. Great Bear has no caravans, but it has you, a tin and four miles to the nearest stove. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("PolarCaravanCup_NAME", "Полярный караван (чёрный чай, крупный лист)", "Polar Caravan (black tea, large leaf)"),
        ("PolarCaravanCup_DESC", "Этот чай везли через тундру на оленях, и олени всю дорогу завидовали. Крупный лист, крепкий настой. На Великом Медведе караванов нет, зато есть ты, жестянка и шесть километров до ближайшей печки.", "This tea crossed the tundra by reindeer, and the reindeer were jealous the whole way. Large leaf, strong brew. Great Bear has no caravans, but it has you, a tin and four miles to the nearest stove."),
        ("MorningWhistle_NAME", "Утренний гудок (чёрный чай в пакетиках)", "Morning Whistle (black tea bags)"),
        ("MorningWhistle_DESC", "Раньше по гудку шли на завод. Теперь гудит только ветер в трубе, а на смену выходят волки. Пакетик в кружку, кипяток сверху, и можно делать вид, что утро доброе. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "The whistle used to call people to the factory. Now only the wind in the chimney whistles, and the wolves take the morning shift. Bag in the cup, hot water on top, and you can pretend the morning is good. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("MorningWhistleCup_NAME", "Утренний гудок (чёрный чай в пакетиках)", "Morning Whistle (black tea bags)"),
        ("MorningWhistleCup_DESC", "Раньше по гудку шли на завод. Теперь гудит только ветер в трубе, а на смену выходят волки. Пакетик в кружку, кипяток сверху, и можно делать вид, что утро доброе.", "The whistle used to call people to the factory. Now only the wind in the chimney whistles, and the wolves take the morning shift. Bag in the cup, hot water on top, and you can pretend the morning is good."),
        ("CountBergamot_NAME", "Граф Бергамот (чёрный чай с бергамотом)", "Count Bergamot (black tea with bergamot)"),
        ("CountBergamot_DESC", "Граф изволит пить чай в пять часов. Ты изволишь пить, когда растопишь снег. Бергамот пахнет гостиной с камином, и медведь за окном почти сходит за дворецкого. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "The Count takes his tea at five o'clock. You take yours whenever the snow melts. Bergamot smells of a drawing room with a fireplace, and the bear outside almost passes for a butler. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CountBergamotCup_NAME", "Граф Бергамот (чёрный чай с бергамотом)", "Count Bergamot (black tea with bergamot)"),
        ("CountBergamotCup_DESC", "Граф изволит пить чай в пять часов. Ты изволишь пить, когда растопишь снег. Бергамот пахнет гостиной с камином, и медведь за окном почти сходит за дворецкого.", "The Count takes his tea at five o'clock. You take yours whenever the snow melts. Bergamot smells of a drawing room with a fireplace, and the bear outside almost passes for a butler."),
        ("JadeRiver_NAME", "Нефритовая река (зелёный чай)", "Jade River (green tea)"),
        ("JadeRiver_DESC", "Зелёный чай с берегов реки, которая не замерзает. Местные реки таким похвастаться не могут: по ним ходят пешком и иногда проваливаются. Пей и вспоминай, как выглядит зелёный цвет. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Green tea from the banks of a river that never freezes. Local rivers can't say the same: people walk on them and sometimes fall through. Drink and remember what green looks like. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("JadeRiverCup_NAME", "Нефритовая река (зелёный чай)", "Jade River (green tea)"),
        ("JadeRiverCup_DESC", "Зелёный чай с берегов реки, которая не замерзает. Местные реки таким похвастаться не могут: по ним ходят пешком и иногда проваливаются. Пей и вспоминай, как выглядит зелёный цвет.", "Green tea from the banks of a river that never freezes. Local rivers can't say the same: people walk on them and sometimes fall through. Drink and remember what green looks like."),
        ("Yunling_NAME", "Юньлин (прессованный пуэр)", "Yunling (pressed pu-erh)"),
        ("Yunling_DESC", "Прессованный пуэр, твёрдый как характер выжившего. Отломи кусок ножом, остальным можно подпереть дверь. Пахнет землёй, которую здесь не видели с первого снега. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "Pressed pu-erh, hard as a survivor's temper. Break off a piece with a knife and prop the door with the rest. It smells of earth, which nobody here has seen since the first snow. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("YunlingCup_NAME", "Юньлин (прессованный пуэр)", "Yunling (pressed pu-erh)"),
        ("YunlingCup_DESC", "Прессованный пуэр, твёрдый как характер выжившего. Отломи кусок ножом, остальным можно подпереть дверь. Пахнет землёй, которую здесь не видели с первого снега.", "Pressed pu-erh, hard as a survivor's temper. Break off a piece with a knife and prop the door with the rest. It smells of earth, which nobody here has seen since the first snow."),
        ("CloudCliff_NAME", "Облачный утёс (улун)", "Cloud Cliff (oolong)"),
        ("CloudCliff_DESC", "Улун с утёса, где облака цепляются за кусты. На Волчьей горе облака цепляются за тебя. Разница в том, что там потом собирают чай, а здесь собирают остатки одежды. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Oolong from a cliff where the clouds snag on the bushes. On Timberwolf Mountain the clouds snag on you. The difference is that over there they pick tea afterwards, and here they pick up what is left of your clothes. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CloudCliffCup_NAME", "Облачный утёс (улун)", "Cloud Cliff (oolong)"),
        ("CloudCliffCup_DESC", "Улун с утёса, где облака цепляются за кусты. На Волчьей горе облака цепляются за тебя. Разница в том, что там потом собирают чай, а здесь собирают остатки одежды.", "Oolong from a cliff where the clouds snag on the bushes. On Timberwolf Mountain the clouds snag on you. The difference is that over there they pick tea afterwards, and here they pick up what is left of your clothes."),
        ("PampaVerde_NAME", "Пампа Верде (мате)", "Pampa Verde (yerba mate)"),
        ("PampaVerde_DESC", "Гаучо пьют мате и часами смотрят на горизонт. У тебя горизонт закрыт метелью, но привычка хорошая: после кружки начинаешь замечать, где ты вообще находишься. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Gauchos drink mate and stare at the horizon for hours. Your horizon is hidden by a blizzard, but the habit is sound: after a cup you start noticing where on earth you are. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("PampaVerdeCup_NAME", "Пампа Верде (мате)", "Pampa Verde (yerba mate)"),
        ("PampaVerdeCup_DESC", "Гаучо пьют мате и часами смотрят на горизонт. У тебя горизонт закрыт метелью, но привычка хорошая: после кружки начинаешь замечать, где ты вообще находишься.", "Gauchos drink mate and stare at the horizon for hours. Your horizon is hidden by a blizzard, but the habit is sound: after a cup you start noticing where on earth you are."),
        ("NileRose_NAME", "Нильская роза (каркаде)", "Nile Rose (hibiscus tea)"),
        ("NileRose_DESC", "Красный, кислый и родом из мест, где плюс сорок в тени. Здесь минус сорок на солнце. Каркаде об этом не предупреждали, но держится он достойно. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Red, sour and born where it is forty above in the shade. Here it is forty below in the sun. Nobody warned the hibiscus, but it is taking it well. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("NileRoseCup_NAME", "Нильская роза (каркаде)", "Nile Rose (hibiscus tea)"),
        ("NileRoseCup_DESC", "Красный, кислый и родом из мест, где плюс сорок в тени. Здесь минус сорок на солнце. Каркаде об этом не предупреждали, но держится он достойно.", "Red, sour and born where it is forty above in the shade. Here it is forty below in the sun. Nobody warned the hibiscus, but it is taking it well."),
        ("FireweedMeadow_NAME", "Кипрейный луг (иван-чай)", "Fireweed Meadow (fireweed tea)"),
        ("FireweedMeadow_DESC", "Иван-чай первым вырастает на пожарищах. Судя по тому, сколько здесь сгоревших домов, у него на острове большое будущее. Пока оно не наступило, пей из пачки. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Fireweed is the first thing to grow on burnt ground. Judging by the number of burnt houses here, it has a bright future on the island. Until then, drink the packet. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("FireweedMeadowCup_NAME", "Кипрейный луг (иван-чай)", "Fireweed Meadow (fireweed tea)"),
        ("FireweedMeadowCup_DESC", "Иван-чай первым вырастает на пожарищах. Судя по тому, сколько здесь сгоревших домов, у него на острове большое будущее. Пока оно не наступило, пей из пачки.", "Fireweed is the first thing to grow on burnt ground. Judging by the number of burnt houses here, it has a bright future on the island. Until then, drink the packet."),
        ("BombaySpice_NAME", "Пряный Бомбей (масала-чай)", "Bombay Spice (masala chai)"),
        ("BombaySpice_DESC", "Чай, в который положили всё, что нашли на базаре: кардамон, корицу, гвоздику, перец. Ты тоже кладёшь в рюкзак всё, что находишь, только у тебя получается не масала, а грыжа. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "A tea that got everything the bazaar had: cardamom, cinnamon, clove, pepper. You also put everything you find into your pack, except you end up with a hernia instead of masala. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("BombaySpiceCup_NAME", "Пряный Бомбей (масала-чай)", "Bombay Spice (masala chai)"),
        ("BombaySpiceCup_DESC", "Чай, в который положили всё, что нашли на базаре: кардамон, корицу, гвоздику, перец. Ты тоже кладёшь в рюкзак всё, что находишь, только у тебя получается не масала, а грыжа.", "A tea that got everything the bazaar had: cardamom, cinnamon, clove, pepper. You also put everything you find into your pack, except you end up with a hernia instead of masala."),
        ("FrostMint_NAME", "Ледяная мята (мятный чай в пакетиках)", "Frost Mint (peppermint tea bags)"),
        ("FrostMint_DESC", "Мятный чай с ледяной свежестью. Гениальный товар для острова, где ледяная свежесть бесплатно прилагается к каждой открытой двери. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Mint tea with icy freshness. A genius product for an island where icy freshness comes free with every opened door. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("FrostMintCup_NAME", "Ледяная мята (мятный чай в пакетиках)", "Frost Mint (peppermint tea bags)"),
        ("FrostMintCup_DESC", "Мятный чай с ледяной свежестью. Гениальный товар для острова, где ледяная свежесть бесплатно прилагается к каждой открытой двери.", "Mint tea with icy freshness. A genius product for an island where icy freshness comes free with every opened door."),
        ("SilverNeedle_NAME", "Серебряные иглы Байшань (белый чай)", "Baishan Silver Needle (white tea)"),
        ("SilverNeedle_DESC", "Белый чай из одних почек в серебристом пуху. Собирают два дня в году, руками, на рассвете. А ты завариваешь его в консервной банке над горящей книгой. Мастера бы плакали. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "White tea made of nothing but downy silver buds. Picked two days a year, by hand, at dawn. And you brew it in a food tin over a burning book. The masters would weep. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("SilverNeedleCup_NAME", "Серебряные иглы Байшань (белый чай)", "Baishan Silver Needle (white tea)"),
        ("SilverNeedleCup_DESC", "Белый чай из одних почек в серебристом пуху. Собирают два дня в году, руками, на рассвете. А ты завариваешь его в консервной банке над горящей книгой. Мастера бы плакали.", "White tea made of nothing but downy silver buds. Picked two days a year, by hand, at dawn. And you brew it in a food tin over a burning book. The masters would weep."),
        ("SkipperMocha_NAME", "Шкипер Мокко (молотый кофе)", "Skipper Mocha (ground coffee)"),
        ("SkipperMocha_DESC", "Шкипер пил этот кофе на мостике и не спал три вахты подряд. Его судно, кстати, лежит на боку у Прибрежного шоссе. Но кофе тут ни при чём, наверное. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "The skipper drank this coffee on the bridge and stayed up three watches in a row. His ship, by the way, lies on its side by the Coastal Highway. Probably not the coffee's fault. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SkipperMochaCup_NAME", "Шкипер Мокко (молотый кофе)", "Skipper Mocha (ground coffee)"),
        ("SkipperMochaCup_DESC", "Шкипер пил этот кофе на мостике и не спал три вахты подряд. Его судно, кстати, лежит на боку у Прибрежного шоссе. Но кофе тут ни при чём, наверное.", "The skipper drank this coffee on the bridge and stayed up three watches in a row. His ship, by the way, lies on its side by the Coastal Highway. Probably not the coffee's fault."),
        ("Instanta_NAME", "Инстанта (растворимый кофе)", "Instanta (instant coffee)"),
        ("Instanta_DESC", "Растворяется мгновенно: быстрее, чем твоя уверенность при виде медвежьих следов. Вкус кофе присутствует примерно как солнце в декабре, но выбирать не приходится. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Dissolves instantly: faster than your confidence at the sight of bear tracks. The taste of coffee is present about as much as the sun in December, but beggars can't be choosers. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("InstantaCup_NAME", "Инстанта (растворимый кофе)", "Instanta (instant coffee)"),
        ("InstantaCup_DESC", "Растворяется мгновенно: быстрее, чем твоя уверенность при виде медвежьих следов. Вкус кофе присутствует примерно как солнце в декабре, но выбирать не приходится.", "Dissolves instantly: faster than your confidence at the sight of bear tracks. The taste of coffee is present about as much as the sun in December, but beggars can't be choosers."),
        ("VulcanoNero_NAME", "Вулкано Неро (эспрессо, тёмная обжарка)", "Vulcano Nero (espresso, dark roast)"),
        ("VulcanoNero_DESC", "Чёрный как кратер, горький как правда. Итальянцы пьют это глотком и идут работать. Ты выпьешь и будешь до утра слушать, как дышит волк за стеной. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Black as a crater, bitter as the truth. Italians knock it back and go to work. You will drink it and spend the night listening to the wolf breathing behind the wall. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("VulcanoNeroCup_NAME", "Вулкано Неро (эспрессо, тёмная обжарка)", "Vulcano Nero (espresso, dark roast)"),
        ("VulcanoNeroCup_DESC", "Чёрный как кратер, горький как правда. Итальянцы пьют это глотком и идут работать. Ты выпьешь и будешь до утра слушать, как дышит волк за стеной.", "Black as a crater, bitter as the truth. Italians knock it back and go to work. You will drink it and spend the night listening to the wolf breathing behind the wall."),
        ("SweetTroika_NAME", "Сладкая тройка (кофе 3 в 1 в стиках)", "Sweet Troika (3-in-1 coffee sticks)"),
        ("SweetTroika_DESC", "Кофе, сливки и сахар в одном стике. Тройка, которая мчит тебя не по снежной дороге, а прямиком к мысли «ещё один, и спать». Спойлер: будет ещё три. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Coffee, creamer and sugar in one stick. A troika that carries you not down a snowy road but straight to the thought 'one more and then bed'. Spoiler: there will be three more. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("SweetTroikaCup_NAME", "Сладкая тройка (кофе 3 в 1 в стиках)", "Sweet Troika (3-in-1 coffee sticks)"),
        ("SweetTroikaCup_DESC", "Кофе, сливки и сахар в одном стике. Тройка, которая мчит тебя не по снежной дороге, а прямиком к мысли «ещё один, и спать». Спойлер: будет ещё три.", "Coffee, creamer and sugar in one stick. A troika that carries you not down a snowy road but straight to the thought 'one more and then bed'. Spoiler: there will be three more."),
        ("NorthLighthouse_NAME", "Северный маяк (свежая обжарка)", "North Lighthouse (fresh roast)"),
        ("NorthLighthouse_DESC", "Свежая обжарка, на пачке маяк. Настоящий маяк на мысе давно не светит, а этот хотя бы пахнет. Клапан на пакете нюхать не стыдно. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Fresh roast with a lighthouse on the bag. The real lighthouse at Desolation Point went dark long ago, and this one at least smells good. Sniffing the valve is nothing to be ashamed of. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("NorthLighthouseCup_NAME", "Северный маяк (свежая обжарка)", "North Lighthouse (fresh roast)"),
        ("NorthLighthouseCup_DESC", "Свежая обжарка, на пачке маяк. Настоящий маяк на мысе давно не светит, а этот хотя бы пахнет. Клапан на пакете нюхать не стыдно.", "Fresh roast with a lighthouse on the bag. The real lighthouse at Desolation Point went dark long ago, and this one at least smells good. Sniffing the valve is nothing to be ashamed of."),
        ("AndesAltura_NAME", "Анды Альтура (колумбийский кофе)", "Andes Altura (Colombian coffee)"),
        ("AndesAltura_DESC", "Кофе с высоты две тысячи метров. Там разрежённый воздух, и зерно зреет медленно. Здесь на высоте тоже всё происходит медленно, особенно подъём по верёвке с полным рюкзаком. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee from six thousand feet up. The air is thin there and the bean ripens slowly. Things are slow at altitude here too, especially climbing a rope with a full pack. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("AndesAlturaCup_NAME", "Анды Альтура (колумбийский кофе)", "Andes Altura (Colombian coffee)"),
        ("AndesAlturaCup_DESC", "Кофе с высоты две тысячи метров. Там разрежённый воздух, и зерно зреет медленно. Здесь на высоте тоже всё происходит медленно, особенно подъём по верёвке с полным рюкзаком.", "Coffee from six thousand feet up. The air is thin there and the bean ripens slowly. Things are slow at altitude here too, especially climbing a rope with a full pack."),
        ("SultanCardamom_NAME", "Султан Кардамон (кофе по-турецки с кардамоном)", "Sultan Cardamom (Turkish coffee with cardamom)"),
        ("SultanCardamom_DESC", "Султан пил этот кофе на подушках, пока ему махали опахалом. Тебе опахалом машет вьюга, а подушка одна, и та пахнет оленем. Зато кардамон настоящий. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "The Sultan drank this coffee on cushions while servants fanned him. Your fan is the blizzard, and your one cushion smells of deer. The cardamom is real, though. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("SultanCardamomCup_NAME", "Султан Кардамон (кофе по-турецки с кардамоном)", "Sultan Cardamom (Turkish coffee with cardamom)"),
        ("SultanCardamomCup_DESC", "Султан пил этот кофе на подушках, пока ему махали опахалом. Тебе опахалом машет вьюга, а подушка одна, и та пахнет оленем. Зато кардамон настоящий.", "The Sultan drank this coffee on cushions while servants fanned him. Your fan is the blizzard, and your one cushion smells of deer. The cardamom is real, though."),
        ("BlueBlossom_NAME", "Синий цветок (цикорий)", "Blue Blossom (chicory)"),
        ("BlueBlossom_DESC", "Цикорий: кофе для тех, кому кофе нельзя. Синий цветок у дороги, корень в чашке. На острове тебе можно всё, просто кофе кончился ещё у прошлого жильца. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Chicory: coffee for people who aren't allowed coffee. A blue flower by the road, the root in your cup. On the island you are allowed anything, it is just that the last tenant finished the coffee. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("BlueBlossomCup_NAME", "Синий цветок (цикорий)", "Blue Blossom (chicory)"),
        ("BlueBlossomCup_DESC", "Цикорий: кофе для тех, кому кофе нельзя. Синий цветок у дороги, корень в чашке. На острове тебе можно всё, просто кофе кончился ещё у прошлого жильца.", "Chicory: coffee for people who aren't allowed coffee. A blue flower by the road, the root in your cup. On the island you are allowed anything, it is just that the last tenant finished the coffee."),
        ("Icebreaker_NAME", "Ледокол (холодный кофе в банке)", "Icebreaker (canned cold brew)"),
        ("Icebreaker_DESC", "Холодный кофе в банке. На острове, где остывает всё, от чего отвернёшься на минуту. Зато огонь не нужен: открыл, выпил, пошёл колоть лёд дальше.", "Cold coffee in a can. On an island where everything turns cold the moment you look away. No fire needed though: crack it, drink it, go back to breaking ice."),
        ("FieldCoffee_NAME", "Полевой кофе ПК-3 (армейский растворимый кофе)", "Field Coffee FC-3 (army instant coffee)"),
        ("FieldCoffee_DESC", "Армейский кофе ПК-3. ПК-1 и ПК-2 засекречены, и, судя по вкусу третьего, правильно. Бодрит по уставу: быстро, без удовольствия и без права на жалобу. Готовится на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "Army field coffee FC-3. FC-1 and FC-2 are classified and, judging by the taste of the third, rightly so. Wakes you by the book: fast, joyless and with no right to complain. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("FieldCoffeeCup_NAME", "Полевой кофе ПК-3 (армейский растворимый кофе)", "Field Coffee FC-3 (army instant coffee)"),
        ("FieldCoffeeCup_DESC", "Армейский кофе ПК-3. ПК-1 и ПК-2 засекречены, и, судя по вкусу третьего, правильно. Бодрит по уставу: быстро, без удовольствия и без права на жалобу.", "Army field coffee FC-3. FC-1 and FC-2 are classified and, judging by the taste of the third, rightly so. Wakes you by the book: fast, joyless and with no right to complain."),
        ("OldTreeYiwu_NAME", "Старое дерево Иу (шэн пуэр, гора Иу)", "Yiwu Old Tree (sheng pu-erh, Mount Yiwu)"),
        ("OldTreeYiwu_DESC", "Лист с дерева, которому триста лет. Оно пережило династии, войны и туристов. Ты пока пережил четыре дня, но чай пьёшь тот же самый. Чувствуешь себя старше. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "Leaf from a tree three hundred years old. It outlived dynasties, wars and tourists. You have outlived four days so far, but you are drinking the same tea. You feel older already. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("OldTreeYiwuCup_NAME", "Старое дерево Иу (шэн пуэр, гора Иу)", "Yiwu Old Tree (sheng pu-erh, Mount Yiwu)"),
        ("OldTreeYiwuCup_DESC", "Лист с дерева, которому триста лет. Оно пережило династии, войны и туристов. Ты пока пережил четыре дня, но чай пьёшь тот же самый. Чувствуешь себя старше.", "Leaf from a tree three hundred years old. It outlived dynasties, wars and tourists. You have outlived four days so far, but you are drinking the same tea. You feel older already."),
        ("BanzhangLord_NAME", "Владыка Баньчжан (шэн пуэр Лао Баньчжан)", "Banzhang Lord (Lao Banzhang sheng pu-erh)"),
        ("BanzhangLord_DESC", "Король пуэров: горечь, которая через минуту становится сладостью. На Великом Медведе горечь обычно становится обморожением, так что это приятное разнообразие. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "The king of pu-erhs: a bitterness that turns sweet within a minute. On Great Bear bitterness usually turns into frostbite, so this makes a nice change. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("BanzhangLordCup_NAME", "Владыка Баньчжан (шэн пуэр Лао Баньчжан)", "Banzhang Lord (Lao Banzhang sheng pu-erh)"),
        ("BanzhangLordCup_DESC", "Король пуэров: горечь, которая через минуту становится сладостью. На Великом Медведе горечь обычно становится обморожением, так что это приятное разнообразие.", "The king of pu-erhs: a bitterness that turns sweet within a minute. On Great Bear bitterness usually turns into frostbite, so this makes a nice change."),
        ("BulangPeak_NAME", "Пик Булан (шэн пуэр, горы Булан)", "Bulang Peak (sheng pu-erh, Bulang mountains)"),
        ("BulangPeak_DESC", "Суровый пуэр с гор Булан. Бьёт горечью сразу, без приветствия. Местные волки одобряют такой подход и сами работают так же. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "A stern pu-erh from the Bulang mountains. Hits you with bitterness at once, no greeting. The local wolves approve of the approach and work the same way. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("BulangPeakCup_NAME", "Пик Булан (шэн пуэр, горы Булан)", "Bulang Peak (sheng pu-erh, Bulang mountains)"),
        ("BulangPeakCup_DESC", "Суровый пуэр с гор Булан. Бьёт горечью сразу, без приветствия. Местные волки одобряют такой подход и сами работают так же.", "A stern pu-erh from the Bulang mountains. Hits you with bitterness at once, no greeting. The local wolves approve of the approach and work the same way."),
        ("IceIsland_NAME", "Ледяной остров (шэн пуэр Биндао)", "Ice Island (Bingdao sheng pu-erh)"),
        ("IceIsland_DESC", "Пуэр из деревни Биндао, «Ледяной остров». Там так назвали деревню ради красоты. А ты на ледяном острове живёшь, и красота тут последнее, о чём думаешь. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Pu-erh from Bingdao village, 'Ice Island'. They named the village that because it sounded pretty. You actually live on an ice island, and pretty is the last thing on your mind. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("IceIslandCup_NAME", "Ледяной остров (шэн пуэр Биндао)", "Ice Island (Bingdao sheng pu-erh)"),
        ("IceIslandCup_DESC", "Пуэр из деревни Биндао, «Ледяной остров». Там так назвали деревню ради красоты. А ты на ледяном острове живёшь, и красота тут последнее, о чём думаешь.", "Pu-erh from Bingdao village, 'Ice Island'. They named the village that because it sounded pretty. You actually live on an ice island, and pretty is the last thing on your mind."),
        ("JingmaiOrchid_NAME", "Орхидея Цзинмай (шэн пуэр, гора Цзинмай)", "Jingmai Orchid (sheng pu-erh, Mount Jingmai)"),
        ("JingmaiOrchid_DESC", "Чайные деревья растут в лесу вперемешку с орхидеями, и лист пахнет цветами. Твоя одежда лежит вперемешку с волчьими шкурами и пахнет соответственно. Чай выигрывает. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "The tea trees grow in a forest among orchids, and the leaf smells of flowers. Your clothes live among wolf pelts and smell accordingly. The tea wins. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("JingmaiOrchidCup_NAME", "Орхидея Цзинмай (шэн пуэр, гора Цзинмай)", "Jingmai Orchid (sheng pu-erh, Mount Jingmai)"),
        ("JingmaiOrchidCup_DESC", "Чайные деревья растут в лесу вперемешку с орхидеями, и лист пахнет цветами. Твоя одежда лежит вперемешку с волчьими шкурами и пахнет соответственно. Чай выигрывает.", "The tea trees grow in a forest among orchids, and the leaf smells of flowers. Your clothes live among wolf pelts and smell accordingly. The tea wins."),
        ("NannuoMist_NAME", "Туман Наньно (шэн пуэр, гора Наньно)", "Nannuo Mist (sheng pu-erh, Mount Nannuo)"),
        ("NannuoMist_DESC", "На горе Наньно туман двести дней в году, и чаю это на пользу. На Загадочном озере туман тоже бывает, но на пользу он только тому, кто идёт за тобой следом. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "Mount Nannuo sits in mist two hundred days a year, and the tea loves it. Mystery Lake gets mist too, but the only one who loves it is whatever is following you. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("NannuoMistCup_NAME", "Туман Наньно (шэн пуэр, гора Наньно)", "Nannuo Mist (sheng pu-erh, Mount Nannuo)"),
        ("NannuoMistCup_DESC", "На горе Наньно туман двести дней в году, и чаю это на пользу. На Загадочном озере туман тоже бывает, но на пользу он только тому, кто идёт за тобой следом.", "Mount Nannuo sits in mist two hundred days a year, and the tea loves it. Mystery Lake gets mist too, but the only one who loves it is whatever is following you."),
        ("BadaWind_NAME", "Ветер Бада (шэн пуэр, гора Бада)", "Bada Wind (sheng pu-erh, Mount Bada)"),
        ("BadaWind_DESC", "Пуэр с продуваемой горы Бада. Ветер там треплет листья, и они вырастают упрямыми. Тебя ветер тоже треплет каждый день, но упрямее ты пока не стал, только обветреннее. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Pu-erh from windswept Mount Bada. The wind batters the leaves and they grow stubborn. The wind batters you daily too, though so far you have only grown more chapped. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("BadaWindCup_NAME", "Ветер Бада (шэн пуэр, гора Бада)", "Bada Wind (sheng pu-erh, Mount Bada)"),
        ("BadaWindCup_DESC", "Пуэр с продуваемой горы Бада. Ветер там треплет листья, и они вырастают упрямыми. Тебя ветер тоже треплет каждый день, но упрямее ты пока не стал, только обветреннее.", "Pu-erh from windswept Mount Bada. The wind batters the leaves and they grow stubborn. The wind batters you daily too, though so far you have only grown more chapped."),
        ("MengkuSnow_NAME", "Снега Мэнку (шэн пуэр Мэнку)", "Mengku Snow (Mengku sheng pu-erh)"),
        ("MengkuSnow_DESC", "Чай со склонов Большой Снежной горы. Китайцы считают, что снег на вершине придаёт чаю благородство. У тебя снега по пояс, благородства должно быть через край. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "Tea from the slopes of the Big Snow Mountain. The Chinese hold that snow on the peak makes the tea noble. You are waist-deep in snow, so you must be dripping with nobility. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("MengkuSnowCup_NAME", "Снега Мэнку (шэн пуэр Мэнку)", "Mengku Snow (Mengku sheng pu-erh)"),
        ("MengkuSnowCup_DESC", "Чай со склонов Большой Снежной горы. Китайцы считают, что снег на вершине придаёт чаю благородство. У тебя снега по пояс, благородства должно быть через край.", "Tea from the slopes of the Big Snow Mountain. The Chinese hold that snow on the peak makes the tea noble. You are waist-deep in snow, so you must be dripping with nobility."),
        ("XiguiBank_NAME", "Берег Сигуй (шэн пуэр Сигуй)", "Xigui Bank (Xigui sheng pu-erh)"),
        ("XiguiBank_DESC", "Пуэр с берега Меконга: мягкий, сладкий, тягучий. Сюда его довезли, судя по всему, вплавь. Твой берег попроще: лёд, рыбацкая будка и ощущение, что за тобой наблюдают. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Pu-erh from the bank of the Mekong: soft, sweet, lingering. It seems to have swum all the way here. Your bank is simpler: ice, a fishing hut and the feeling of being watched. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("XiguiBankCup_NAME", "Берег Сигуй (шэн пуэр Сигуй)", "Xigui Bank (Xigui sheng pu-erh)"),
        ("XiguiBankCup_DESC", "Пуэр с берега Меконга: мягкий, сладкий, тягучий. Сюда его довезли, судя по всему, вплавь. Твой берег попроще: лёд, рыбацкая будка и ощущение, что за тобой наблюдают.", "Pu-erh from the bank of the Mekong: soft, sweet, lingering. It seems to have swum all the way here. Your bank is simpler: ice, a fishing hut and the feeling of being watched."),
        ("YouleDrum_NAME", "Барабан Юлэ (шэн пуэр, гора Юлэ)", "Youle Drum (sheng pu-erh, Mount Youle)"),
        ("YouleDrum_DESC", "На горе Юлэ бьют в барабан, чтобы отогнать злых духов от чайных садов. Ты бьёшь ложкой по кастрюле, чтобы отогнать волка от крыльца. Традиции похожи, результат у них лучше. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "On Mount Youle they beat a drum to keep evil spirits out of the tea gardens. You beat a pot with a spoon to keep a wolf off the porch. Similar traditions, though theirs works better. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("YouleDrumCup_NAME", "Барабан Юлэ (шэн пуэр, гора Юлэ)", "Youle Drum (sheng pu-erh, Mount Youle)"),
        ("YouleDrumCup_DESC", "На горе Юлэ бьют в барабан, чтобы отогнать злых духов от чайных садов. Ты бьёшь ложкой по кастрюле, чтобы отогнать волка от крыльца. Традиции похожи, результат у них лучше.", "On Mount Youle they beat a drum to keep evil spirits out of the tea gardens. You beat a pot with a spoon to keep a wolf off the porch. Similar traditions, though theirs works better."),
        ("YibangLeaf_NAME", "Малый лист Ибан (шэн пуэр Ибан)", "Yibang Small Leaf (Yibang sheng pu-erh)"),
        ("YibangLeaf_DESC", "Мелкий лист, который когда-то возили императору. Император пил и хвалил. Ты пьёшь и молчишь, потому что хвалить вслух тут некому, а волки комплиментов не понимают. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "A small leaf once sent to the emperor. The emperor drank and praised it. You drink in silence, since there is nobody to praise it to and wolves don't take compliments. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("YibangLeafCup_NAME", "Малый лист Ибан (шэн пуэр Ибан)", "Yibang Small Leaf (Yibang sheng pu-erh)"),
        ("YibangLeafCup_DESC", "Мелкий лист, который когда-то возили императору. Император пил и хвалил. Ты пьёшь и молчишь, потому что хвалить вслух тут некому, а волки комплиментов не понимают.", "A small leaf once sent to the emperor. The emperor drank and praised it. You drink in silence, since there is nobody to praise it to and wolves don't take compliments."),
        ("PurpleZijuan_NAME", "Пурпурная Цзы Цзюань (пурпурный пуэр)", "Purple Zijuan (purple pu-erh)"),
        ("PurpleZijuan_DESC", "Пурпурный чай: лист фиолетовый, настой тоже. Цвет в точности как твои пальцы после часа рыбалки без перчаток. Только чай от этого полезнее, а пальцы нет. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Purple tea: violet leaf, violet brew. The exact colour of your fingers after an hour of fishing without gloves. Except it makes the tea healthier and the fingers not so much. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("PurpleZijuanCup_NAME", "Пурпурная Цзы Цзюань (пурпурный пуэр)", "Purple Zijuan (purple pu-erh)"),
        ("PurpleZijuanCup_DESC", "Пурпурный чай: лист фиолетовый, настой тоже. Цвет в точности как твои пальцы после часа рыбалки без перчаток. Только чай от этого полезнее, а пальцы нет.", "Purple tea: violet leaf, violet brew. The exact colour of your fingers after an hour of fishing without gloves. Except it makes the tea healthier and the fingers not so much."),
        ("ThirtyWinters_NAME", "Тридцать зим (выдержанный шэн пуэр)", "Thirty Winters (aged sheng pu-erh)"),
        ("ThirtyWinters_DESC", "Этот блин пролежал тридцать зим и стал только лучше. Ты пролежал одну ночь в снежном укрытии и лучше не стал. Вывод: не все созданы для выдержки. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "This cake lay through thirty winters and only got better. You lay through one night in a snow shelter and did not improve. Conclusion: not everyone is made for ageing. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("ThirtyWintersCup_NAME", "Тридцать зим (выдержанный шэн пуэр)", "Thirty Winters (aged sheng pu-erh)"),
        ("ThirtyWintersCup_DESC", "Этот блин пролежал тридцать зим и стал только лучше. Ты пролежал одну ночь в снежном укрытии и лучше не стал. Вывод: не все созданы для выдержки.", "This cake lay through thirty winters and only got better. You lay through one night in a snow shelter and did not improve. Conclusion: not everyone is made for ageing."),
        ("MenghaiHearth_NAME", "Очаг Мэнхая (шу пуэр Мэнхай)", "Menghai Hearth (Menghai shou pu-erh)"),
        ("MenghaiHearth_DESC", "Шу пуэр: тёмный, густой, пахнет орехами и погребом. Его специально томят в кучах, чтобы он состарился быстрее. Остров делает с людьми то же самое, только без куч. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "Shou pu-erh: dark, thick, smelling of nuts and a cellar. They pile it up on purpose to age it faster. The island does the same to people, minus the piles. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("MenghaiHearthCup_NAME", "Очаг Мэнхая (шу пуэр Мэнхай)", "Menghai Hearth (Menghai shou pu-erh)"),
        ("MenghaiHearthCup_DESC", "Шу пуэр: тёмный, густой, пахнет орехами и погребом. Его специально томят в кучах, чтобы он состарился быстрее. Остров делает с людьми то же самое, только без куч.", "Shou pu-erh: dark, thick, smelling of nuts and a cellar. They pile it up on purpose to age it faster. The island does the same to people, minus the piles."),
        ("PalaceGold_NAME", "Дворцовое золото (шу пуэр гунтин)", "Palace Gold (Gong Ting shou pu-erh)"),
        ("PalaceGold_DESC", "Дворцовый сорт: мелкие золотые почки, чай для чиновников в шёлке. Твой дворец называется «гараж у плотины», шёлк заменяет медвежья шкура. Этикет прежний: пить горячим. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Palace grade: tiny golden buds, a tea for officials in silk. Your palace is called 'the garage by the dam' and a bearskin stands in for silk. Etiquette unchanged: drink it hot. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("PalaceGoldCup_NAME", "Дворцовое золото (шу пуэр гунтин)", "Palace Gold (Gong Ting shou pu-erh)"),
        ("PalaceGoldCup_DESC", "Дворцовый сорт: мелкие золотые почки, чай для чиновников в шёлке. Твой дворец называется «гараж у плотины», шёлк заменяет медвежья шкура. Этикет прежний: пить горячим.", "Palace grade: tiny golden buds, a tea for officials in silk. Your palace is called 'the garage by the dam' and a bearskin stands in for silk. Etiquette unchanged: drink it hot."),
        ("TeaNuggets_NAME", "Чайные самородки (шу пуэр лао ча тоу)", "Tea Nuggets (Lao Cha Tou shou pu-erh)"),
        ("TeaNuggets_DESC", "Комки, которые слиплись при выдержке пуэра. Сначала их выбрасывали, потом попробовали. На острове ты тоже начал есть то, что раньше выбросил бы. Добро пожаловать в клуб. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 14.", "Lumps that clumped together while the pu-erh was ageing. They used to throw them out, then someone tasted them. On the island you also started eating things you once would have binned. Welcome to the club. Brew it over a fire: put it in a pot with water. Servings: 14."),
        ("TeaNuggetsCup_NAME", "Чайные самородки (шу пуэр лао ча тоу)", "Tea Nuggets (Lao Cha Tou shou pu-erh)"),
        ("TeaNuggetsCup_DESC", "Комки, которые слиплись при выдержке пуэра. Сначала их выбрасывали, потом попробовали. На острове ты тоже начал есть то, что раньше выбросил бы. Добро пожаловать в клуб.", "Lumps that clumped together while the pu-erh was ageing. They used to throw them out, then someone tasted them. On the island you also started eating things you once would have binned. Welcome to the club."),
        ("RiceNest_NAME", "Рисовое гнёздышко (мини-точа с ароматом клейкого риса)", "Rice Nest (sticky rice mini tuocha)"),
        ("RiceNest_DESC", "Крошечное гнёздышко пуэра с запахом варёного риса. Риса на острове нет, так что это единственный способ его понюхать. Одно гнёздышко на кружку, и никаких птенцов. Заваривается на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "A tiny nest of pu-erh that smells of steamed rice. There is no rice on the island, so this is your only chance to sniff some. One nest per cup, no chicks included. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("RiceNestCup_NAME", "Рисовое гнёздышко (мини-точа с ароматом клейкого риса)", "Rice Nest (sticky rice mini tuocha)"),
        ("RiceNestCup_DESC", "Крошечное гнёздышко пуэра с запахом варёного риса. Риса на острове нет, так что это единственный способ его понюхать. Одно гнёздышко на кружку, и никаких птенцов.", "A tiny nest of pu-erh that smells of steamed rice. There is no rice on the island, so this is your only chance to sniff some. One nest per cup, no chicks included."),
        ("RoseNest_NAME", "Розовое гнёздышко (мини-точа с розой)", "Rose Nest (rose mini tuocha)"),
        ("RoseNest_DESC", "Мини-точа с лепестками розы. Самая романтичная вещь на сто километров вокруг. Подарить некому, поэтому пьёшь сам и смотришь на полярное сияние. Тоже свидание. Заваривается на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "A mini tuocha with rose petals. The most romantic object for sixty miles around. There is nobody to give it to, so you drink it yourself and watch the aurora. Still counts as a date. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("RoseNestCup_NAME", "Розовое гнёздышко (мини-точа с розой)", "Rose Nest (rose mini tuocha)"),
        ("RoseNestCup_DESC", "Мини-точа с лепестками розы. Самая романтичная вещь на сто километров вокруг. Подарить некому, поэтому пьёшь сам и смотришь на полярное сияние. Тоже свидание.", "A mini tuocha with rose petals. The most romantic object for sixty miles around. There is nobody to give it to, so you drink it yourself and watch the aurora. Still counts as a date."),
        ("ChrysCake_NAME", "Хризантемовый блин (пуэр с хризантемой)", "Chrysanthemum Cake (chrysanthemum pu-erh)"),
        ("ChrysCake_DESC", "Пуэр с хризантемой: в Китае такой пьют, чтобы «остудить внутренний жар». У тебя с внутренним жаром проблем нет, его выдуло ещё на перевале. Но вкусно. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Pu-erh with chrysanthemum: in China they drink it to 'cool the inner heat'. You have no trouble with inner heat, it got blown out of you back at the pass. Tasty, though. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ChrysCakeCup_NAME", "Хризантемовый блин (пуэр с хризантемой)", "Chrysanthemum Cake (chrysanthemum pu-erh)"),
        ("ChrysCakeCup_DESC", "Пуэр с хризантемой: в Китае такой пьют, чтобы «остудить внутренний жар». У тебя с внутренним жаром проблем нет, его выдуло ещё на перевале. Но вкусно.", "Pu-erh with chrysanthemum: in China they drink it to 'cool the inner heat'. You have no trouble with inner heat, it got blown out of you back at the pass. Tasty, though."),
        ("GreenTangerine_NAME", "Зелёный мандарин (пуэр в мандарине)", "Green Tangerine (pu-erh in a tangerine)"),
        ("GreenTangerine_DESC", "Пуэр, который засунули в маленький зелёный мандарин и высушили. Выглядит как ёлочная игрушка. Самое близкое к Новому году, что с тобой случится на этом острове. Заваривается на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "Pu-erh stuffed into a small green tangerine and dried. It looks like a Christmas bauble. The closest thing to the holidays that will happen to you on this island. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("GreenTangerineCup_NAME", "Зелёный мандарин (пуэр в мандарине)", "Green Tangerine (pu-erh in a tangerine)"),
        ("GreenTangerineCup_DESC", "Пуэр, который засунули в маленький зелёный мандарин и высушили. Выглядит как ёлочная игрушка. Самое близкое к Новому году, что с тобой случится на этом острове.", "Pu-erh stuffed into a small green tangerine and dried. It looks like a Christmas bauble. The closest thing to the holidays that will happen to you on this island."),
        ("BambooJoint_NAME", "Бамбуковое колено (пуэр в бамбуке)", "Bamboo Joint (bamboo tube pu-erh)"),
        ("BambooJoint_DESC", "Пуэр, запечённый в бамбуковом стволе. Чтобы достать чай, бамбук надо расколоть. Наконец-то задача, для которой у тебя с собой топор, а не надежда. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Pu-erh baked inside a bamboo stem. To get at the tea you have to split the bamboo. At last a job for which you carry an axe rather than hope. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("BambooJointCup_NAME", "Бамбуковое колено (пуэр в бамбуке)", "Bamboo Joint (bamboo tube pu-erh)"),
        ("BambooJointCup_DESC", "Пуэр, запечённый в бамбуковом стволе. Чтобы достать чай, бамбук надо расколоть. Наконец-то задача, для которой у тебя с собой топор, а не надежда.", "Pu-erh baked inside a bamboo stem. To get at the tea you have to split the bamboo. At last a job for which you carry an axe rather than hope."),
        ("BirdsNest_NAME", "Птичье гнездо (шэн точа)", "Bird's Nest (sheng tuocha)"),
        ("BirdsNest_DESC", "Точа: пуэр в форме гнезда. Вороны над трупом оленя посмотрели бы с уважением. Они тут вообще главные по гнёздам и по новостям о том, кто недавно умер. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Tuocha: pu-erh shaped like a nest. The crows circling a deer carcass would look on with respect. They run the nests around here, and the news about who died lately. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("BirdsNestCup_NAME", "Птичье гнездо (шэн точа)", "Bird's Nest (sheng tuocha)"),
        ("BirdsNestCup_DESC", "Точа: пуэр в форме гнезда. Вороны над трупом оленя посмотрели бы с уважением. Они тут вообще главные по гнёздам и по новостям о том, кто недавно умер.", "Tuocha: pu-erh shaped like a nest. The crows circling a deer carcass would look on with respect. They run the nests around here, and the news about who died lately."),
        ("DarkBowl_NAME", "Тёмная чаша (шу точа)", "Dark Bowl (shou tuocha)"),
        ("DarkBowl_DESC", "Тёмная точа: перевернёшь, и получится чашечка из чая. Чашка, которую заваривают в чашке: философская вещь. Долгими ночами у печки на такие мысли как раз хватает времени. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "A dark tuocha: flip it over and you get a bowl you could drink itself from. A philosophical object. Long nights by the stove leave just enough time for thoughts like that. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("DarkBowlCup_NAME", "Тёмная чаша (шу точа)", "Dark Bowl (shou tuocha)"),
        ("DarkBowlCup_DESC", "Тёмная точа: перевернёшь, и получится чашечка из чая. Чашка, которую заваривают в чашке: философская вещь. Долгими ночами у печки на такие мысли как раз хватает времени.", "A dark tuocha: flip it over and you get a bowl you could drink itself from. A philosophical object. Long nights by the stove leave just enough time for thoughts like that."),
        ("TeaRoadBrick_NAME", "Кирпич Чайного пути (шэн пуэр, кирпич)", "Tea Road Brick (sheng pu-erh brick)"),
        ("TeaRoadBrick_DESC", "Чайный кирпич, какими платили вместо денег. За такой давали овцу. На Великом Медведе курс другой: за кирпич дают тёплый вечер, а овцу тут не видели никогда. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A tea brick of the kind once used as money. One would buy you a sheep. The exchange rate on Great Bear differs: a brick buys a warm evening, and nobody has ever seen a sheep here. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("TeaRoadBrickCup_NAME", "Кирпич Чайного пути (шэн пуэр, кирпич)", "Tea Road Brick (sheng pu-erh brick)"),
        ("TeaRoadBrickCup_DESC", "Чайный кирпич, какими платили вместо денег. За такой давали овцу. На Великом Медведе курс другой: за кирпич дают тёплый вечер, а овцу тут не видели никогда.", "A tea brick of the kind once used as money. One would buy you a sheep. The exchange rate on Great Bear differs: a brick buys a warm evening, and nobody has ever seen a sheep here."),
        ("KunmingBrick_NAME", "Красный кирпич Куньмина (шу пуэр, кирпич)", "Kunming Red Brick (shou pu-erh brick)"),
        ("KunmingBrick_DESC", "Красный кирпич из Куньмина. В отличие от обычного кирпича, заваривается. В отличие от обычного чая, им можно разбить окно. Вещь двойного назначения. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A red brick from Kunming. Unlike a normal brick, it brews. Unlike a normal tea, it can break a window. A dual-purpose item. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("KunmingBrickCup_NAME", "Красный кирпич Куньмина (шу пуэр, кирпич)", "Kunming Red Brick (shou pu-erh brick)"),
        ("KunmingBrickCup_DESC", "Красный кирпич из Куньмина. В отличие от обычного кирпича, заваривается. В отличие от обычного чая, им можно разбить окно. Вещь двойного назначения.", "A red brick from Kunming. Unlike a normal brick, it brews. Unlike a normal tea, it can break a window. A dual-purpose item."),
        ("FourSeals_NAME", "Четыре печати (пуэр фанча, квадрат)", "Four Seals (fangcha square pu-erh)"),
        ("FourSeals_DESC", "Квадратная плитка с четырьмя иероглифами: счастье, достаток, долголетие, радость. На острове из этого списка доступен только чай. Ломай по линиям, как шоколад. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "A square tile stamped with four characters: luck, wealth, long life, joy. On the island only the tea from that list is in stock. Break it along the lines like chocolate. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("FourSealsCup_NAME", "Четыре печати (пуэр фанча, квадрат)", "Four Seals (fangcha square pu-erh)"),
        ("FourSealsCup_DESC", "Квадратная плитка с четырьмя иероглифами: счастье, достаток, долголетие, радость. На острове из этого списка доступен только чай. Ломай по линиям, как шоколад.", "A square tile stamped with four characters: luck, wealth, long life, joy. On the island only the tea from that list is in stock. Break it along the lines like chocolate."),
        ("JinchaHeart_NAME", "Сердце Цзиньча (пуэр цзиньча, гриб)", "Jincha Heart (jincha mushroom pu-erh)"),
        ("JinchaHeart_DESC", "Пуэр в форме гриба, его возили в Тибет. Не ядовит, потому что это не гриб. А вот те грибы, что ты нашёл на пеньке, лучше сначала сверь с книжкой. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Pu-erh shaped like a mushroom, once carried to Tibet. Perfectly safe, because it is not a mushroom. The ones you found on that stump, however, you had better check against the book first. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("JinchaHeartCup_NAME", "Сердце Цзиньча (пуэр цзиньча, гриб)", "Jincha Heart (jincha mushroom pu-erh)"),
        ("JinchaHeartCup_DESC", "Пуэр в форме гриба, его возили в Тибет. Не ядовит, потому что это не гриб. А вот те грибы, что ты нашёл на пеньке, лучше сначала сверь с книжкой.", "Pu-erh shaped like a mushroom, once carried to Tibet. Perfectly safe, because it is not a mushroom. The ones you found on that stump, however, you had better check against the book first."),
        ("GoldenMelon_NAME", "Золотая тыква (пуэр цзиньгуа, тыква)", "Golden Melon (jingua melon pu-erh)"),
        ("GoldenMelon_DESC", "Пуэр в форме тыквы, подарок императору. Тяжёлый, круглый, с дольками. Если совсем прижмёт, им можно кинуть в волка. Волк удивится, а ты останешься без чая. Не кидай. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 16.", "Pu-erh shaped like a pumpkin, a tribute to the emperor. Heavy, round, with segments. In a pinch you could throw it at a wolf. The wolf would be surprised and you would be out of tea. Don't. Brew it over a fire: put it in a pot with water. Servings: 16."),
        ("GoldenMelonCup_NAME", "Золотая тыква (пуэр цзиньгуа, тыква)", "Golden Melon (jingua melon pu-erh)"),
        ("GoldenMelonCup_DESC", "Пуэр в форме тыквы, подарок императору. Тяжёлый, круглый, с дольками. Если совсем прижмёт, им можно кинуть в волка. Волк удивится, а ты останешься без чая. Не кидай.", "Pu-erh shaped like a pumpkin, a tribute to the emperor. Heavy, round, with segments. In a pinch you could throw it at a wolf. The wolf would be surprised and you would be out of tea. Don't."),
        ("DragonPearl_NAME", "Жемчужина дракона (пуэр лунчжу, шарик)", "Dragon Pearl (longzhu pu-erh ball)"),
        ("DragonPearl_DESC", "Шарик пуэра размером с каштан. Дракон хранит такую жемчужину под языком. У тебя драконов нет, есть медведь, и под язык к нему лучше не заглядывать. Заваривается на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "A ball of pu-erh the size of a chestnut. A dragon keeps a pearl like this under its tongue. You have no dragons, only a bear, and you had better not look under its tongue. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("DragonPearlCup_NAME", "Жемчужина дракона (пуэр лунчжу, шарик)", "Dragon Pearl (longzhu pu-erh ball)"),
        ("DragonPearlCup_DESC", "Шарик пуэра размером с каштан. Дракон хранит такую жемчужину под языком. У тебя драконов нет, есть медведь, и под язык к нему лучше не заглядывать.", "A ball of pu-erh the size of a chestnut. A dragon keeps a pearl like this under its tongue. You have no dragons, only a bear, and you had better not look under its tongue."),
        ("MoneyTea_NAME", "Чайная монета (корейский тон-ча)", "Money Tea (Korean doncha)"),
        ("MoneyTea_DESC", "Корейский чай в виде монеты с дыркой: нанизывали на верёвку и носили на поясе. Единственные деньги на острове, которые на что-то годятся. Доллары горят хуже. Заваривается на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "Korean tea shaped like a coin with a hole: threaded on a string and worn on the belt. The only money on the island that is good for anything. Dollar bills burn worse. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("MoneyTeaCup_NAME", "Чайная монета (корейский тон-ча)", "Money Tea (Korean doncha)"),
        ("MoneyTeaCup_DESC", "Корейский чай в виде монеты с дыркой: нанизывали на верёвку и носили на поясе. Единственные деньги на острове, которые на что-то годятся. Доллары горят хуже.", "Korean tea shaped like a coin with a hole: threaded on a string and worn on the belt. The only money on the island that is good for anything. Dollar bills burn worse."),
        ("TeaResin_NAME", "Чайная смола (ча гао, вываренный пуэр)", "Tea Resin (cha gao, pu-erh extract)"),
        ("TeaResin_DESC", "Пуэр, вываренный до чёрной смолы. Кусочек с ноготь на кружку. Придумали для путников, которым некогда. Тебе обычно тоже некогда: то метель, то кто-то рычит. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 20.", "Pu-erh boiled down to a black resin. A piece the size of a fingernail does a cup. Invented for travellers with no time. You are usually short of time too: either a blizzard or something growling. Brew it over a fire: put it in a pot with water. Servings: 20."),
        ("TeaResinCup_NAME", "Чайная смола (ча гао, вываренный пуэр)", "Tea Resin (cha gao, pu-erh extract)"),
        ("TeaResinCup_DESC", "Пуэр, вываренный до чёрной смолы. Кусочек с ноготь на кружку. Придумали для путников, которым некогда. Тебе обычно тоже некогда: то метель, то кто-то рычит.", "Pu-erh boiled down to a black resin. A piece the size of a fingernail does a cup. Invented for travellers with no time. You are usually short of time too: either a blizzard or something growling."),
        ("EldersBrow_NAME", "Брови старца (белый чай шоу мэй, блин)", "Elder's Brow (Shou Mei white tea cake)"),
        ("EldersBrow_DESC", "«Брови старца»: белый чай из крупных мохнатых листьев. Через месяц на острове у тебя будут точно такие же брови, только с инеем. Чай напоминает, к чему готовиться. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "'Elder's Brow': a white tea of big shaggy leaves. After a month on the island your own brows will look just like it, with added frost. The tea is letting you know what to expect. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("EldersBrowCup_NAME", "Брови старца (белый чай шоу мэй, блин)", "Elder's Brow (Shou Mei white tea cake)"),
        ("EldersBrowCup_DESC", "«Брови старца»: белый чай из крупных мохнатых листьев. Через месяц на острове у тебя будут точно такие же брови, только с инеем. Чай напоминает, к чему готовиться.", "'Elder's Brow': a white tea of big shaggy leaves. After a month on the island your own brows will look just like it, with added frost. The tea is letting you know what to expect."),
        ("WhitePeony_NAME", "Белый пион (белый чай бай му дань, блин)", "White Peony (Bai Mu Dan white tea cake)"),
        ("WhitePeony_DESC", "Белый пион: нежный, цветочный, требует воды ровно восемьдесят градусов. Ты льёшь кипяток из закопчённого котелка, и пион молча это терпит. Он воспитанный. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "White Peony: delicate, floral, demands water at precisely eighty degrees. You pour boiling water from a sooty pot, and the peony bears it in silence. It was raised well. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("WhitePeonyCup_NAME", "Белый пион (белый чай бай му дань, блин)", "White Peony (Bai Mu Dan white tea cake)"),
        ("WhitePeonyCup_DESC", "Белый пион: нежный, цветочный, требует воды ровно восемьдесят градусов. Ты льёшь кипяток из закопчённого котелка, и пион молча это терпит. Он воспитанный.", "White Peony: delicate, floral, demands water at precisely eighty degrees. You pour boiling water from a sooty pot, and the peony bears it in silence. It was raised well."),
        ("Moonlight_NAME", "Лунный свет (юэ гуан бай, блин)", "Moonlight (Yue Guang Bai cake)"),
        ("Moonlight_DESC", "Чай, который сушат ночью при луне, чтобы лист с одной стороны остался белым. Ты при луне обычно сушишь носки у костра. У каждого своё ремесло. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "A tea dried at night under the moon so one side of the leaf stays white. Under the moon you mostly dry socks by the fire. To each their own craft. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("MoonlightCup_NAME", "Лунный свет (юэ гуан бай, блин)", "Moonlight (Yue Guang Bai cake)"),
        ("MoonlightCup_DESC", "Чай, который сушат ночью при луне, чтобы лист с одной стороны остался белым. Ты при луне обычно сушишь носки у костра. У каждого своё ремесло.", "A tea dried at night under the moon so one side of the leaf stays white. Under the moon you mostly dry socks by the fire. To each their own craft."),
        ("DianhongRound_NAME", "Красный круг Дяньхун (красный чай дянь хун, блин)", "Dianhong Round (Dian Hong black tea cake)"),
        ("DianhongRound_DESC", "Красный чай из Юньнани, спрессованный в блин. Пахнет мёдом и печёной картошкой. Печёной картошки ты не ел так давно, что готов нюхать блин вместо ужина. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Red tea from Yunnan pressed into a cake. Smells of honey and baked potato. It has been so long since you ate a baked potato that you are ready to sniff the cake for supper. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("DianhongRoundCup_NAME", "Красный круг Дяньхун (красный чай дянь хун, блин)", "Dianhong Round (Dian Hong black tea cake)"),
        ("DianhongRoundCup_DESC", "Красный чай из Юньнани, спрессованный в блин. Пахнет мёдом и печёной картошкой. Печёной картошки ты не ел так давно, что готов нюхать блин вместо ужина.", "Red tea from Yunnan pressed into a cake. Smells of honey and baked potato. It has been so long since you ate a baked potato that you are ready to sniff the cake for supper."),
        ("ZhangpingNarcissus_NAME", "Нарцисс Чжанпин (прессованный улун шуй сянь)", "Zhangping Narcissus (pressed Shui Xian oolong)"),
        ("ZhangpingNarcissus_DESC", "Маленький квадратик улуна в бумажке, как ириска. Единственный улун, который прессуют деревянным молотком. Развернул, вспомнил детство, заварил. Ириски тут всё равно нет. Заваривается на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "A little square of oolong in a paper wrap, like a toffee. The only oolong pressed with a wooden mallet. Unwrap, remember childhood, brew. There is no toffee here anyway. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("ZhangpingNarcissusCup_NAME", "Нарцисс Чжанпин (прессованный улун шуй сянь)", "Zhangping Narcissus (pressed Shui Xian oolong)"),
        ("ZhangpingNarcissusCup_DESC", "Маленький квадратик улуна в бумажке, как ириска. Единственный улун, который прессуют деревянным молотком. Развернул, вспомнил детство, заварил. Ириски тут всё равно нет.", "A little square of oolong in a paper wrap, like a toffee. The only oolong pressed with a wooden mallet. Unwrap, remember childhood, brew. There is no toffee here anyway."),
        ("GoldenFlowers_NAME", "Золотые цветы (хэй ча фу чжуань)", "Golden Flowers (Fu Zhuan dark tea)"),
        ("GoldenFlowers_DESC", "Кирпич чёрного чая, внутри которого растёт золотая плесень, и это специально. За такую платят больше. Твоя банка персиков с похожим узором, увы, так не работает. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A brick of dark tea with golden mould growing inside, on purpose. People pay extra for it. Your tin of peaches with a similar pattern sadly does not work that way. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("GoldenFlowersCup_NAME", "Золотые цветы (хэй ча фу чжуань)", "Golden Flowers (Fu Zhuan dark tea)"),
        ("GoldenFlowersCup_DESC", "Кирпич чёрного чая, внутри которого растёт золотая плесень, и это специально. За такую платят больше. Твоя банка персиков с похожим узором, увы, так не работает.", "A brick of dark tea with golden mould growing inside, on purpose. People pay extra for it. Your tin of peaches with a similar pattern sadly does not work that way."),
        ("FlowerBrick_NAME", "Цветочный кирпич (хэй ча хуа чжуань)", "Flower Brick (Hua Zhuan dark tea)"),
        ("FlowerBrick_DESC", "Кирпич с выдавленным узором. Цветов внутри нет, название врёт. На острове к этому привыкаешь: «Отрадная долина» тоже звучит гостеприимнее, чем выглядит. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A brick with a pressed pattern. There are no flowers inside, the name lies. You get used to that on the island: 'Pleasant Valley' also sounds friendlier than it looks. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("FlowerBrickCup_NAME", "Цветочный кирпич (хэй ча хуа чжуань)", "Flower Brick (Hua Zhuan dark tea)"),
        ("FlowerBrickCup_DESC", "Кирпич с выдавленным узором. Цветов внутри нет, название врёт. На острове к этому привыкаешь: «Отрадная долина» тоже звучит гостеприимнее, чем выглядит.", "A brick with a pressed pattern. There are no flowers inside, the name lies. You get used to that on the island: 'Pleasant Valley' also sounds friendlier than it looks."),
        ("ThousandTaels_NAME", "Тысяча лянов (хэй ча цянь лян)", "Thousand Taels (Qian Liang dark tea)"),
        ("ThousandTaels_DESC", "Чайное бревно весом в тысячу лянов, его пилят пилой. Тебе досталось полено поменьше. Впервые в жизни смотришь на дрова и думаешь не «сжечь», а «заварить». Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 30.", "A log of tea weighing a thousand taels, cut with a saw. You got a smaller billet. For the first time in your life you look at firewood and think 'brew' instead of 'burn'. Brew it over a fire: put it in a pot with water. Servings: 30."),
        ("ThousandTaelsCup_NAME", "Тысяча лянов (хэй ча цянь лян)", "Thousand Taels (Qian Liang dark tea)"),
        ("ThousandTaelsCup_DESC", "Чайное бревно весом в тысячу лянов, его пилят пилой. Тебе досталось полено поменьше. Впервые в жизни смотришь на дрова и думаешь не «сжечь», а «заварить».", "A log of tea weighing a thousand taels, cut with a saw. You got a smaller billet. For the first time in your life you look at firewood and think 'brew' instead of 'burn'."),
        ("LiubaoBasket_NAME", "Корзина Любао (хэй ча любао)", "Liubao Basket (Liu Bao dark tea)"),
        ("LiubaoBasket_DESC", "Чёрный чай в плетёной корзине, пахнет бетелем и сырым погребом. Шахтёры пили его от сырости. Заходишь в шахту у Прибрежного шоссе и понимаешь шахтёров. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Dark tea in a wicker basket, smelling of betel nut and a damp cellar. Miners drank it against the damp. Walk into the mine off the Coastal Highway and you will see their point. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("LiubaoBasketCup_NAME", "Корзина Любао (хэй ча любао)", "Liubao Basket (Liu Bao dark tea)"),
        ("LiubaoBasketCup_DESC", "Чёрный чай в плетёной корзине, пахнет бетелем и сырым погребом. Шахтёры пили его от сырости. Заходишь в шахту у Прибрежного шоссе и понимаешь шахтёров.", "Dark tea in a wicker basket, smelling of betel nut and a damp cellar. Miners drank it against the damp. Walk into the mine off the Coastal Highway and you will see their point."),
        ("LiuanBasket_NAME", "Корзинка Люань (хэй ча люань)", "Liuan Basket (Liu'an basket tea)"),
        ("LiuanBasket_DESC", "Корзиночка чая, проложенная листьями бамбука. Её не открывают годами, чтобы созрела. Ты нашёл и открыл сразу. Терпение на острове тратится на другое. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "A little basket of tea lined with bamboo leaves. You are meant to leave it shut for years to mature. You found it and opened it at once. On the island patience is spent elsewhere. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("LiuanBasketCup_NAME", "Корзинка Люань (хэй ча люань)", "Liuan Basket (Liu'an basket tea)"),
        ("LiuanBasketCup_DESC", "Корзиночка чая, проложенная листьями бамбука. Её не открывают годами, чтобы созрела. Ты нашёл и открыл сразу. Терпение на острове тратится на другое.", "A little basket of tea lined with bamboo leaves. You are meant to leave it shut for years to mature. You found it and opened it at once. On the island patience is spent elsewhere."),
        ("HubeiGreenBrick_NAME", "Зелёный кирпич Хубэя (хэй ча цин чжуань)", "Hubei Green Brick (Qing Zhuan dark tea)"),
        ("HubeiGreenBrick_DESC", "Зелёный кирпич, грубый и честный. Его варили в котле с молоком пастухи. Он не притворяется изысканным, и ты рядом с ним тоже можешь не притворяться. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A green brick, coarse and honest. Herdsmen boiled it in a cauldron with milk. It does not pretend to be refined, and next to it you needn't pretend either. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("HubeiGreenBrickCup_NAME", "Зелёный кирпич Хубэя (хэй ча цин чжуань)", "Hubei Green Brick (Qing Zhuan dark tea)"),
        ("HubeiGreenBrickCup_DESC", "Зелёный кирпич, грубый и честный. Его варили в котле с молоком пастухи. Он не притворяется изысканным, и ты рядом с ним тоже можешь не притворяться.", "A green brick, coarse and honest. Herdsmen boiled it in a cauldron with milk. It does not pretend to be refined, and next to it you needn't pretend either."),
        ("HankouTile_NAME", "Плитка Ханькоу (ми чжуань, плиточный чёрный чай)", "Hankou Tile (Mi Zhuan pressed black tea)"),
        ("HankouTile_DESC", "Плитка из чайной пыли с красивым тиснением. Такими торговали с Сибирью. Сибиряк бы посмотрел на Великий Медведь, пожал плечами и спросил, где тут зима. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "A tile of tea dust with a handsome stamp. They traded these with Siberia. A Siberian would look at Great Bear, shrug and ask where the winter is. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("HankouTileCup_NAME", "Плитка Ханькоу (ми чжуань, плиточный чёрный чай)", "Hankou Tile (Mi Zhuan pressed black tea)"),
        ("HankouTileCup_DESC", "Плитка из чайной пыли с красивым тиснением. Такими торговали с Сибирью. Сибиряк бы посмотрел на Великий Медведь, пожал плечами и спросил, где тут зима.", "A tile of tea dust with a handsome stamp. They traded these with Siberia. A Siberian would look at Great Bear, shrug and ask where the winter is."),
        ("KangBrick_NAME", "Кирпич Кан (хэй ча кан чжуань)", "Kang Brick (Kang Zhuan dark tea)"),
        ("KangBrick_DESC", "Кирпич для Тибета: его везли на спинах носильщики через перевалы, по сто кило на человека. А ты ноешь из-за тридцати. Выпей и постыдись. Потом выложи из рюкзака лишний ломик. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A brick bound for Tibet: porters hauled it over the passes, two hundred pounds a man. And you whine about sixty. Drink and be ashamed. Then take the spare prybar out of your pack. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("KangBrickCup_NAME", "Кирпич Кан (хэй ча кан чжуань)", "Kang Brick (Kang Zhuan dark tea)"),
        ("KangBrickCup_DESC", "Кирпич для Тибета: его везли на спинах носильщики через перевалы, по сто кило на человека. А ты ноешь из-за тридцати. Выпей и постыдись. Потом выложи из рюкзака лишний ломик.", "A brick bound for Tibet: porters hauled it over the passes, two hundred pounds a man. And you whine about sixty. Drink and be ashamed. Then take the spare prybar out of your pack."),
        ("ColchisTile_NAME", "Плиточный «Колхида» (плиточный чёрный чай)", "Colchis Tile Tea (pressed black tea tile)"),
        ("ColchisTile_DESC", "Плиточный чай из тех, что лежали в каждом сельпо и в каждом рюкзаке геолога. Геологи на Великом Медведе тоже бывали. Судя по записке в пещере, чай кончился раньше, чем экспедиция. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Tile tea of the kind found in every village shop and every geologist's pack. Geologists visited Great Bear too. Going by the note in the cave, the tea ran out before the expedition did. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ColchisTileCup_NAME", "Плиточный «Колхида» (плиточный чёрный чай)", "Colchis Tile Tea (pressed black tea tile)"),
        ("ColchisTileCup_DESC", "Плиточный чай из тех, что лежали в каждом сельпо и в каждом рюкзаке геолога. Геологи на Великом Медведе тоже бывали. Судя по записке в пещере, чай кончился раньше, чем экспедиция.", "Tile tea of the kind found in every village shop and every geologist's pack. Geologists visited Great Bear too. Going by the note in the cave, the tea ran out before the expedition did."),
        ("SteppeBrick_NAME", "Кирпичный «Степной» (кирпичный зелёный чай)", "Steppe Brick Tea (green brick tea)"),
        ("SteppeBrick_DESC", "Кирпичный зелёный чай для степи: рубят топором, варят с солью. Тонкие ценители падают в обморок. Здесь тонких ценителей съели в первую неделю, так что вари смело. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Green brick tea for the steppe: chopped with an axe, boiled with salt. Connoisseurs faint. Here the connoisseurs got eaten in week one, so boil away. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("SteppeBrickCup_NAME", "Кирпичный «Степной» (кирпичный зелёный чай)", "Steppe Brick Tea (green brick tea)"),
        ("SteppeBrickCup_DESC", "Кирпичный зелёный чай для степи: рубят топором, варят с солью. Тонкие ценители падают в обморок. Здесь тонких ценителей съели в первую неделю, так что вари смело.", "Green brick tea for the steppe: chopped with an axe, boiled with salt. Connoisseurs faint. Here the connoisseurs got eaten in week one, so boil away."),
        ("KoporyeRound_NAME", "Копорский круг (прессованный иван-чай)", "Koporye Round (pressed fireweed tea)"),
        ("KoporyeRound_DESC", "Прессованный иван-чай, старинный копорский рецепт. Когда-то его продавали в Англию под видом китайского. На острове обманывать некого, пьём как есть и гордимся. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Pressed fireweed, the old Koporye recipe. It was once sold to England passed off as Chinese. There is nobody on the island to fool, so we drink it as is, with pride. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("KoporyeRoundCup_NAME", "Копорский круг (прессованный иван-чай)", "Koporye Round (pressed fireweed tea)"),
        ("KoporyeRoundCup_DESC", "Прессованный иван-чай, старинный копорский рецепт. Когда-то его продавали в Англию под видом китайского. На острове обманывать некого, пьём как есть и гордимся.", "Pressed fireweed, the old Koporye recipe. It was once sold to England passed off as Chinese. There is nobody on the island to fool, so we drink it as is, with pride."),
        ("AssamDawn_NAME", "Ассамский рассвет (чёрный чай ассам)", "Assam Dawn (Assam black tea)"),
        ("AssamDawn_DESC", "Ассам: густой, солодовый, цвета красного дерева. В Индии им будят целые города. Здесь он будит одного человека, и тот первым делом проверяет, не погасла ли печка. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Assam: thick, malty, the colour of mahogany. In India it wakes whole cities. Here it wakes one person, whose first move is to check the stove hasn't gone out. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("AssamDawnCup_NAME", "Ассамский рассвет (чёрный чай ассам)", "Assam Dawn (Assam black tea)"),
        ("AssamDawnCup_DESC", "Ассам: густой, солодовый, цвета красного дерева. В Индии им будят целые города. Здесь он будит одного человека, и тот первым делом проверяет, не погасла ли печка.", "Assam: thick, malty, the colour of mahogany. In India it wakes whole cities. Here it wakes one person, whose first move is to check the stove hasn't gone out."),
        ("DarjeelingFlush_NAME", "Первый сбор Дарджилинга (чёрный чай дарджилинг)", "Darjeeling First Flush (Darjeeling black tea)"),
        ("DarjeelingFlush_DESC", "Первый весенний сбор, «шампанское среди чаёв». Весну на Великом Медведе отменили, шампанское выпили до тебя. Осталась эта жестянка, и ей положено радоваться. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "The first spring flush, 'the champagne of teas'. Spring has been cancelled on Great Bear and somebody drank the champagne before you. This tin is what remains, and you are expected to be glad. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("DarjeelingFlushCup_NAME", "Первый сбор Дарджилинга (чёрный чай дарджилинг)", "Darjeeling First Flush (Darjeeling black tea)"),
        ("DarjeelingFlushCup_DESC", "Первый весенний сбор, «шампанское среди чаёв». Весну на Великом Медведе отменили, шампанское выпили до тебя. Осталась эта жестянка, и ей положено радоваться.", "The first spring flush, 'the champagne of teas'. Spring has been cancelled on Great Bear and somebody drank the champagne before you. This tin is what remains, and you are expected to be glad."),
        ("CeylonCrag_NAME", "Цейлонский утёс (цейлонский чай ува)", "Ceylon Crag (Ceylon Uva tea)"),
        ("CeylonCrag_DESC", "Чай с продуваемого утёса на Цейлоне: ветер делает лист терпким. Если бы ветер так работал с людьми, ты был бы самым терпким человеком в Канаде. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Tea from a windswept crag in Ceylon: the wind makes the leaf brisk. If wind worked like that on people, you would be the briskest person in Canada. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CeylonCragCup_NAME", "Цейлонский утёс (цейлонский чай ува)", "Ceylon Crag (Ceylon Uva tea)"),
        ("CeylonCragCup_DESC", "Чай с продуваемого утёса на Цейлоне: ветер делает лист терпким. Если бы ветер так работал с людьми, ты был бы самым терпким человеком в Канаде.", "Tea from a windswept crag in Ceylon: the wind makes the leaf brisk. If wind worked like that on people, you would be the briskest person in Canada."),
        ("ElephantPass_NAME", "Слоновий перевал (цейлонский оранж пеко)", "Elephant Pass (Ceylon Orange Pekoe)"),
        ("ElephantPass_DESC", "Оранж пеко с перевала, где дорогу переходят слоны. У тебя дорогу переходит лось. Слон хотя бы трубит заранее, а лось просто смотрит и решает твою судьбу. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Orange pekoe from a pass where elephants cross the road. Your road gets crossed by a moose. An elephant at least trumpets first, a moose just looks at you and decides your fate. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ElephantPassCup_NAME", "Слоновий перевал (цейлонский оранж пеко)", "Elephant Pass (Ceylon Orange Pekoe)"),
        ("ElephantPassCup_DESC", "Оранж пеко с перевала, где дорогу переходят слоны. У тебя дорогу переходит лось. Слон хотя бы трубит заранее, а лось просто смотрит и решает твою судьбу.", "Orange pekoe from a pass where elephants cross the road. Your road gets crossed by a moose. An elephant at least trumpets first, a moose just looks at you and decides your fate."),
        ("KeemunRed_NAME", "Красный Цимэнь (чёрный чай кимун)", "Keemun Red (Keemun black tea)"),
        ("KeemunRed_DESC", "Кимун: пахнет вином, сухофруктами и немного дымом. Английская королева пила его на день рождения. Ты пьёшь по случаю того, что пережил вторник. Повод не хуже. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Keemun: smells of wine, dried fruit and a little smoke. The Queen of England had it on her birthday. You are having it because you survived Tuesday. As good a reason as any. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("KeemunRedCup_NAME", "Красный Цимэнь (чёрный чай кимун)", "Keemun Red (Keemun black tea)"),
        ("KeemunRedCup_DESC", "Кимун: пахнет вином, сухофруктами и немного дымом. Английская королева пила его на день рождения. Ты пьёшь по случаю того, что пережил вторник. Повод не хуже.", "Keemun: smells of wine, dried fruit and a little smoke. The Queen of England had it on her birthday. You are having it because you survived Tuesday. As good a reason as any."),
        ("YunnanBuds_NAME", "Золотые почки Юньнани (красный чай дянь хун)", "Yunnan Golden Buds (Dian Hong black tea)"),
        ("YunnanBuds_DESC", "Одни золотые почки, мягкие, как шерсть. Настой сладкий, медовый. На острове золотое и мягкое обычно оказывается чьим-то хвостом, так что чай приятно удивляет. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Nothing but golden buds, soft as fur. The brew is sweet like honey. On the island anything golden and soft usually turns out to be somebody's tail, so the tea is a pleasant surprise. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("YunnanBudsCup_NAME", "Золотые почки Юньнани (красный чай дянь хун)", "Yunnan Golden Buds (Dian Hong black tea)"),
        ("YunnanBudsCup_DESC", "Одни золотые почки, мягкие, как шерсть. Настой сладкий, медовый. На острове золотое и мягкое обычно оказывается чьим-то хвостом, так что чай приятно удивляет.", "Nothing but golden buds, soft as fur. The brew is sweet like honey. On the island anything golden and soft usually turns out to be somebody's tail, so the tea is a pleasant surprise."),
        ("PineSmoke_NAME", "Сосновый дым (лапсанг сушонг)", "Pine Smoke (Lapsang Souchong)"),
        ("PineSmoke_DESC", "Чай, копчённый на сосновых дровах. Пахнет костром. Твоя куртка пахнет костром. Волосы, спальник и консервы пахнут костром. Теперь и чай. Полный комплект. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Tea smoked over pine wood. It smells of campfire. Your jacket smells of campfire. So do your hair, your bedroll and your tinned food. Now the tea as well. The set is complete. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("PineSmokeCup_NAME", "Сосновый дым (лапсанг сушонг)", "Pine Smoke (Lapsang Souchong)"),
        ("PineSmokeCup_DESC", "Чай, копчённый на сосновых дровах. Пахнет костром. Твоя куртка пахнет костром. Волосы, спальник и консервы пахнут костром. Теперь и чай. Полный комплект.", "Tea smoked over pine wood. It smells of campfire. Your jacket smells of campfire. So do your hair, your bedroll and your tinned food. Now the tea as well. The set is complete."),
        ("GoldenBrows_NAME", "Золотые брови (цзинь цзюнь мэй)", "Golden Brows (Jin Jun Mei)"),
        ("GoldenBrows_DESC", "На полкило этого чая идёт пятьдесят тысяч почек, сорванных вручную. Ты за день вручную срываешь пять стеблей рогоза и считаешь, что устал. Пей с уважением. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "A pound of this tea takes fifty thousand hand-picked buds. You hand-pick five cattail stalks a day and call it hard work. Drink with respect. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("GoldenBrowsCup_NAME", "Золотые брови (цзинь цзюнь мэй)", "Golden Brows (Jin Jun Mei)"),
        ("GoldenBrowsCup_DESC", "На полкило этого чая идёт пятьдесят тысяч почек, сорванных вручную. Ты за день вручную срываешь пять стеблей рогоза и считаешь, что устал. Пей с уважением.", "A pound of this tea takes fifty thousand hand-picked buds. You hand-pick five cattail stalks a day and call it hard work. Drink with respect."),
        ("Savanna_NAME", "Саванна (кенийский гранулированный чай)", "Savanna (Kenyan CTC tea)"),
        ("Savanna_DESC", "Кенийские гранулы: завариваются за минуту в чёрный, как ночь в саванне, настой. Там в темноте ходят львы. Здесь в темноте тоже кто-то ходит. Родная атмосфера. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Kenyan granules: one minute and the brew is black as a savanna night. Lions walk in the dark there. Something walks in the dark here too. Feels like home. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SavannaCup_NAME", "Саванна (кенийский гранулированный чай)", "Savanna (Kenyan CTC tea)"),
        ("SavannaCup_DESC", "Кенийские гранулы: завариваются за минуту в чёрный, как ночь в саванне, настой. Там в темноте ходят львы. Здесь в темноте тоже кто-то ходит. Родная атмосфера.", "Kenyan granules: one minute and the brew is black as a savanna night. Lions walk in the dark there. Something walks in the dark here too. Feels like home."),
        ("BlueHills_NAME", "Голубые горы (чёрный чай нилгири)", "Blue Hills (Nilgiri black tea)"),
        ("BlueHills_DESC", "Нилгири, «Голубые горы»: чай, который не мутнеет, когда остывает. Ценное свойство для места, где остывает всё и сразу. Хоть что-то останется прозрачным. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Nilgiri, the 'Blue Hills': a tea that does not cloud when it cools. A valuable trait in a place where everything cools at once. At least something stays clear. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("BlueHillsCup_NAME", "Голубые горы (чёрный чай нилгири)", "Blue Hills (Nilgiri black tea)"),
        ("BlueHillsCup_DESC", "Нилгири, «Голубые горы»: чай, который не мутнеет, когда остывает. Ценное свойство для места, где остывает всё и сразу. Хоть что-то останется прозрачным.", "Nilgiri, the 'Blue Hills': a tea that does not cloud when it cools. A valuable trait in a place where everything cools at once. At least something stays clear."),
        ("BatumiBouquet_NAME", "Батумский букет (грузинский чёрный чай)", "Batumi Bouquet (Georgian black tea)"),
        ("BatumiBouquet_DESC", "Грузинский чай с батумских склонов. Там пальмы, море и тост на сорок минут. Здесь ёлки, лёд и тост короткий: «Ну, чтоб не замёрзнуть». Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Georgian tea from the slopes above Batumi. Over there: palms, the sea and a forty-minute toast. Over here: firs, ice and a short toast: 'Well, here's to not freezing.' Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("BatumiBouquetCup_NAME", "Батумский букет (грузинский чёрный чай)", "Batumi Bouquet (Georgian black tea)"),
        ("BatumiBouquetCup_DESC", "Грузинский чай с батумских склонов. Там пальмы, море и тост на сорок минут. Здесь ёлки, лёд и тост короткий: «Ну, чтоб не замёрзнуть».", "Georgian tea from the slopes above Batumi. Over there: palms, the sea and a forty-minute toast. Over here: firs, ice and a short toast: 'Well, here's to not freezing.'"),
        ("SouthernSlope_NAME", "Южный склон (краснодарский чай)", "Southern Slope (Krasnodar tea)"),
        ("SouthernSlope_DESC", "Краснодарский: самый северный чай в мире. Гордится этим, как может. Потом его привезли на Великий Медведь, и чай узнал, что север бывает и посевернее. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Krasnodar tea: the northernmost tea in the world, and proud of it. Then it was shipped to Great Bear and learned that north can get a good deal norther. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("SouthernSlopeCup_NAME", "Южный склон (краснодарский чай)", "Southern Slope (Krasnodar tea)"),
        ("SouthernSlopeCup_DESC", "Краснодарский: самый северный чай в мире. Гордится этим, как может. Потом его привезли на Великий Медведь, и чай узнал, что север бывает и посевернее.", "Krasnodar tea: the northernmost tea in the world, and proud of it. Then it was shipped to Great Bear and learned that north can get a good deal norther."),
        ("LankaranArmudu_NAME", "Ленкоранский армуду (азербайджанский чай)", "Lankaran Armudu (Azerbaijani tea)"),
        ("LankaranArmudu_DESC", "Чай, который пьют из стаканчика в форме груши, вприкуску и не торопясь. Стаканчика нет, сахара нет, зато не торопиться тебе никто не мешает. Метель на трое суток. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "A tea drunk from a pear-shaped glass with a lump of sugar, unhurried. You have no glass and no sugar, but nobody is stopping you from taking your time. The blizzard is in for three days. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("LankaranArmuduCup_NAME", "Ленкоранский армуду (азербайджанский чай)", "Lankaran Armudu (Azerbaijani tea)"),
        ("LankaranArmuduCup_DESC", "Чай, который пьют из стаканчика в форме груши, вприкуску и не торопясь. Стаканчика нет, сахара нет, зато не торопиться тебе никто не мешает. Метель на трое суток.", "A tea drunk from a pear-shaped glass with a lump of sugar, unhurried. You have no glass and no sugar, but nobody is stopping you from taking your time. The blizzard is in for three days."),
        ("DoubleKettle_NAME", "Двойной чайник (турецкий чай ризе)", "Double Kettle (Turkish Rize tea)"),
        ("DoubleKettle_DESC", "Турецкий чай варят в двух чайниках, поставленных друг на друга. У тебя одна консервная банка, и ставить её не на что, кроме углей. Чай не обижается, турки бы обиделись. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Turkish tea is made in two kettles stacked one on the other. You have one food tin and nothing to stack it on but coals. The tea doesn't mind. The Turks would. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("DoubleKettleCup_NAME", "Двойной чайник (турецкий чай ризе)", "Double Kettle (Turkish Rize tea)"),
        ("DoubleKettleCup_DESC", "Турецкий чай варят в двух чайниках, поставленных друг на друга. У тебя одна консервная банка, и ставить её не на что, кроме углей. Чай не обижается, турки бы обиделись.", "Turkish tea is made in two kettles stacked one on the other. You have one food tin and nothing to stack it on but coals. The tea doesn't mind. The Turks would."),
        ("HeartyBreakfast_NAME", "Плотный завтрак (английский завтрак, пакетики)", "Hearty Breakfast (English Breakfast tea bags)"),
        ("HeartyBreakfast_DESC", "Английский завтрак: к нему положены яичница, бекон, фасоль и тост. У тебя к нему положены полбанки собачьих консервов. Чай делает вид, что не заметил. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "English breakfast: meant to go with eggs, bacon, beans and toast. Yours goes with half a tin of dog food. The tea pretends not to notice. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("HeartyBreakfastCup_NAME", "Плотный завтрак (английский завтрак, пакетики)", "Hearty Breakfast (English Breakfast tea bags)"),
        ("HeartyBreakfastCup_DESC", "Английский завтрак: к нему положены яичница, бекон, фасоль и тост. У тебя к нему положены полбанки собачьих консервов. Чай делает вид, что не заметил.", "English breakfast: meant to go with eggs, bacon, beans and toast. Yours goes with half a tin of dog food. The tea pretends not to notice."),
        ("DublinDock_NAME", "Дублинский док (ирландский завтрак)", "Dublin Dock (Irish Breakfast tea)"),
        ("DublinDock_DESC", "Ирландский завтрак: такой крепкий, что ложка стоит. Докеры пили его перед сменой в тумане и холоде. У тебя туман и холод без смены, круглосуточно. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Irish breakfast: strong enough to stand a spoon in. Dockers drank it before a shift in the fog and cold. You get the fog and cold with no shift change, around the clock. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("DublinDockCup_NAME", "Дублинский док (ирландский завтрак)", "Dublin Dock (Irish Breakfast tea)"),
        ("DublinDockCup_DESC", "Ирландский завтрак: такой крепкий, что ложка стоит. Докеры пили его перед сменой в тумане и холоде. У тебя туман и холод без смены, круглосуточно.", "Irish breakfast: strong enough to stand a spoon in. Dockers drank it before a shift in the fog and cold. You get the fog and cold with no shift change, around the clock."),
        ("SiamSunset_NAME", "Сиамский закат (тайский чай)", "Siam Sunset (Thai tea mix)"),
        ("SiamSunset_DESC", "Тайский чай: оранжевый, как закат над Бангкоком, со сгущёнкой и льдом. Лёд у тебя свой, закат в четыре часа дня, и после него лучше быть за дверью. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Thai tea: orange as a Bangkok sunset, with condensed milk and ice. You have your own ice, sunset is at four in the afternoon, and you had better be indoors after it. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SiamSunsetCup_NAME", "Сиамский закат (тайский чай)", "Siam Sunset (Thai tea mix)"),
        ("SiamSunsetCup_DESC", "Тайский чай: оранжевый, как закат над Бангкоком, со сгущёнкой и льдом. Лёд у тебя свой, закат в четыре часа дня, и после него лучше быть за дверью.", "Thai tea: orange as a Bangkok sunset, with condensed milk and ice. You have your own ice, sunset is at four in the afternoon, and you had better be indoors after it."),
        ("SilkStocking_NAME", "Шёлковый чулок (гонконгский молочный чай)", "Silk Stocking (Hong Kong milk tea)"),
        ("SilkStocking_DESC", "Гонконгский чай, который процеживают через мешок, похожий на чулок. Отсюда название. Нет, не настоящий. Да, ты тоже подумал про свои носки у печки. Нет, не надо. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Hong Kong tea strained through a bag that looks like a stocking. Hence the name. No, not a real one. Yes, you also thought of your socks by the stove. No, don't. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("SilkStockingCup_NAME", "Шёлковый чулок (гонконгский молочный чай)", "Silk Stocking (Hong Kong milk tea)"),
        ("SilkStockingCup_DESC", "Гонконгский чай, который процеживают через мешок, похожий на чулок. Отсюда название. Нет, не настоящий. Да, ты тоже подумал про свои носки у печки. Нет, не надо.", "Hong Kong tea strained through a bag that looks like a stocking. Hence the name. No, not a real one. Yes, you also thought of your socks by the stove. No, don't."),
        ("PinkKashmir_NAME", "Розовый Кашмир (кашмирский нун-чай)", "Pink Kashmir (Kashmiri noon chai)"),
        ("PinkKashmir_DESC", "Розовый чай с солью и содой, его пьют в Гималаях. Да, розовый. Да, солёный. Последнее розовое, что ты видел: собственное ухо перед обморожением. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Pink tea with salt and soda, drunk in the Himalayas. Yes, pink. Yes, salty. The last pink thing you saw was your own ear just before the frostbite. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("PinkKashmirCup_NAME", "Розовый Кашмир (кашмирский нун-чай)", "Pink Kashmir (Kashmiri noon chai)"),
        ("PinkKashmirCup_DESC", "Розовый чай с солью и содой, его пьют в Гималаях. Да, розовый. Да, солёный. Последнее розовое, что ты видел: собственное ухо перед обморожением.", "Pink tea with salt and soda, drunk in the Himalayas. Yes, pink. Yes, salty. The last pink thing you saw was your own ear just before the frostbite."),
        ("SaffronKahwa_NAME", "Шафрановая кахва (кашмирская кахва)", "Saffron Kahwa (Kashmiri kahwa)"),
        ("SaffronKahwa_DESC", "Зелёный чай с шафраном, миндалём и кардамоном. Шафран дороже золота. Ты нашёл его в шкафчике над раковиной, рядом со спичками. На острове спички дороже. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Green tea with saffron, almond and cardamom. Saffron costs more than gold. You found it in the cupboard over the sink, next to the matches. On the island the matches are worth more. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("SaffronKahwaCup_NAME", "Шафрановая кахва (кашмирская кахва)", "Saffron Kahwa (Kashmiri kahwa)"),
        ("SaffronKahwaCup_DESC", "Зелёный чай с шафраном, миндалём и кардамоном. Шафран дороже золота. Ты нашёл его в шкафчике над раковиной, рядом со спичками. На острове спички дороже.", "Green tea with saffron, almond and cardamom. Saffron costs more than gold. You found it in the cupboard over the sink, next to the matches. On the island the matches are worth more."),
        ("MaghrebWhisper_NAME", "Шёпот Магриба (марокканский мятный чай)", "Maghreb Whisper (Moroccan mint tea)"),
        ("MaghrebWhisper_DESC", "Мятный чай льют с высоты, чтобы была пена: чем выше струя, тем больше уважения к гостю. Гостей у тебя не бывает. Но можешь уважить себя, только не ошпарься. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Mint tea is poured from a height to raise a froth: the higher the stream, the greater the respect for the guest. You never have guests. Respect yourself, then, just mind the scalding. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("MaghrebWhisperCup_NAME", "Шёпот Магриба (марокканский мятный чай)", "Maghreb Whisper (Moroccan mint tea)"),
        ("MaghrebWhisperCup_DESC", "Мятный чай льют с высоты, чтобы была пена: чем выше струя, тем больше уважения к гостю. Гостей у тебя не бывает. Но можешь уважить себя, только не ошпарься.", "Mint tea is poured from a height to raise a froth: the higher the stream, the greater the respect for the guest. You never have guests. Respect yourself, then, just mind the scalding."),
        ("JasminePearl_NAME", "Жасминовая жемчужина (жасминовый чай)", "Jasmine Pearl (jasmine pearl tea)"),
        ("JasminePearl_DESC", "Чайные листья скручены в шарики и семь ночей лежали с цветами жасмина. В кружке они раскрываются. Единственное, что на этом острове раскрывается добровольно. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Tea leaves rolled into pearls and laid with jasmine blossoms for seven nights. In the cup they unfurl. The only thing on this island that opens up willingly. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("JasminePearlCup_NAME", "Жасминовая жемчужина (жасминовый чай)", "Jasmine Pearl (jasmine pearl tea)"),
        ("JasminePearlCup_DESC", "Чайные листья скручены в шарики и семь ночей лежали с цветами жасмина. В кружке они раскрываются. Единственное, что на этом острове раскрывается добровольно.", "Tea leaves rolled into pearls and laid with jasmine blossoms for seven nights. In the cup they unfurl. The only thing on this island that opens up willingly."),
        ("HotayLotus_NAME", "Лотос Хотай (вьетнамский лотосовый чай)", "Ho Tay Lotus (Vietnamese lotus tea)"),
        ("HotayLotus_DESC", "Чай на ночь прячут в цветок лотоса, утром достают. На одну жестянку уходит тысяча цветков с озера. С твоего озера можно достать разве что окуня, и тот против. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "The tea is hidden inside a lotus blossom overnight and taken out at dawn. One tin takes a thousand flowers from the lake. All your lake gives up is a bass, and it objects. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("HotayLotusCup_NAME", "Лотос Хотай (вьетнамский лотосовый чай)", "Ho Tay Lotus (Vietnamese lotus tea)"),
        ("HotayLotusCup_DESC", "Чай на ночь прячут в цветок лотоса, утром достают. На одну жестянку уходит тысяча цветков с озера. С твоего озера можно достать разве что окуня, и тот против.", "The tea is hidden inside a lotus blossom overnight and taken out at dawn. One tin takes a thousand flowers from the lake. All your lake gives up is a bass, and it objects."),
        ("SpringWell_NAME", "Весенний колодец (лунцзин)", "Spring Well (Longjing (Dragon Well))"),
        ("SpringWell_DESC", "Лунцзин, «Колодец дракона»: плоские листики, жареные в котле руками. Пахнет каштаном и весной. Весну придётся брать на веру, а колодец здесь один, и он замёрз. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Longjing, 'Dragon Well': flat little leaves pan-fired by hand. Smells of chestnut and spring. You will have to take spring on trust, and the only well around here is frozen. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SpringWellCup_NAME", "Весенний колодец (лунцзин)", "Spring Well (Longjing (Dragon Well))"),
        ("SpringWellCup_DESC", "Лунцзин, «Колодец дракона»: плоские листики, жареные в котле руками. Пахнет каштаном и весной. Весну придётся брать на веру, а колодец здесь один, и он замёрз.", "Longjing, 'Dragon Well': flat little leaves pan-fired by hand. Smells of chestnut and spring. You will have to take spring on trust, and the only well around here is frozen."),
        ("EmeraldSpiral_NAME", "Изумрудная спираль (би ло чунь)", "Emerald Spiral (Bi Luo Chun)"),
        ("EmeraldSpiral_DESC", "Крошечные спиральки с фруктовым запахом: чай растёт между персиковых деревьев. Персики на острове бывают только в банках, и вспоминать о них сейчас больно. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Tiny spirals with a fruity scent: the tea grows among peach trees. Peaches on the island come only in tins, and it hurts to think about them right now. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("EmeraldSpiralCup_NAME", "Изумрудная спираль (би ло чунь)", "Emerald Spiral (Bi Luo Chun)"),
        ("EmeraldSpiralCup_DESC", "Крошечные спиральки с фруктовым запахом: чай растёт между персиковых деревьев. Персики на острове бывают только в банках, и вспоминать о них сейчас больно.", "Tiny spirals with a fruity scent: the tea grows among peach trees. Peaches on the island come only in tins, and it hurts to think about them right now."),
        ("GreenShot_NAME", "Зелёная картечь (ганпаудер)", "Green Shot (gunpowder green tea)"),
        ("GreenShot_DESC", "Ганпаудер, «порох»: лист скатан в дробинки. В кипятке они разворачиваются с лёгким треском. Самые безопасные боеприпасы на острове, жаль, медведь их не боится. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Gunpowder: the leaf is rolled into pellets. In hot water they open with a faint crackle. The safest ammunition on the island, a pity the bear isn't scared of it. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("GreenShotCup_NAME", "Зелёная картечь (ганпаудер)", "Green Shot (gunpowder green tea)"),
        ("GreenShotCup_DESC", "Ганпаудер, «порох»: лист скатан в дробинки. В кипятке они разворачиваются с лёгким треском. Самые безопасные боеприпасы на острове, жаль, медведь их не боится.", "Gunpowder: the leaf is rolled into pellets. In hot water they open with a faint crackle. The safest ammunition on the island, a pity the bear isn't scared of it."),
        ("YellowMountain_NAME", "Жёлтая гора (хуаншань маофэн)", "Yellow Mountain (Huangshan Maofeng)"),
        ("YellowMountain_DESC", "Чай с Жёлтой горы, где сосны растут из скал, а художники рисуют туман. Здесь сосны тоже растут из скал, но художников нет: краски замёрзли, натурщики кусаются. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Tea from the Yellow Mountain, where pines grow from the rock and painters paint the mist. Pines grow from the rock here too, but no painters: the paint froze and the models bite. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("YellowMountainCup_NAME", "Жёлтая гора (хуаншань маофэн)", "Yellow Mountain (Huangshan Maofeng)"),
        ("YellowMountainCup_DESC", "Чай с Жёлтой горы, где сосны растут из скал, а художники рисуют туман. Здесь сосны тоже растут из скал, но художников нет: краски замёрзли, натурщики кусаются.", "Tea from the Yellow Mountain, where pines grow from the rock and painters paint the mist. Pines grow from the rock here too, but no painters: the paint froze and the models bite."),
        ("MonkeyChief_NAME", "Обезьяний вождь (тайпин хоу куй)", "Monkey Chief (Taiping Houkui)"),
        ("MonkeyChief_DESC", "Листья по семь сантиметров, расплющены между сетками. По легенде, чай сажали обезьяны на недоступных скалах. На Великом Медведе на недоступные скалы лезешь ты. Выводы делай сам. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Leaves three inches long, pressed flat between screens. Legend says monkeys planted the tea on unreachable cliffs. On Great Bear the one climbing unreachable cliffs is you. Draw your own conclusions. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("MonkeyChiefCup_NAME", "Обезьяний вождь (тайпин хоу куй)", "Monkey Chief (Taiping Houkui)"),
        ("MonkeyChiefCup_DESC", "Листья по семь сантиметров, расплющены между сетками. По легенде, чай сажали обезьяны на недоступных скалах. На Великом Медведе на недоступные скалы лезешь ты. Выводы делай сам.", "Leaves three inches long, pressed flat between screens. Legend says monkeys planted the tea on unreachable cliffs. On Great Bear the one climbing unreachable cliffs is you. Draw your own conclusions."),
        ("MelonSeed_NAME", "Тыквенные семечки (люань гуапянь)", "Melon Seed (Lu'an Guapian)"),
        ("MelonSeed_DESC", "Чай из одних листьев, без почек и стеблей, по форме как тыквенная семечка. Есть его не надо, даже если очень хочется. А хочется здесь всегда. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "A tea of leaves only, no buds and no stems, shaped like melon seeds. You are not supposed to eat it, however tempted. And on this island you are always tempted. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("MelonSeedCup_NAME", "Тыквенные семечки (люань гуапянь)", "Melon Seed (Lu'an Guapian)"),
        ("MelonSeedCup_DESC", "Чай из одних листьев, без почек и стеблей, по форме как тыквенная семечка. Есть его не надо, даже если очень хочется. А хочется здесь всегда.", "A tea of leaves only, no buds and no stems, shaped like melon seeds. You are not supposed to eat it, however tempted. And on this island you are always tempted."),
        ("AnjiWhiteLeaf_NAME", "Белый лист Аньцзи (аньцзи бай ча)", "Anji White Leaf (Anji Bai Cha)"),
        ("AnjiWhiteLeaf_DESC", "Зелёный чай с белым листом: куст бледнеет на холоде. Тут вы похожи. Только он от этого становится сладким и дорогим, а ты просто бледным. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "A green tea with a white leaf: the bush goes pale in the cold. You two have that in common. Except it turns sweet and expensive, and you just turn pale. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("AnjiWhiteLeafCup_NAME", "Белый лист Аньцзи (аньцзи бай ча)", "Anji White Leaf (Anji Bai Cha)"),
        ("AnjiWhiteLeafCup_DESC", "Зелёный чай с белым листом: куст бледнеет на холоде. Тут вы похожи. Только он от этого становится сладким и дорогим, а ты просто бледным.", "A green tea with a white leaf: the bush goes pale in the cold. You two have that in common. Except it turns sweet and expensive, and you just turn pale."),
        ("ShizuokaMorning_NAME", "Утро Сидзуоки (сэнтя)", "Shizuoka Morning (sencha)"),
        ("ShizuokaMorning_DESC", "Сэнтя с видом на Фудзи: свежая, травяная, пахнет морем. Заваривать полагается в тишине. С тишиной на острове полный порядок, иногда даже слишком. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Sencha with a view of Mount Fuji: fresh, grassy, smelling of the sea. It is meant to be brewed in silence. Silence is one thing the island has plenty of, sometimes too much. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ShizuokaMorningCup_NAME", "Утро Сидзуоки (сэнтя)", "Shizuoka Morning (sencha)"),
        ("ShizuokaMorningCup_DESC", "Сэнтя с видом на Фудзи: свежая, травяная, пахнет морем. Заваривать полагается в тишине. С тишиной на острове полный порядок, иногда даже слишком.", "Sencha with a view of Mount Fuji: fresh, grassy, smelling of the sea. It is meant to be brewed in silence. Silence is one thing the island has plenty of, sometimes too much."),
        ("JadeDew_NAME", "Нефритовая роса (гёкуро)", "Jade Dew (gyokuro)"),
        ("JadeDew_DESC", "Гёкуро три недели растёт в тени под навесом и от этого становится сладким. Ты третью неделю живёшь в тени под навесом и становишься только подозрительным. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Gyokuro spends three weeks growing in shade under a canopy and turns sweet. You have spent three weeks in the shade under a roof and have only turned suspicious. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("JadeDewCup_NAME", "Нефритовая роса (гёкуро)", "Jade Dew (gyokuro)"),
        ("JadeDewCup_DESC", "Гёкуро три недели растёт в тени под навесом и от этого становится сладким. Ты третью неделю живёшь в тени под навесом и становишься только подозрительным.", "Gyokuro spends three weeks growing in shade under a canopy and turns sweet. You have spent three weeks in the shade under a roof and have only turned suspicious."),
        ("GreenFroth_NAME", "Зелёная пена (матча)", "Green Froth (matcha)"),
        ("GreenFroth_DESC", "Матча: чайный порошок, который взбивают бамбуковым венчиком до пены. Венчика нет. Есть вилка и злость. Пена получается хуже, зато с характером. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "Matcha: powdered tea whisked to a froth with a bamboo whisk. You have no whisk. You have a fork and some anger. The froth is poorer but has character. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("GreenFrothCup_NAME", "Зелёная пена (матча)", "Green Froth (matcha)"),
        ("GreenFrothCup_DESC", "Матча: чайный порошок, который взбивают бамбуковым венчиком до пены. Венчика нет. Есть вилка и злость. Пена получается хуже, зато с характером.", "Matcha: powdered tea whisked to a froth with a bamboo whisk. You have no whisk. You have a fork and some anger. The froth is poorer but has character."),
        ("RiceCrackle_NAME", "Рисовый хруст (гэнмайтя)", "Rice Crackle (genmaicha)"),
        ("RiceCrackle_DESC", "Зелёный чай с жареным рисом, часть зёрен лопнула, как попкорн. Придумали бедняки, чтобы чая хватало дольше. На острове ты и есть бедняк, так что рецепт твой. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Green tea with toasted rice, some grains popped like popcorn. Invented by the poor to make the tea go further. On the island the poor means you, so the recipe is yours. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("RiceCrackleCup_NAME", "Рисовый хруст (гэнмайтя)", "Rice Crackle (genmaicha)"),
        ("RiceCrackleCup_DESC", "Зелёный чай с жареным рисом, часть зёрен лопнула, как попкорн. Придумали бедняки, чтобы чая хватало дольше. На острове ты и есть бедняк, так что рецепт твой.", "Green tea with toasted rice, some grains popped like popcorn. Invented by the poor to make the tea go further. On the island the poor means you, so the recipe is yours."),
        ("KyotoEmbers_NAME", "Угольки Киото (ходзитя)", "Kyoto Embers (hojicha)"),
        ("KyotoEmbers_DESC", "Чай, обжаренный на углях до коричневого цвета. Почти без кофеина, пьют перед сном. Угли у тебя есть и свои, но рядом с ними лучше не засыпать. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Tea roasted over charcoal until brown. Next to no caffeine, drunk before bed. You have embers of your own, though they are better watched than slept beside unattended. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("KyotoEmbersCup_NAME", "Угольки Киото (ходзитя)", "Kyoto Embers (hojicha)"),
        ("KyotoEmbersCup_DESC", "Чай, обжаренный на углях до коричневого цвета. Почти без кофеина, пьют перед сном. Угли у тебя есть и свои, но рядом с ними лучше не засыпать.", "Tea roasted over charcoal until brown. Next to no caffeine, drunk before bed. You have embers of your own, though they are better watched than slept beside unattended."),
        ("ThreeTwigs_NAME", "Три веточки (кукитя)", "Three Twigs (kukicha)"),
        ("ThreeTwigs_DESC", "Чай из веточек и черешков, которые остались от хорошего чая. Японцы не выбрасывают ничего. Ты теперь тоже: вчера полчаса решал, нужна ли тебе пустая банка. Нужна. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "A tea of the twigs and stalks left over from the good tea. The Japanese throw nothing away. Neither do you now: yesterday you spent half an hour deciding whether you need an empty tin. You do. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ThreeTwigsCup_NAME", "Три веточки (кукитя)", "Three Twigs (kukicha)"),
        ("ThreeTwigsCup_DESC", "Чай из веточек и черешков, которые остались от хорошего чая. Японцы не выбрасывают ничего. Ты теперь тоже: вчера полчаса решал, нужна ли тебе пустая банка. Нужна.", "A tea of the twigs and stalks left over from the good tea. The Japanese throw nothing away. Neither do you now: yesterday you spent half an hour deciding whether you need an empty tin. You do."),
        ("SparrowTongue_NAME", "Воробьиный язычок (корейский сэджак)", "Sparrow's Tongue (Korean sejak)"),
        ("SparrowTongue_DESC", "Корейский чай из листочков размером с язык воробья. Воробьёв на острове нет, есть вороны. Язык вороны лучше не измерять: она запомнит и расскажет остальным. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Korean tea from leaves the size of a sparrow's tongue. The island has no sparrows, only crows. Better not measure a crow's tongue: it will remember and tell the others. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SparrowTongueCup_NAME", "Воробьиный язычок (корейский сэджак)", "Sparrow's Tongue (Korean sejak)"),
        ("SparrowTongueCup_DESC", "Корейский чай из листочков размером с язык воробья. Воробьёв на острове нет, есть вороны. Язык вороны лучше не измерять: она запомнит и расскажет остальным.", "Korean tea from leaves the size of a sparrow's tongue. The island has no sparrows, only crows. Better not measure a crow's tongue: it will remember and tell the others."),
        ("JunshanIsle_NAME", "Остров Цзюньшань (жёлтый чай цзюньшань иньчжэнь)", "Junshan Isle (Junshan Yinzhen yellow tea)"),
        ("JunshanIsle_DESC", "Жёлтый чай с крошечного острова посреди озера. Почки в стакане встают торчком и трижды всплывают. Ты на своём острове тоже трижды всплывал, из проруби. Чай изящнее. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Yellow tea from a tiny island in a lake. The buds stand upright in the glass and rise three times. You have also come up three times on your island, out of a hole in the ice. The tea does it with more grace. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("JunshanIsleCup_NAME", "Остров Цзюньшань (жёлтый чай цзюньшань иньчжэнь)", "Junshan Isle (Junshan Yinzhen yellow tea)"),
        ("JunshanIsleCup_DESC", "Жёлтый чай с крошечного острова посреди озера. Почки в стакане встают торчком и трижды всплывают. Ты на своём острове тоже трижды всплывал, из проруби. Чай изящнее.", "Yellow tea from a tiny island in a lake. The buds stand upright in the glass and rise three times. You have also come up three times on your island, out of a hole in the ice. The tea does it with more grace."),
        ("YellowSprout_NAME", "Жёлтый росток (жёлтый чай хошань хуанъя)", "Yellow Sprout (Huoshan Huangya yellow tea)"),
        ("YellowSprout_DESC", "Жёлтый чай: его «томят» под тканью, пока не пожелтеет. Редкость даже в Китае. Как он оказался в охотничьем домике, знает только прежний хозяин, а он уже не расскажет. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Yellow tea: 'smothered' under cloth until it yellows. Rare even in China. How it ended up in a hunting lodge only the former owner knows, and he is past telling. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("YellowSproutCup_NAME", "Жёлтый росток (жёлтый чай хошань хуанъя)", "Yellow Sprout (Huoshan Huangya yellow tea)"),
        ("YellowSproutCup_DESC", "Жёлтый чай: его «томят» под тканью, пока не пожелтеет. Редкость даже в Китае. Как он оказался в охотничьем домике, знает только прежний хозяин, а он уже не расскажет.", "Yellow tea: 'smothered' under cloth until it yellows. Rare even in China. How it ended up in a hunting lodge only the former owner knows, and he is past telling."),
        ("IronMercy_NAME", "Железная милость (те гуаньинь)", "Iron Mercy (Tieguanyin)"),
        ("IronMercy_DESC", "Те гуаньинь, «Железная богиня милосердия». Милосердие на Великом Медведе выдают редко и только в чайной форме. Бери, пока есть: метель железнее. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Tie Guanyin, the 'Iron Goddess of Mercy'. Mercy on Great Bear is issued rarely and only in tea form. Take it while it lasts: the blizzard is made of harder iron. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("IronMercyCup_NAME", "Железная милость (те гуаньинь)", "Iron Mercy (Tieguanyin)"),
        ("IronMercyCup_DESC", "Те гуаньинь, «Железная богиня милосердия». Милосердие на Великом Медведе выдают редко и только в чайной форме. Бери, пока есть: метель железнее.", "Tie Guanyin, the 'Iron Goddess of Mercy'. Mercy on Great Bear is issued rarely and only in tea form. Take it while it lasts: the blizzard is made of harder iron."),
        ("ScarletRobe_NAME", "Алая мантия (да хун пао)", "Scarlet Robe (Da Hong Pao)"),
        ("ScarletRobe_DESC", "Да хун пао, «Большой красный халат»: по легенде, кусты укрыли мантией императора в благодарность. Тебя бы кто укрыл. Ты согласен даже на оленью шкуру. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Da Hong Pao, 'Big Red Robe': legend says the bushes were draped in the emperor's robe as thanks. If only someone would drape you. You would settle for a deer hide. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ScarletRobeCup_NAME", "Алая мантия (да хун пао)", "Scarlet Robe (Da Hong Pao)"),
        ("ScarletRobeCup_DESC", "Да хун пао, «Большой красный халат»: по легенде, кусты укрыли мантией императора в благодарность. Тебя бы кто укрыл. Ты согласен даже на оленью шкуру.", "Da Hong Pao, 'Big Red Robe': legend says the bushes were draped in the emperor's robe as thanks. If only someone would drape you. You would settle for a deer hide."),
        ("LoneBush_NAME", "Одинокий куст (фэнхуан дань цун)", "Lone Bush (Fenghuang Dan Cong)"),
        ("LoneBush_DESC", "Улун с одиночных кустов: каждый куст собирают отдельно, у каждого свой запах. Одинокий, сам по себе, с непростым характером. Вы с ним поладите. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Oolong from single bushes: each one picked separately, each with its own scent. A loner, on its own, with a difficult character. You two will get along. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("LoneBushCup_NAME", "Одинокий куст (фэнхуан дань цун)", "Lone Bush (Fenghuang Dan Cong)"),
        ("LoneBushCup_DESC", "Улун с одиночных кустов: каждый куст собирают отдельно, у каждого свой запах. Одинокий, сам по себе, с непростым характером. Вы с ним поладите.", "Oolong from single bushes: each one picked separately, each with its own scent. A loner, on its own, with a difficult character. You two will get along."),
        ("FrozenPeak_NAME", "Морозный пик (дун дин)", "Frozen Peak (Dong Ding oolong)"),
        ("FrozenPeak_DESC", "Дун дин, «Морозная вершина». На Тайване так назвали гору, где зимой бывает плюс пять. Привезите этих людей на Волчью гору, пусть придумают название ей. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Dong Ding, 'Frozen Peak'. In Taiwan that is what they call a mountain where winter means five above. Bring those people to Timberwolf Mountain and let them name that. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("FrozenPeakCup_NAME", "Морозный пик (дун дин)", "Frozen Peak (Dong Ding oolong)"),
        ("FrozenPeakCup_DESC", "Дун дин, «Морозная вершина». На Тайване так назвали гору, где зимой бывает плюс пять. Привезите этих людей на Волчью гору, пусть придумают название ей.", "Dong Ding, 'Frozen Peak'. In Taiwan that is what they call a mountain where winter means five above. Bring those people to Timberwolf Mountain and let them name that."),
        ("HighMist_NAME", "Высокогорный туман (алишань)", "High Mountain Mist (Alishan oolong)"),
        ("HighMist_DESC", "Улун с высоты, где кусты полдня стоят в облаке. Сливочный, цветочный. Ты тоже вчера полдня простоял в облаке на вершине, но сливочным не стал. Стал мокрым. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Oolong from heights where the bushes stand in cloud half the day. Creamy, floral. You stood in a cloud on the summit for half of yesterday too and did not come out creamy. You came out wet. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("HighMistCup_NAME", "Высокогорный туман (алишань)", "High Mountain Mist (Alishan oolong)"),
        ("HighMistCup_DESC", "Улун с высоты, где кусты полдня стоят в облаке. Сливочный, цветочный. Ты тоже вчера полдня простоял в облаке на вершине, но сливочным не стал. Стал мокрым.", "Oolong from heights where the bushes stand in cloud half the day. Creamy, floral. You stood in a cloud on the summit for half of yesterday too and did not come out creamy. You came out wet."),
        ("FiveColours_NAME", "Пятицветная красавица (дунфан мэйжэнь)", "Five-Colour Beauty (Oriental Beauty oolong)"),
        ("FiveColours_DESC", "Этот чай сначала должны покусать цикадки, иначе не будет медового вкуса. Редкий случай, когда укусы идут на пользу. С волками такая схема не работает, не проверяй. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "This tea has to be bitten by leafhoppers first, or there is no honey taste. A rare case of bites doing good. The scheme does not work with wolves, do not test it. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("FiveColoursCup_NAME", "Пятицветная красавица (дунфан мэйжэнь)", "Five-Colour Beauty (Oriental Beauty oolong)"),
        ("FiveColoursCup_DESC", "Этот чай сначала должны покусать цикадки, иначе не будет медового вкуса. Редкий случай, когда укусы идут на пользу. С волками такая схема не работает, не проверяй.", "This tea has to be bitten by leafhoppers first, or there is no honey taste. A rare case of bites doing good. The scheme does not work with wolves, do not test it."),
        ("GoldenDaylily_NAME", "Золотая лилия (молочный улун цзинь сюань)", "Golden Daylily (Jin Xuan milk oolong)"),
        ("GoldenDaylily_DESC", "Молочный улун: пахнет сливками, хотя молока в нём нет. Корову на острове ты тоже не найдёшь. Единственное молочное на сто километров, и то понарошку. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Milk oolong: smells of cream though there is no milk in it. You won't find a cow on the island either. The only dairy for sixty miles, and even that is make-believe. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("GoldenDaylilyCup_NAME", "Золотая лилия (молочный улун цзинь сюань)", "Golden Daylily (Jin Xuan milk oolong)"),
        ("GoldenDaylilyCup_DESC", "Молочный улун: пахнет сливками, хотя молока в нём нет. Корову на острове ты тоже не найдёшь. Единственное молочное на сто километров, и то понарошку.", "Milk oolong: smells of cream though there is no milk in it. You won't find a cow on the island either. The only dairy for sixty miles, and even that is make-believe."),
        ("CliffCinnamon_NAME", "Утёсная корица (жоу гуй)", "Cliff Cinnamon (Rou Gui)"),
        ("CliffCinnamon_DESC", "Утёсный улун, пахнет корицей и горячим камнем. Корицы в нём нет, камень настоящий. Скалы тут у тебя тоже настоящие, но пахнут они только неприятностями. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "A cliff oolong that smells of cinnamon and hot stone. There is no cinnamon in it, the stone is real. Your cliffs are real too, but all they smell of is trouble. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CliffCinnamonCup_NAME", "Утёсная корица (жоу гуй)", "Cliff Cinnamon (Rou Gui)"),
        ("CliffCinnamonCup_DESC", "Утёсный улун, пахнет корицей и горячим камнем. Корицы в нём нет, камень настоящий. Скалы тут у тебя тоже настоящие, но пахнут они только неприятностями.", "A cliff oolong that smells of cinnamon and hot stone. There is no cinnamon in it, the stone is real. Your cliffs are real too, but all they smell of is trouble."),
        ("QuietOolong_NAME", "Тихий улун (габа-улун)", "Quiet Oolong (GABA oolong)"),
        ("QuietOolong_DESC", "Габа-улун: японцы придумали его, чтобы люди меньше нервничали. Отличная идея. Сообщите её тому, кто ходит ночью вокруг хижины и скребёт дверь. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "GABA oolong: the Japanese invented it so people would worry less. A fine idea. Kindly pass it on to whatever circles the cabin at night scratching the door. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("QuietOolongCup_NAME", "Тихий улун (габа-улун)", "Quiet Oolong (GABA oolong)"),
        ("QuietOolongCup_DESC", "Габа-улун: японцы придумали его, чтобы люди меньше нервничали. Отличная идея. Сообщите её тому, кто ходит ночью вокруг хижины и скребёт дверь.", "GABA oolong: the Japanese invented it so people would worry less. A fine idea. Kindly pass it on to whatever circles the cabin at night scratching the door."),
        ("TeaBarn_NAME", "Чайный амбар (рассыпной шу пуэр)", "Tea Barn (loose shou pu-erh)"),
        ("TeaBarn_DESC", "Мешок рассыпного шу пуэра, пахнет старым амбаром. В хорошем смысле. На острове ты ночевал в амбарах и можешь подтвердить: чай пахнет лучше оригинала. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A sack of loose shou pu-erh that smells of an old barn. In a good way. You have slept in barns on the island and can confirm: the tea smells better than the original. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("TeaBarnCup_NAME", "Чайный амбар (рассыпной шу пуэр)", "Tea Barn (loose shou pu-erh)"),
        ("TeaBarnCup_DESC", "Мешок рассыпного шу пуэра, пахнет старым амбаром. В хорошем смысле. На острове ты ночевал в амбарах и можешь подтвердить: чай пахнет лучше оригинала.", "A sack of loose shou pu-erh that smells of an old barn. In a good way. You have slept in barns on the island and can confirm: the tea smells better than the original."),
        ("CederbergBush_NAME", "Красный куст Седерберга (ройбуш)", "Cederberg Red Bush (rooibos)"),
        ("CederbergBush_DESC", "Ройбуш из Южной Африки: красный, сладковатый, без кофеина. Вырос там, где снега не видели никогда. Сейчас он смотрит на тебя из кружки и ничего не понимает. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Rooibos from South Africa: red, sweetish, caffeine-free. It grew where nobody has ever seen snow. It is now looking up at you from the cup, utterly baffled. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CederbergBushCup_NAME", "Красный куст Седерберга (ройбуш)", "Cederberg Red Bush (rooibos)"),
        ("CederbergBushCup_DESC", "Ройбуш из Южной Африки: красный, сладковатый, без кофеина. Вырос там, где снега не видели никогда. Сейчас он смотрит на тебя из кружки и ничего не понимает.", "Rooibos from South Africa: red, sweetish, caffeine-free. It grew where nobody has ever seen snow. It is now looking up at you from the cup, utterly baffled."),
        ("CapeBee_NAME", "Капская пчела (ханибуш)", "Cape Bee (honeybush)"),
        ("CapeBee_DESC", "Ханибуш цветёт так, что на запах слетаются все пчёлы мыса. Пчёл на Великом Медведе нет. Мёда тоже нет. Есть этот пакет и воспоминания о бутерброде. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Honeybush blooms so sweetly that every bee on the Cape comes flying. Great Bear has no bees. No honey either. It has this packet and the memory of toast. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("CapeBeeCup_NAME", "Капская пчела (ханибуш)", "Cape Bee (honeybush)"),
        ("CapeBeeCup_DESC", "Ханибуш цветёт так, что на запах слетаются все пчёлы мыса. Пчёл на Великом Медведе нет. Мёда тоже нет. Есть этот пакет и воспоминания о бутерброде.", "Honeybush blooms so sweetly that every bee on the Cape comes flying. Great Bear has no bees. No honey either. It has this packet and the memory of toast."),
        ("TropicStalk_NAME", "Тропический стебель (лемонграсс)", "Tropic Stalk (lemongrass tea)"),
        ("TropicStalk_DESC", "Лемонграсс: лимонный запах без единого лимона. В тропиках им отпугивают комаров. Здесь комаров отпугнул мороз, примерно навсегда. Хоть какая-то польза от климата. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Lemongrass: the smell of lemon without a single lemon. In the tropics it keeps mosquitoes away. Here the frost saw to the mosquitoes, more or less for good. The climate is useful for something. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("TropicStalkCup_NAME", "Тропический стебель (лемонграсс)", "Tropic Stalk (lemongrass tea)"),
        ("TropicStalkCup_DESC", "Лемонграсс: лимонный запах без единого лимона. В тропиках им отпугивают комаров. Здесь комаров отпугнул мороз, примерно навсегда. Хоть какая-то польза от климата.", "Lemongrass: the smell of lemon without a single lemon. In the tropics it keeps mosquitoes away. Here the frost saw to the mosquitoes, more or less for good. The climate is useful for something."),
        ("ProvenceVerveine_NAME", "Вербена Прованса (лимонная вербена)", "Provence Verveine (lemon verbena)"),
        ("ProvenceVerveine_DESC", "Вербену во Франции пьют после ужина, на террасе, под стрекот цикад. У тебя после ужина терраса заметена, стрекочет только счётчик в голове: дров на четыре часа. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "In France verbena is drunk after dinner, on the terrace, to the sound of cicadas. After your dinner the terrace is snowed under, and the only ticking is in your head: four hours of firewood left. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ProvenceVerveineCup_NAME", "Вербена Прованса (лимонная вербена)", "Provence Verveine (lemon verbena)"),
        ("ProvenceVerveineCup_DESC", "Вербену во Франции пьют после ужина, на террасе, под стрекот цикад. У тебя после ужина терраса заметена, стрекочет только счётчик в голове: дров на четыре часа.", "In France verbena is drunk after dinner, on the terrace, to the sound of cicadas. After your dinner the terrace is snowed under, and the only ticking is in your head: four hours of firewood left."),
        ("JulyLinden_NAME", "Июльская липа (липовый цвет)", "July Linden (linden blossom tea)"),
        ("JulyLinden_DESC", "Липовый цвет, собранный в июле. Июль: это когда тепло, жужжат пчёлы и можно ходить без трёх свитеров. На острове звучит как сказка, поэтому пей и не перебивай. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Linden blossom gathered in July. July: that is when it is warm, bees hum and you can go about without three sweaters. On the island it sounds like a fairy tale, so drink and don't interrupt. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("JulyLindenCup_NAME", "Июльская липа (липовый цвет)", "July Linden (linden blossom tea)"),
        ("JulyLindenCup_DESC", "Липовый цвет, собранный в июле. Июль: это когда тепло, жужжат пчёлы и можно ходить без трёх свитеров. На острове звучит как сказка, поэтому пей и не перебивай.", "Linden blossom gathered in July. July: that is when it is warm, bees hum and you can go about without three sweaters. On the island it sounds like a fairy tale, so drink and don't interrupt."),
        ("PassThyme_NAME", "Чабрец с перевала (чай с чабрецом)", "Pass Thyme (thyme tea)"),
        ("PassThyme_DESC", "Чабрец собирали на горном перевале, на солнцепёке. Здешний перевал знаменит другим: с него сдувает. Завари покрепче и никуда сегодня не ходи. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "The thyme was gathered on a mountain pass, in full sun. The local pass is famous for something else: it blows you off. Brew it strong and go nowhere today. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("PassThymeCup_NAME", "Чабрец с перевала (чай с чабрецом)", "Pass Thyme (thyme tea)"),
        ("PassThymeCup_DESC", "Чабрец собирали на горном перевале, на солнцепёке. Здешний перевал знаменит другим: с него сдувает. Завари покрепче и никуда сегодня не ходи.", "The thyme was gathered on a mountain pass, in full sun. The local pass is famous for something else: it blows you off. Brew it strong and go nowhere today."),
        ("MeadowOregano_NAME", "Луговая душица (чай с душицей)", "Meadow Oregano (oregano tea)"),
        ("MeadowOregano_DESC", "Душица с летнего луга. Бабушка говорила: «от нервов». У бабушки нервы были из-за соседки. У тебя из-за медведя. Доза, видимо, нужна побольше. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Oregano from a summer meadow. Grandma said it was 'for the nerves'. Grandma's nerves were about the neighbour. Yours are about a bear. You may need a bigger dose. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("MeadowOreganoCup_NAME", "Луговая душица (чай с душицей)", "Meadow Oregano (oregano tea)"),
        ("MeadowOreganoCup_DESC", "Душица с летнего луга. Бабушка говорила: «от нервов». У бабушки нервы были из-за соседки. У тебя из-за медведя. Доза, видимо, нужна побольше.", "Oregano from a summer meadow. Grandma said it was 'for the nerves'. Grandma's nerves were about the neighbour. Yours are about a bear. You may need a bigger dose."),
        ("ShepherdsTea_NAME", "Пастуший чай Олимпа (греческий горный чай)", "Olympus Shepherd's Tea (Greek mountain tea)"),
        ("ShepherdsTea_DESC", "Горный чай: пастухи на Олимпе пьют его всю зиму и не болеют. Правда, у них есть овцы, сыр и боги по соседству. У тебя из соседей только ворона. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Mountain tea: the shepherds of Olympus drink it all winter and never fall ill. Mind you, they have sheep, cheese and gods next door. Your only neighbour is a crow. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ShepherdsTeaCup_NAME", "Пастуший чай Олимпа (греческий горный чай)", "Olympus Shepherd's Tea (Greek mountain tea)"),
        ("ShepherdsTeaCup_DESC", "Горный чай: пастухи на Олимпе пьют его всю зиму и не болеют. Правда, у них есть овцы, сыр и боги по соседству. У тебя из соседей только ворона.", "Mountain tea: the shepherds of Olympus drink it all winter and never fall ill. Mind you, they have sheep, cheese and gods next door. Your only neighbour is a crow."),
        ("BuckthornNoon_NAME", "Облепиховый полдень (облепиховый чай)", "Buckthorn Noon (sea buckthorn tea)"),
        ("BuckthornNoon_DESC", "Облепиха: оранжевая, кислая, витаминов больше, чем букв в слове «авитаминоз». После месяца на консервах организм узнаёт её и плачет от счастья. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Sea buckthorn: orange, sour, with more vitamins than there are letters in 'deficiency'. After a month of tinned food your body recognises it and weeps for joy. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("BuckthornNoonCup_NAME", "Облепиховый полдень (облепиховый чай)", "Buckthorn Noon (sea buckthorn tea)"),
        ("BuckthornNoonCup_DESC", "Облепиха: оранжевая, кислая, витаминов больше, чем букв в слове «авитаминоз». После месяца на консервах организм узнаёт её и плачет от счастья.", "Sea buckthorn: orange, sour, with more vitamins than there are letters in 'deficiency'. After a month of tinned food your body recognises it and weeps for joy."),
        ("DachaCurrant_NAME", "Дачная смородина (смородиновый лист)", "Dacha Currant (blackcurrant leaf tea)"),
        ("DachaCurrant_DESC", "Смородиновый лист с дачи. Пахнет летом, грядками и бабушкиным «надень панамку». Здесь панамку заменяет балаклава, а грядки лежат под двумя метрами снега. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Currant leaf from the summer cottage. Smells of summer, vegetable beds and grandma's 'put your sun hat on'. Here the sun hat is a balaclava and the beds are under six feet of snow. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("DachaCurrantCup_NAME", "Дачная смородина (смородиновый лист)", "Dacha Currant (blackcurrant leaf tea)"),
        ("DachaCurrantCup_DESC", "Смородиновый лист с дачи. Пахнет летом, грядками и бабушкиным «надень панамку». Здесь панамку заменяет балаклава, а грядки лежат под двумя метрами снега.", "Currant leaf from the summer cottage. Smells of summer, vegetable beds and grandma's 'put your sun hat on'. Here the sun hat is a balaclava and the beds are under six feet of snow."),
        ("AltaiBergenia_NAME", "Чёрный бадан Алтая (чигирский чай из бадана)", "Altai Bergenia (Chigir tea of bergenia)"),
        ("AltaiBergenia_DESC", "Бадан: листья должны перезимовать под снегом и почернеть, только тогда из них выходит чай. На острове под снегом зимует вообще всё. Жаль, заваривается не всё. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Bergenia: the leaves must winter under the snow and turn black before they make tea. On the island everything winters under the snow. A pity not all of it brews. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("AltaiBergeniaCup_NAME", "Чёрный бадан Алтая (чигирский чай из бадана)", "Altai Bergenia (Chigir tea of bergenia)"),
        ("AltaiBergeniaCup_DESC", "Бадан: листья должны перезимовать под снегом и почернеть, только тогда из них выходит чай. На острове под снегом зимует вообще всё. Жаль, заваривается не всё.", "Bergenia: the leaves must winter under the snow and turn black before they make tea. On the island everything winters under the snow. A pity not all of it brews."),
        ("SayanWing_NAME", "Белое крыло Саян (саган-дайля)", "Sayan White Wing (sagan dailya)"),
        ("SayanWing_DESC", "Саган-дайля: охотники в Саянах кладут один листик на чайник и потом идут за зверем сутки. Положишь три: пойдёшь двое суток, причём не туда. Один листик. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Sagan dailya: hunters in the Sayan mountains put one leaf in the pot and then track game for a day. Put in three and you will walk for two days, the wrong way. One leaf. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("SayanWingCup_NAME", "Белое крыло Саян (саган-дайля)", "Sayan White Wing (sagan dailya)"),
        ("SayanWingCup_DESC", "Саган-дайля: охотники в Саянах кладут один листик на чайник и потом идут за зверем сутки. Положишь три: пойдёшь двое суток, причём не туда. Один листик.", "Sagan dailya: hunters in the Sayan mountains put one leaf in the pot and then track game for a day. Put in three and you will walk for two days, the wrong way. One leaf."),
        ("Cinquefoil_NAME", "Пятилистник (курильский чай)", "Cinquefoil (Kuril tea)"),
        ("Cinquefoil_DESC", "Курильский чай: кустик, который растёт там, где больше никто не хочет. Камни, ветер, холод. Если бы он рос на Великом Медведе, вы бы здоровались. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Kuril tea: a little shrub that grows where nothing else wants to. Rock, wind, cold. If it grew on Great Bear, you two would be on nodding terms. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("CinquefoilCup_NAME", "Пятилистник (курильский чай)", "Cinquefoil (Kuril tea)"),
        ("CinquefoilCup_DESC", "Курильский чай: кустик, который растёт там, где больше никто не хочет. Камни, ветер, холод. Если бы он рос на Великом Медведе, вы бы здоровались.", "Kuril tea: a little shrub that grows where nothing else wants to. Rock, wind, cold. If it grew on Great Bear, you two would be on nodding terms."),
        ("MeadowQueen_NAME", "Королева лугов (таволга)", "Queen of the Meadow (meadowsweet tea)"),
        ("MeadowQueen_DESC", "Таволга: пахнет мёдом и миндалём, из неё когда-то впервые получили аспирин. Королева лугов и первая таблетка в истории. От встречи с лосем, правда, не поможет. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Meadowsweet: smells of honey and almond, and aspirin was first made from it. Queen of the meadow and history's first pill. It won't help against meeting a moose, though. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("MeadowQueenCup_NAME", "Королева лугов (таволга)", "Queen of the Meadow (meadowsweet tea)"),
        ("MeadowQueenCup_DESC", "Таволга: пахнет мёдом и миндалём, из неё когда-то впервые получили аспирин. Королева лугов и первая таблетка в истории. От встречи с лосем, правда, не поможет.", "Meadowsweet: smells of honey and almond, and aspirin was first made from it. Queen of the meadow and history's first pill. It won't help against meeting a moose, though."),
        ("HeatherMoor_NAME", "Вересковая пустошь (вересковый чай)", "Heather Moor (heather tea)"),
        ("HeatherMoor_DESC", "Вереск с шотландских пустошей: туман, ветер, ни души на мили вокруг. Шотландец на Великом Медведе почувствовал бы себя дома и пожаловался бы только на отсутствие виски. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Heather from the Scottish moors: fog, wind, not a soul for miles. A Scot on Great Bear would feel right at home and complain only about the lack of whisky. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("HeatherMoorCup_NAME", "Вересковая пустошь (вересковый чай)", "Heather Moor (heather tea)"),
        ("HeatherMoorCup_DESC", "Вереск с шотландских пустошей: туман, ветер, ни души на мили вокруг. Шотландец на Великом Медведе почувствовал бы себя дома и пожаловался бы только на отсутствие виски.", "Heather from the Scottish moors: fog, wind, not a soul for miles. A Scot on Great Bear would feel right at home and complain only about the lack of whisky."),
        ("JuneElder_NAME", "Июньская бузина (цветки бузины)", "June Elder (elderflower tea)"),
        ("JuneElder_DESC", "Цветки бузины, собранные в июне, пахнут мускатом и началом каникул. До каникул тебе осталось пережить зиму. Какую по счёту, уже не спрашивай. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Elderflowers gathered in June smell of muscat and the start of the holidays. All that stands between you and the holidays is one winter. Don't ask which one in a row. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("JuneElderCup_NAME", "Июньская бузина (цветки бузины)", "June Elder (elderflower tea)"),
        ("JuneElderCup_DESC", "Цветки бузины, собранные в июне, пахнут мускатом и началом каникул. До каникул тебе осталось пережить зиму. Какую по счёту, уже не спрашивай.", "Elderflowers gathered in June smell of muscat and the start of the holidays. All that stands between you and the holidays is one winter. Don't ask which one in a row."),
        ("BeeBalm_NAME", "Пчелиная трава (мелисса, пакетики)", "Bee Balm (lemon balm tea bags)"),
        ("BeeBalm_DESC", "Мелисса: лимонная, мягкая, от неё тянет зевать. Вся пачка шепчет: «ляг, поспи». Совет хороший, но сначала подбрось дров и проверь, заперта ли дверь. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Lemon balm: citrusy, gentle, makes you yawn. The whole box whispers 'lie down, have a nap'. Sound advice, but feed the fire first and check the door is shut. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("BeeBalmCup_NAME", "Пчелиная трава (мелисса, пакетики)", "Bee Balm (lemon balm tea bags)"),
        ("BeeBalmCup_DESC", "Мелисса: лимонная, мягкая, от неё тянет зевать. Вся пачка шепчет: «ляг, поспи». Совет хороший, но сначала подбрось дров и проверь, заперта ли дверь.", "Lemon balm: citrusy, gentle, makes you yawn. The whole box whispers 'lie down, have a nap'. Sound advice, but feed the fire first and check the door is shut."),
        ("TulsiMorning_NAME", "Утро туласи (туласи, священный базилик)", "Tulsi Morning (tulsi (holy basil) tea)"),
        ("TulsiMorning_DESC", "Туласи, священный базилик: в Индии растёт у каждого дома и охраняет его. Твой дом охраняет сломанный замок и табуретка под дверной ручкой. Базилик не помешает. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Tulsi, holy basil: in India it grows by every house and guards it. Your house is guarded by a broken lock and a stool wedged under the door handle. Some basil wouldn't hurt. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("TulsiMorningCup_NAME", "Утро туласи (туласи, священный базилик)", "Tulsi Morning (tulsi (holy basil) tea)"),
        ("TulsiMorningCup_DESC", "Туласи, священный базилик: в Индии растёт у каждого дома и охраняет его. Твой дом охраняет сломанный замок и табуретка под дверной ручкой. Базилик не помешает.", "Tulsi, holy basil: in India it grows by every house and guards it. Your house is guarded by a broken lock and a stool wedged under the door handle. Some basil wouldn't hurt."),
        ("ImmortalHerb_NAME", "Трава бессмертия (цзяогулань)", "Immortality Herb (jiaogulan)"),
        ("ImmortalHerb_DESC", "Цзяогулань, «трава бессмертия»: в деревне, где её пьют, полно столетних стариков. Правда, в той деревне нет ни волков, ни метелей. Но попытаться стоит. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Jiaogulan, the 'herb of immortality': the village that drinks it is full of hundred-year-olds. Granted, that village has no wolves and no blizzards. Still worth a try. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ImmortalHerbCup_NAME", "Трава бессмертия (цзяогулань)", "Immortality Herb (jiaogulan)"),
        ("ImmortalHerbCup_DESC", "Цзяогулань, «трава бессмертия»: в деревне, где её пьют, полно столетних стариков. Правда, в той деревне нет ни волков, ни метелей. Но попытаться стоит.", "Jiaogulan, the 'herb of immortality': the village that drinks it is full of hundred-year-olds. Granted, that village has no wolves and no blizzards. Still worth a try."),
        ("PingyinRose_NAME", "Бутоны Пинъинь (бутоны розы)", "Pingyin Rosebuds (rosebud tea)"),
        ("PingyinRose_DESC", "Целые бутоны розы в жестянке. В кипятке распускаются, пахнут садом. Ты неделю не мылся, спишь в медвежьей шкуре и пьёшь чай из роз. Жизнь полна контрастов. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Whole rosebuds in a tin. They open in hot water and smell of a garden. You haven't washed in a week, you sleep in a bearskin and you drink tea made of roses. Life is full of contrast. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("PingyinRoseCup_NAME", "Бутоны Пинъинь (бутоны розы)", "Pingyin Rosebuds (rosebud tea)"),
        ("PingyinRoseCup_DESC", "Целые бутоны розы в жестянке. В кипятке распускаются, пахнут садом. Ты неделю не мылся, спишь в медвежьей шкуре и пьёшь чай из роз. Жизнь полна контрастов.", "Whole rosebuds in a tin. They open in hot water and smell of a garden. You haven't washed in a week, you sleep in a bearskin and you drink tea made of roses. Life is full of contrast."),
        ("AutumnChrys_NAME", "Осенняя хризантема (хризантемовый чай)", "Autumn Chrysanthemum (chrysanthemum tea)"),
        ("AutumnChrys_DESC", "Хризантемы в Китае пьют поэты, глядя на осеннюю луну. Здесь осень длилась полтора дня. Луна есть, поэтов нет, стихи приходится сочинять самому. Рифма к «мороз»: «мороз». Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "In China poets drink chrysanthemum while gazing at the autumn moon. Autumn here lasted a day and a half. There is a moon and no poets, so you write your own. Rhyme for 'frost': 'frost'. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("AutumnChrysCup_NAME", "Осенняя хризантема (хризантемовый чай)", "Autumn Chrysanthemum (chrysanthemum tea)"),
        ("AutumnChrysCup_DESC", "Хризантемы в Китае пьют поэты, глядя на осеннюю луну. Здесь осень длилась полтора дня. Луна есть, поэтов нет, стихи приходится сочинять самому. Рифма к «мороз»: «мороз».", "In China poets drink chrysanthemum while gazing at the autumn moon. Autumn here lasted a day and a half. There is a moon and no poets, so you write your own. Rhyme for 'frost': 'frost'."),
        ("BlueMoth_NAME", "Синий мотылёк (анчан, синий чай)", "Blue Moth (butterfly pea tea)"),
        ("BlueMoth_DESC", "Чай синего цвета. Капнешь кислого: станет фиолетовым. Почти как небо в ночь сияния, только чай не включает старые радиоприёмники и не злит волков. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "A tea that is blue. Add something sour and it turns violet. Much like the sky on an aurora night, except this does not switch on old radios or anger the wolves. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("BlueMothCup_NAME", "Синий мотылёк (анчан, синий чай)", "Blue Moth (butterfly pea tea)"),
        ("BlueMothCup_DESC", "Чай синего цвета. Капнешь кислого: станет фиолетовым. Почти как небо в ночь сияния, только чай не включает старые радиоприёмники и не злит волков.", "A tea that is blue. Add something sour and it turns violet. Much like the sky on an aurora night, except this does not switch on old radios or anger the wolves."),
        ("BitterNeedle_NAME", "Горькая игла (кудин)", "Bitter Needle (kuding)"),
        ("BitterNeedle_DESC", "Кудин: лист скручен в иглу, и он горький. Нет, ты не понял. Очень горький. Один на кружку. Китайцы говорят, потом сладко. «Потом» наступает после десяти минут страданий. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Kuding: the leaf is twisted into a needle, and it is bitter. No, you don't follow. Very bitter. One per cup. The Chinese say sweetness comes after. After arrives following ten minutes of suffering. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("BitterNeedleCup_NAME", "Горькая игла (кудин)", "Bitter Needle (kuding)"),
        ("BitterNeedleCup_DESC", "Кудин: лист скручен в иглу, и он горький. Нет, ты не понял. Очень горький. Один на кружку. Китайцы говорят, потом сладко. «Потом» наступает после десяти минут страданий.", "Kuding: the leaf is twisted into a needle, and it is bitter. No, you don't follow. Very bitter. One per cup. The Chinese say sweetness comes after. After arrives following ten minutes of suffering."),
        ("PinkTrumpet_NAME", "Розовая труба (лапачо)", "Pink Trumpet (lapacho)"),
        ("PinkTrumpet_DESC", "Лапачо: кора дерева, которое цветёт розовыми трубами. Инки пили её от всех болезней. От волчьих укусов в списке ничего нет, но инки с волками и не встречались. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Lapacho: the bark of a tree that flowers in pink trumpets. The Incas drank it for every ailment. Wolf bites are not on the list, but then the Incas never met wolves. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("PinkTrumpetCup_NAME", "Розовая труба (лапачо)", "Pink Trumpet (lapacho)"),
        ("PinkTrumpetCup_DESC", "Лапачо: кора дерева, которое цветёт розовыми трубами. Инки пили её от всех болезней. От волчьих укусов в списке ничего нет, но инки с волками и не встречались.", "Lapacho: the bark of a tree that flowers in pink trumpets. The Incas drank it for every ailment. Wolf bites are not on the list, but then the Incas never met wolves."),
        ("NightWatchman_NAME", "Ночной страж (гуаюса)", "Night Watchman (guayusa)"),
        ("NightWatchman_DESC", "Гуаюса: индейцы пьют её ночью, чтобы не спать на охоте и вовремя заметить ягуара. Ягуара нет, но принцип тот же. Сторож из тебя после кружки выходит приличный. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Guayusa: forest hunters drink it at night to stay awake and spot the jaguar in time. No jaguars here, but the principle stands. After a cup you make a decent watchman. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("NightWatchmanCup_NAME", "Ночной страж (гуаюса)", "Night Watchman (guayusa)"),
        ("NightWatchmanCup_DESC", "Гуаюса: индейцы пьют её ночью, чтобы не спать на охоте и вовремя заметить ягуара. Ягуара нет, но принцип тот же. Сторож из тебя после кружки выходит приличный.", "Guayusa: forest hunters drink it at night to stay awake and spot the jaguar in time. No jaguars here, but the principle stands. After a cup you make a decent watchman."),
        ("Cassina_NAME", "Кассина (яупон)", "Cassina (yaupon)"),
        ("Cassina_DESC", "Яупон: единственный куст с кофеином, который растёт в Северной Америке. Почти земляк. До Великого Медведя он, правда, не дошёл. Умный куст. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Yaupon: the only caffeinated shrub native to North America. Practically a local. It never made it as far as Great Bear, though. Smart shrub. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CassinaCup_NAME", "Кассина (яупон)", "Cassina (yaupon)"),
        ("CassinaCup_DESC", "Яупон: единственный куст с кофеином, который растёт в Северной Америке. Почти земляк. До Великого Медведя он, правда, не дошёл. Умный куст.", "Yaupon: the only caffeinated shrub native to North America. Practically a local. It never made it as far as Great Bear, though. Smart shrub."),
        ("ToastedGaucho_NAME", "Жареный гаучо (обжаренный мате)", "Toasted Gaucho (roasted mate)"),
        ("ToastedGaucho_DESC", "Мате, обжаренный на огне: горчинка, дымок, вкус костра в пампе. Гаучо у костра поёт под гитару. Ты у костра молчишь и считаешь патроны. Оба при деле. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Mate toasted over a fire: a little bitter, a little smoky, the taste of a campfire on the pampas. The gaucho by his fire sings to a guitar. You by yours sit quiet and count cartridges. Both gainfully occupied. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ToastedGauchoCup_NAME", "Жареный гаучо (обжаренный мате)", "Toasted Gaucho (roasted mate)"),
        ("ToastedGauchoCup_DESC", "Мате, обжаренный на огне: горчинка, дымок, вкус костра в пампе. Гаучо у костра поёт под гитару. Ты у костра молчишь и считаешь патроны. Оба при деле.", "Mate toasted over a fire: a little bitter, a little smoky, the taste of a campfire on the pampas. The gaucho by his fire sings to a guitar. You by yours sit quiet and count cartridges. Both gainfully occupied."),
        ("SilkLeaf_NAME", "Шелковичный лист (чай из листьев шелковицы)", "Silk Leaf (mulberry leaf tea)"),
        ("SilkLeaf_DESC", "Листья шелковицы: ими кормят шелкопрядов, а что не съели, заваривают. Сладкий, травяной. Шёлка с него не получится, но носки из кролика тоже неплохи. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Mulberry leaves: fed to silkworms, and what the worms leave gets brewed. Sweet, grassy. It won't give you silk, but rabbit-skin socks aren't bad either. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("SilkLeafCup_NAME", "Шелковичный лист (чай из листьев шелковицы)", "Silk Leaf (mulberry leaf tea)"),
        ("SilkLeafCup_DESC", "Листья шелковицы: ими кормят шелкопрядов, а что не съели, заваривают. Сладкий, травяной. Шёлка с него не получится, но носки из кролика тоже неплохи.", "Mulberry leaves: fed to silkworms, and what the worms leave gets brewed. Sweet, grassy. It won't give you silk, but rabbit-skin socks aren't bad either."),
        ("GoldenBuckwheat_NAME", "Золотая гречиха (гречишный чай)", "Golden Buckwheat (buckwheat tea)"),
        ("GoldenBuckwheat_DESC", "Жареная гречиха, которую заваривают как чай. Пахнет печеньем. Потом зёрна можно съесть. Чай и закуска в одной упаковке: на острове это называется «пир». Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Roasted buckwheat brewed like tea. Smells of biscuits. You can eat the grains afterwards. A drink and a snack in one tube: on the island that counts as a feast. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("GoldenBuckwheatCup_NAME", "Золотая гречиха (гречишный чай)", "Golden Buckwheat (buckwheat tea)"),
        ("GoldenBuckwheatCup_DESC", "Жареная гречиха, которую заваривают как чай. Пахнет печеньем. Потом зёрна можно съесть. Чай и закуска в одной упаковке: на острове это называется «пир».", "Roasted buckwheat brewed like tea. Smells of biscuits. You can eat the grains afterwards. A drink and a snack in one tube: on the island that counts as a feast."),
        ("BarleySummer_NAME", "Ячменное лето (ячменный чай мугитя)", "Barley Summer (mugicha barley tea)"),
        ("BarleySummer_DESC", "Ячменный чай: в Японии это вкус лета, его пьют холодным в жару. Здесь лето не предусмотрено, поэтому пьём горячим и представляем жару. Получается плохо, но приятно. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Barley tea: in Japan it is the taste of summer, drunk cold in the heat. Summer is not on offer here, so we drink it hot and imagine the heat. It works badly but pleasantly. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("BarleySummerCup_NAME", "Ячменное лето (ячменный чай мугитя)", "Barley Summer (mugicha barley tea)"),
        ("BarleySummerCup_DESC", "Ячменный чай: в Японии это вкус лета, его пьют холодным в жару. Здесь лето не предусмотрено, поэтому пьём горячим и представляем жару. Получается плохо, но приятно.", "Barley tea: in Japan it is the taste of summer, drunk cold in the heat. Summer is not on offer here, so we drink it hot and imagine the heat. It works badly but pleasantly."),
        ("GangwonCob_NAME", "Початок Канвондо (кукурузный чай)", "Gangwon Cob (Korean corn tea)"),
        ("GangwonCob_DESC", "Чай из жареной кукурузы, сладкий и жёлтый. В Корее им греются зимой в горах Канвондо. Ещё одни люди, которые знают про зиму. Пакет можно обнять. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "A tea of roasted corn, sweet and yellow. In Korea they warm up with it through the Gangwon mountain winter. More people who know about winter. You may hug the bag. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("GangwonCobCup_NAME", "Початок Канвондо (кукурузный чай)", "Gangwon Cob (Korean corn tea)"),
        ("GangwonCobCup_DESC", "Чай из жареной кукурузы, сладкий и жёлтый. В Корее им греются зимой в горах Канвондо. Ещё одни люди, которые знают про зиму. Пакет можно обнять.", "A tea of roasted corn, sweet and yellow. In Korea they warm up with it through the Gangwon mountain winter. More people who know about winter. You may hug the bag."),
        ("YirgacheffeBloom_NAME", "Цветок Иргачеффе (эфиопский иргачеффе)", "Yirgacheffe Bloom (Ethiopian Yirgacheffe)"),
        ("YirgacheffeBloom_DESC", "Эфиопский кофе, который пахнет жасмином и лимоном, как будто это вообще чай. Бариста рассказывает о нём десять минут. Тебя никто не слушает, расскажи хотя бы печке. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Ethiopian coffee that smells of jasmine and lemon, as if it were tea all along. A barista would talk about it for ten minutes. Nobody is listening to you, so at least tell the stove. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("YirgacheffeBloomCup_NAME", "Цветок Иргачеффе (эфиопский иргачеффе)", "Yirgacheffe Bloom (Ethiopian Yirgacheffe)"),
        ("YirgacheffeBloomCup_DESC", "Эфиопский кофе, который пахнет жасмином и лимоном, как будто это вообще чай. Бариста рассказывает о нём десять минут. Тебя никто не слушает, расскажи хотя бы печке.", "Ethiopian coffee that smells of jasmine and lemon, as if it were tea all along. A barista would talk about it for ten minutes. Nobody is listening to you, so at least tell the stove."),
        ("SidamoValley_NAME", "Долина Сидамо (эфиопский сидамо)", "Sidamo Valley (Ethiopian Sidamo)"),
        ("SidamoValley_DESC", "Кофе из долины, где его пьют в три захода: первая чашка за встречу, вторая за разговор, третья за благословение. У тебя все три: за то, что дошёл, согрелся и никем не съеден. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee from a valley where it is drunk in three rounds: one for meeting, one for talk, one for blessing. You get all three: for making it, for warming up and for not being eaten. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SidamoValleyCup_NAME", "Долина Сидамо (эфиопский сидамо)", "Sidamo Valley (Ethiopian Sidamo)"),
        ("SidamoValleyCup_DESC", "Кофе из долины, где его пьют в три захода: первая чашка за встречу, вторая за разговор, третья за благословение. У тебя все три: за то, что дошёл, согрелся и никем не съеден.", "Coffee from a valley where it is drunk in three rounds: one for meeting, one for talk, one for blessing. You get all three: for making it, for warming up and for not being eaten."),
        ("HararGate_NAME", "Ворота Харэра (эфиопский харрар)", "Harar Gate (Ethiopian Harrar)"),
        ("HararGate_DESC", "Харрар сушат прямо в ягоде, и он пахнет черникой и вином. В Харэре по ночам кормят с рук гиен. Здесь волков с рук лучше не кормить: рука одна, а зима длинная. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Harrar is dried inside the cherry and smells of blueberries and wine. In Harar they hand-feed hyenas at night. Better not hand-feed the wolves here: hands are scarce and winter is long. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("HararGateCup_NAME", "Ворота Харэра (эфиопский харрар)", "Harar Gate (Ethiopian Harrar)"),
        ("HararGateCup_DESC", "Харрар сушат прямо в ягоде, и он пахнет черникой и вином. В Харэре по ночам кормят с рук гиен. Здесь волков с рук лучше не кормить: рука одна, а зима длинная.", "Harrar is dried inside the cherry and smells of blueberries and wine. In Harar they hand-feed hyenas at night. Better not hand-feed the wolves here: hands are scarce and winter is long."),
        ("NyeriSlope_NAME", "Склон Ньери (кения АА)", "Nyeri Slope (Kenya AA)"),
        ("NyeriSlope_DESC", "Кения АА: кислый, яркий, со вкусом чёрной смородины. «АА» значит самое крупное зерно. На острове «а-а» значит, что ты наступил на тонкий лёд. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Kenya AA: bright, sharp, tasting of blackcurrant. 'AA' means the biggest bean. On the island 'aa' means you have just stepped on thin ice. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("NyeriSlopeCup_NAME", "Склон Ньери (кения АА)", "Nyeri Slope (Kenya AA)"),
        ("NyeriSlopeCup_DESC", "Кения АА: кислый, яркий, со вкусом чёрной смородины. «АА» значит самое крупное зерно. На острове «а-а» значит, что ты наступил на тонкий лёд.", "Kenya AA: bright, sharp, tasting of blackcurrant. 'AA' means the biggest bean. On the island 'aa' means you have just stepped on thin ice."),
        ("PearlBean_NAME", "Жемчужное зерно (танзанийский пиберри)", "Pearl Bean (Tanzanian peaberry)"),
        ("PearlBean_DESC", "Пиберри: в ягоде вместо двух зёрен выросло одно, круглое. Одиночка, которому досталось всё. Ты в пустом доме с целым шкафом консервов понимаешь его как никто. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Peaberry: instead of two beans the cherry grew just one, round. A loner who got it all. Alone in an empty house with a whole cupboard of tins, you understand it better than anyone. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("PearlBeanCup_NAME", "Жемчужное зерно (танзанийский пиберри)", "Pearl Bean (Tanzanian peaberry)"),
        ("PearlBeanCup_DESC", "Пиберри: в ягоде вместо двух зёрен выросло одно, круглое. Одиночка, которому досталось всё. Ты в пустом доме с целым шкафом консервов понимаешь его как никто.", "Peaberry: instead of two beans the cherry grew just one, round. A loner who got it all. Alone in an empty house with a whole cupboard of tins, you understand it better than anyone."),
        ("ThousandHills_NAME", "Тысяча холмов (руандийский бурбон)", "Thousand Hills (Rwandan bourbon)"),
        ("ThousandHills_DESC", "Кофе из страны тысячи холмов. Красиво, пока не надо идти пешком. Ты уже знаешь: за каждым холмом ещё холм, а за последним кончаются силы. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee from the land of a thousand hills. Lovely until you have to walk it. You know by now: behind every hill is another hill, and behind the last one your strength runs out. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ThousandHillsCup_NAME", "Тысяча холмов (руандийский бурбон)", "Thousand Hills (Rwandan bourbon)"),
        ("ThousandHillsCup_DESC", "Кофе из страны тысячи холмов. Красиво, пока не надо идти пешком. Ты уже знаешь: за каждым холмом ещё холм, а за последним кончаются силы.", "Coffee from the land of a thousand hills. Lovely until you have to walk it. You know by now: behind every hill is another hill, and behind the last one your strength runs out."),
        ("VictoriaShore_NAME", "Берег Виктории (угандийская робуста)", "Victoria Shore (Ugandan robusta)"),
        ("VictoriaShore_DESC", "Угандийская робуста: кофеина вдвое больше, манер вдвое меньше. Грубая, горькая и честная. Выпил вечером: познакомишься со всеми ночными звуками хижины поимённо. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Ugandan robusta: twice the caffeine, half the manners. Rough, bitter and honest. Drink it in the evening and you will get to know every night sound of the cabin by name. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("VictoriaShoreCup_NAME", "Берег Виктории (угандийская робуста)", "Victoria Shore (Ugandan robusta)"),
        ("VictoriaShoreCup_DESC", "Угандийская робуста: кофеина вдвое больше, манер вдвое меньше. Грубая, горькая и честная. Выпил вечером: познакомишься со всеми ночными звуками хижины поимённо.", "Ugandan robusta: twice the caffeine, half the manners. Rough, bitter and honest. Drink it in the evening and you will get to know every night sound of the cabin by name."),
        ("PortMokha_NAME", "Порт Моха (йеменский мокка матари)", "Port Mokha (Yemen Mocha Mattari)"),
        ("PortMokha_DESC", "Из порта Моха кофе впервые поплыл по миру. Пахнет шоколадом и пряностями. Мешок проделал путь через три океана и застрял в рыбацком посёлке. Знакомая история. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "From the port of Mokha coffee first sailed out into the world. It smells of chocolate and spice. The sack crossed three oceans and got stuck in a fishing village. A familiar story. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("PortMokhaCup_NAME", "Порт Моха (йеменский мокка матари)", "Port Mokha (Yemen Mocha Mattari)"),
        ("PortMokhaCup_DESC", "Из порта Моха кофе впервые поплыл по миру. Пахнет шоколадом и пряностями. Мешок проделал путь через три океана и застрял в рыбацком посёлке. Знакомая история.", "From the port of Mokha coffee first sailed out into the world. It smells of chocolate and spice. The sack crossed three oceans and got stuck in a fishing village. A familiar story."),
        ("SantosWharf_NAME", "Причал Сантос (бразильский сантос)", "Santos Wharf (Brazil Santos)"),
        ("SantosWharf_DESC", "Бразильский сантос: мягкий, ореховый, без сюрпризов. Кофе, на который можно положиться. На острове это редкое качество. Тут даже на лёд нельзя положиться. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Brazilian Santos: mild, nutty, no surprises. A coffee you can rely on. A rare quality on the island. Here you can't even rely on the ice. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("SantosWharfCup_NAME", "Причал Сантос (бразильский сантос)", "Santos Wharf (Brazil Santos)"),
        ("SantosWharfCup_DESC", "Бразильский сантос: мягкий, ореховый, без сюрпризов. Кофе, на который можно положиться. На острове это редкое качество. Тут даже на лёд нельзя положиться.", "Brazilian Santos: mild, nutty, no surprises. A coffee you can rely on. A rare quality on the island. Here you can't even rely on the ice."),
        ("ThreeVolcanoes_NAME", "Три вулкана (гватемала антигуа)", "Three Volcanoes (Guatemala Antigua)"),
        ("ThreeVolcanoes_DESC", "Кофе вырос на пепле между тремя вулканами. Один из них до сих пор дымит. Зерно получилось с дымком и характером. Рядом с таким соседом характер появится у кого угодно. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee grown on ash between three volcanoes. One of them still smokes. The bean came out smoky, with character. Anyone would grow a character next to a neighbour like that. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ThreeVolcanoesCup_NAME", "Три вулкана (гватемала антигуа)", "Three Volcanoes (Guatemala Antigua)"),
        ("ThreeVolcanoesCup_DESC", "Кофе вырос на пепле между тремя вулканами. Один из них до сих пор дымит. Зерно получилось с дымком и характером. Рядом с таким соседом характер появится у кого угодно.", "Coffee grown on ash between three volcanoes. One of them still smokes. The bean came out smoky, with character. Anyone would grow a character next to a neighbour like that."),
        ("TarrazuPura_NAME", "Тарразу Пура (коста-риканский тарразу)", "Tarrazú Pura (Costa Rica Tarrazú)"),
        ("TarrazuPura_DESC", "В Коста-Рике девиз «пура вида», чистая жизнь. Жизнь на Великом Медведе тоже чистая: ни людей, ни электричества, ни планов на завтра. Только ты и кофе. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "The Costa Rican motto is 'pura vida', pure life. Life on Great Bear is pure too: no people, no electricity, no plans for tomorrow. Just you and the coffee. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("TarrazuPuraCup_NAME", "Тарразу Пура (коста-риканский тарразу)", "Tarrazú Pura (Costa Rica Tarrazú)"),
        ("TarrazuPuraCup_DESC", "В Коста-Рике девиз «пура вида», чистая жизнь. Жизнь на Великом Медведе тоже чистая: ни людей, ни электричества, ни планов на завтра. Только ты и кофе.", "The Costa Rican motto is 'pura vida', pure life. Life on Great Bear is pure too: no people, no electricity, no plans for tomorrow. Just you and the coffee."),
        ("ElephantBean_NAME", "Слоновье зерно (никарагуа марагоджип)", "Elephant Bean (Nicaragua Maragogype)"),
        ("ElephantBean_DESC", "Марагоджип: зёрна втрое крупнее обычных, «слоновьи». Слонов на острове не водилось, зато когда-то тут ходили мамонты. Кофе они не дождались. Ты дождался. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Maragogype: beans three times the usual size, 'elephant beans'. The island never had elephants, though mammoths once walked here. They did not live to see coffee. You did. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("ElephantBeanCup_NAME", "Слоновье зерно (никарагуа марагоджип)", "Elephant Bean (Nicaragua Maragogype)"),
        ("ElephantBeanCup_DESC", "Марагоджип: зёрна втрое крупнее обычных, «слоновьи». Слонов на острове не водилось, зато когда-то тут ходили мамонты. Кофе они не дождались. Ты дождался.", "Maragogype: beans three times the usual size, 'elephant beans'. The island never had elephants, though mammoths once walked here. They did not live to see coffee. You did."),
        ("SierraChiapas_NAME", "Сьерра Чьяпас (мексиканский чьяпас)", "Sierra Chiapas (Mexican Chiapas)"),
        ("SierraChiapas_DESC", "Кофе с гор Чьяпаса: шоколад, орех и немного упрямства. Вырос в облачном лесу, где сыро и ничего не видно. Туманное утро на болоте ему покажется родным. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Coffee from the Chiapas highlands: chocolate, nuts and a streak of stubbornness. Grown in cloud forest where it is damp and you can't see a thing. A foggy morning on the muskeg will feel like home to it. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("SierraChiapasCup_NAME", "Сьерра Чьяпас (мексиканский чьяпас)", "Sierra Chiapas (Mexican Chiapas)"),
        ("SierraChiapasCup_DESC", "Кофе с гор Чьяпаса: шоколад, орех и немного упрямства. Вырос в облачном лесу, где сыро и ничего не видно. Туманное утро на болоте ему покажется родным.", "Coffee from the Chiapas highlands: chocolate, nuts and a streak of stubbornness. Grown in cloud forest where it is damp and you can't see a thing. A foggy morning on the muskeg will feel like home to it."),
        ("BoqueteGeisha_NAME", "Гейша Бокете (панамская гейша)", "Boquete Geisha (Panama Geisha)"),
        ("BoqueteGeisha_DESC", "Панамская гейша: самый дорогой кофе на аукционах, пахнет бергамотом и персиком. За такую банку платят как за подержанную машину. Машины тут всё равно не заводятся. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Panama Geisha: the priciest coffee at auction, smelling of bergamot and peach. A tin like this costs as much as a used car. The cars here don't start anyway. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("BoqueteGeishaCup_NAME", "Гейша Бокете (панамская гейша)", "Boquete Geisha (Panama Geisha)"),
        ("BoqueteGeishaCup_DESC", "Панамская гейша: самый дорогой кофе на аукционах, пахнет бергамотом и персиком. За такую банку платят как за подержанную машину. Машины тут всё равно не заводятся.", "Panama Geisha: the priciest coffee at auction, smelling of bergamot and peach. A tin like this costs as much as a used car. The cars here don't start anyway."),
        ("BlueRidge_NAME", "Синий хребет (ямайка блю маунтин)", "Blue Ridge (Jamaica Blue Mountain)"),
        ("BlueRidge_DESC", "Блю маунтин возят в деревянных бочонках, как ром. Мягкий, без горечи, для ценителей. Пустой бочонок не выбрасывай: на острове всё, что горит, называется «дрова». Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Blue Mountain ships in wooden barrels, like rum. Smooth, no bitterness, one for the connoisseur. Keep the empty barrel: on the island anything that burns is called firewood. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("BlueRidgeCup_NAME", "Синий хребет (ямайка блю маунтин)", "Blue Ridge (Jamaica Blue Mountain)"),
        ("BlueRidgeCup_DESC", "Блю маунтин возят в деревянных бочонках, как ром. Мягкий, без горечи, для ценителей. Пустой бочонок не выбрасывай: на острове всё, что горит, называется «дрова».", "Blue Mountain ships in wooden barrels, like rum. Smooth, no bitterness, one for the connoisseur. Keep the empty barrel: on the island anything that burns is called firewood."),
        ("SierraMaestra_NAME", "Сьерра-Маэстра (кубинский кофе)", "Sierra Maestra (Cuban coffee)"),
        ("SierraMaestra_DESC", "Кубинский кофе: крошечная чашка, много сахара, крепость как у революции. В этих горах прятались партизаны. Ты прячешься в горах от погоды. Победит, увы, погода. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Cuban coffee: a tiny cup, lots of sugar, strong as a revolution. Guerrillas once hid in those mountains. You hide in yours from the weather. The weather, alas, will win. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SierraMaestraCup_NAME", "Сьерра-Маэстра (кубинский кофе)", "Sierra Maestra (Cuban coffee)"),
        ("SierraMaestraCup_DESC", "Кубинский кофе: крошечная чашка, много сахара, крепость как у революции. В этих горах прятались партизаны. Ты прячешься в горах от погоды. Победит, увы, погода.", "Cuban coffee: a tiny cup, lots of sugar, strong as a revolution. Guerrillas once hid in those mountains. You hide in yours from the weather. The weather, alas, will win."),
        ("MaunaKona_NAME", "Мауна Кона (гавайская кона)", "Mauna Kona (Hawaiian Kona)"),
        ("MaunaKona_DESC", "Кона с Гавайев: вулкан, океан, гирлянды цветов. Кто-то привёз банку из отпуска и поставил на полку «на особый случай». Особый случай настал, хозяин не дождался. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Kona from Hawaii: a volcano, the ocean, garlands of flowers. Someone brought the tin back from holiday and shelved it 'for a special occasion'. The occasion has come, the owner missed it. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("MaunaKonaCup_NAME", "Мауна Кона (гавайская кона)", "Mauna Kona (Hawaiian Kona)"),
        ("MaunaKonaCup_DESC", "Кона с Гавайев: вулкан, океан, гирлянды цветов. Кто-то привёз банку из отпуска и поставил на полку «на особый случай». Особый случай настал, хозяин не дождался.", "Kona from Hawaii: a volcano, the ocean, garlands of flowers. Someone brought the tin back from holiday and shelved it 'for a special occasion'. The occasion has come, the owner missed it."),
        ("SacredValley_NAME", "Священная долина (перуанский кофе)", "Sacred Valley (Peruvian coffee)"),
        ("SacredValley_DESC", "Кофе из долины инков, с высоты, где у туристов болит голова. Инки строили стены без раствора, и они стоят до сих пор. В твоей хижине дует из всех щелей. Учись. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee from the valley of the Incas, from heights that give tourists a headache. The Incas built walls without mortar and they still stand. Your cabin leaks wind at every seam. Take notes. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SacredValleyCup_NAME", "Священная долина (перуанский кофе)", "Sacred Valley (Peruvian coffee)"),
        ("SacredValleyCup_DESC", "Кофе из долины инков, с высоты, где у туристов болит голова. Инки строили стены без раствора, и они стоят до сих пор. В твоей хижине дует из всех щелей. Учись.", "Coffee from the valley of the Incas, from heights that give tourists a headache. The Incas built walls without mortar and they still stand. Your cabin leaks wind at every seam. Take notes."),
        ("MandhelingTiger_NAME", "Тигр Мандейлинга (суматра мандейлинг)", "Mandheling Tiger (Sumatra Mandheling)"),
        ("MandhelingTiger_DESC", "Суматра: густой, землистый, тяжёлый, как шаг тигра в джунглях. Тигров на острове нет, зато завелась пума. После этой кружки ты услышишь её раньше, чем она тебя. Наверное. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Sumatra: thick, earthy, heavy as a tiger's tread in the jungle. The island has no tigers, though a cougar has moved in. After this cup you will hear it before it hears you. Probably. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("MandhelingTigerCup_NAME", "Тигр Мандейлинга (суматра мандейлинг)", "Mandheling Tiger (Sumatra Mandheling)"),
        ("MandhelingTigerCup_DESC", "Суматра: густой, землистый, тяжёлый, как шаг тигра в джунглях. Тигров на острове нет, зато завелась пума. После этой кружки ты услышишь её раньше, чем она тебя. Наверное.", "Sumatra: thick, earthy, heavy as a tiger's tread in the jungle. The island has no tigers, though a cougar has moved in. After this cup you will hear it before it hears you. Probably."),
        ("OldJava_NAME", "Старая Ява (яванский кофе)", "Old Java (Java coffee)"),
        ("OldJava_DESC", "Яванский кофе: когда-то «ява» значило просто «кофе». Зерно выдерживали в трюмах парусников, пока плыли полгода. Твоя банка выдерживалась в подвале. Срок похожий. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Java coffee: 'java' once simply meant coffee. The beans aged in the holds of sailing ships on the half-year voyage. Your tin aged in a basement. About as long. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("OldJavaCup_NAME", "Старая Ява (яванский кофе)", "Old Java (Java coffee)"),
        ("OldJavaCup_DESC", "Яванский кофе: когда-то «ява» значило просто «кофе». Зерно выдерживали в трюмах парусников, пока плыли полгода. Твоя банка выдерживалась в подвале. Срок похожий.", "Java coffee: 'java' once simply meant coffee. The beans aged in the holds of sailing ships on the half-year voyage. Your tin aged in a basement. About as long."),
        ("TorajaHouse_NAME", "Дом Тораджи (сулавеси тораджа)", "Toraja House (Sulawesi Toraja)"),
        ("TorajaHouse_DESC", "Тораджа: кофе от людей, которые строят дома с крышей в форме лодки и хоронят родню в скалах. К покойникам там относятся спокойно. На острове ты тоже привык. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Toraja: coffee from people who build houses with boat-shaped roofs and bury their kin in cliffs. They are easy about the dead there. On the island you have got used to them too. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("TorajaHouseCup_NAME", "Дом Тораджи (сулавеси тораджа)", "Toraja House (Sulawesi Toraja)"),
        ("TorajaHouseCup_DESC", "Тораджа: кофе от людей, которые строят дома с крышей в форме лодки и хоронят родню в скалах. К покойникам там относятся спокойно. На острове ты тоже привык.", "Toraja: coffee from people who build houses with boat-shaped roofs and bury their kin in cliffs. They are easy about the dead there. On the island you have got used to them too."),
        ("NightCivet_NAME", "Ночная циветта (копи лювак)", "Night Civet (kopi luwak)"),
        ("NightCivet_DESC", "Копи лювак. Да, тот самый. Да, зверёк его сначала ест. Да, потом собирают. Ты на острове ел вещи и похуже, так что лицо попроще, и наливай. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Kopi luwak. Yes, that one. Yes, the animal eats it first. Yes, then they collect it. You have eaten worse on this island, so wipe that look off your face and pour. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("NightCivetCup_NAME", "Ночная циветта (копи лювак)", "Night Civet (kopi luwak)"),
        ("NightCivetCup_DESC", "Копи лювак. Да, тот самый. Да, зверёк его сначала ест. Да, потом собирают. Ты на острове ел вещи и похуже, так что лицо попроще, и наливай.", "Kopi luwak. Yes, that one. Yes, the animal eats it first. Yes, then they collect it. You have eaten worse on this island, so wipe that look off your face and pour."),
        ("ParadiseBird_NAME", "Райская птица (кофе Папуа — Новой Гвинеи)", "Bird of Paradise (Papua New Guinea coffee)"),
        ("ParadiseBird_DESC", "Кофе из Папуа, где в лесах танцуют райские птицы. Самец часами пляшет ради одного взгляда. У тебя из зрителей ворона, и её интересует, когда ты упадёшь. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee from Papua, where birds of paradise dance in the forest. The male dances for hours for a single glance. Your audience is a crow, and its interest is in when you will fall over. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ParadiseBirdCup_NAME", "Райская птица (кофе Папуа — Новой Гвинеи)", "Bird of Paradise (Papua New Guinea coffee)"),
        ("ParadiseBirdCup_DESC", "Кофе из Папуа, где в лесах танцуют райские птицы. Самец часами пляшет ради одного взгляда. У тебя из зрителей ворона, и её интересует, когда ты упадёшь.", "Coffee from Papua, where birds of paradise dance in the forest. The male dances for hours for a single glance. Your audience is a crow, and its interest is in when you will fall over."),
        ("MalabarRains_NAME", "Дожди Малабара (индийский муссонный малабар)", "Malabar Rains (Indian Monsooned Malabar)"),
        ("MalabarRains_DESC", "Зерно месяцами держат на муссонном ветру, пока не разбухнет и не пожелтеет. Кофе, испорченный погодой нарочно. Тебя погода портит бесплатно и без спроса. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "The beans are left in the monsoon wind for months until they swell and yellow. A coffee spoiled by the weather on purpose. The weather spoils you free of charge and without asking. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("MalabarRainsCup_NAME", "Дожди Малабара (индийский муссонный малабар)", "Malabar Rains (Indian Monsooned Malabar)"),
        ("MalabarRainsCup_DESC", "Зерно месяцами держат на муссонном ветру, пока не разбухнет и не пожелтеет. Кофе, испорченный погодой нарочно. Тебя погода портит бесплатно и без спроса.", "The beans are left in the monsoon wind for months until they swell and yellow. A coffee spoiled by the weather on purpose. The weather spoils you free of charge and without asking."),
        ("SaigonPhin_NAME", "Сайгонский фин (вьетнамская робуста)", "Saigon Phin (Vietnamese robusta)"),
        ("SaigonPhin_DESC", "Вьетнамская робуста для фина: капает в чашку по капле, минут десять. Крепкая, как удар веслом. Десять минут ожидания тут никого не пугают: метель идёт третий день. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Vietnamese robusta for the phin filter: it drips into the cup for ten minutes. Strong as a blow from an oar. A ten-minute wait scares nobody here: the blizzard is on its third day. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SaigonPhinCup_NAME", "Сайгонский фин (вьетнамская робуста)", "Saigon Phin (Vietnamese robusta)"),
        ("SaigonPhinCup_DESC", "Вьетнамская робуста для фина: капает в чашку по капле, минут десять. Крепкая, как удар веслом. Десять минут ожидания тут никого не пугают: метель идёт третий день.", "Vietnamese robusta for the phin filter: it drips into the cup for ten minutes. Strong as a blow from an oar. A ten-minute wait scares nobody here: the blizzard is on its third day."),
        ("BaoshanArabica_NAME", "Баошань (юньнаньский кофе)", "Baoshan (Yunnan coffee)"),
        ("BaoshanArabica_DESC", "Кофе из Юньнани, чайной провинции. Вырос среди чайных кустов и всю жизнь доказывал, что он не хуже. Доказал. Теперь стоит на полке рядом с пуэром и молчит. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee from Yunnan, the tea province. It grew among tea bushes and spent its life proving it was just as good. It proved it. Now it sits on the shelf beside the pu-erh, saying nothing. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("BaoshanArabicaCup_NAME", "Баошань (юньнаньский кофе)", "Baoshan (Yunnan coffee)"),
        ("BaoshanArabicaCup_DESC", "Кофе из Юньнани, чайной провинции. Вырос среди чайных кустов и всю жизнь доказывал, что он не хуже. Доказал. Теперь стоит на полке рядом с пуэром и молчит.", "Coffee from Yunnan, the tea province. It grew among tea bushes and spent its life proving it was just as good. It proved it. Now it sits on the shelf beside the pu-erh, saying nothing."),
        ("ExileIsland_NAME", "Остров Изгнания (кофе острова Святой Елены)", "Exile Island (St Helena coffee)"),
        ("ExileIsland_DESC", "Кофе с острова Святой Елены, куда сослали Наполеона. Он говорил, что хорош там только кофе. Ты сослан на остров попроще: без губернатора, зато с медведем. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Coffee from Saint Helena, where Napoleon was exiled. He said the coffee was the only good thing there. Your island of exile is humbler: no governor, but it comes with a bear. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("ExileIslandCup_NAME", "Остров Изгнания (кофе острова Святой Елены)", "Exile Island (St Helena coffee)"),
        ("ExileIslandCup_DESC", "Кофе с острова Святой Елены, куда сослали Наполеона. Он говорил, что хорош там только кофе. Ты сослан на остров попроще: без губернатора, зато с медведем.", "Coffee from Saint Helena, where Napoleon was exiled. He said the coffee was the only good thing there. Your island of exile is humbler: no governor, but it comes with a bear."),
        ("OldDock_NAME", "Старый док (купаж мокко-ява)", "Old Dock (Mocha-Java blend)"),
        ("OldDock_DESC", "Мокко-ява: зёрна из двух портов встретились на причале и решили держаться вместе. В доках Прибрежного шоссе так не вышло: все разбежались, остались сети и кофе. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Mocha-Java: beans from two ports met on a quay and decided to stick together. It did not go that way at the Coastal Highway docks: everyone scattered, leaving nets and coffee. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("OldDockCup_NAME", "Старый док (купаж мокко-ява)", "Old Dock (Mocha-Java blend)"),
        ("OldDockCup_DESC", "Мокко-ява: зёрна из двух портов встретились на причале и решили держаться вместе. В доках Прибрежного шоссе так не вышло: все разбежались, остались сети и кофе.", "Mocha-Java: beans from two ports met on a quay and decided to stick together. It did not go that way at the Coastal Highway docks: everyone scattered, leaving nets and coffee."),
        ("NapoliScuro_NAME", "Наполи Скуро (итальянская обжарка)", "Napoli Scuro (Italian roast)"),
        ("NapoliScuro_DESC", "Неаполитанская обжарка: почти уголь. В Неаполе кофе пьют стоя, за минуту, и оставляют один оплаченный для незнакомца. Тебе тоже кто-то оставил. Спасибо, незнакомец. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Neapolitan roast: very nearly charcoal. In Naples coffee is drunk standing, in a minute, and one is left paid for a stranger. Someone left one for you too. Thank you, stranger. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("NapoliScuroCup_NAME", "Наполи Скуро (итальянская обжарка)", "Napoli Scuro (Italian roast)"),
        ("NapoliScuroCup_DESC", "Неаполитанская обжарка: почти уголь. В Неаполе кофе пьют стоя, за минуту, и оставляют один оплаченный для незнакомца. Тебе тоже кто-то оставил. Спасибо, незнакомец.", "Neapolitan roast: very nearly charcoal. In Naples coffee is drunk standing, in a minute, and one is left paid for a stranger. Someone left one for you too. Thank you, stranger."),
        ("ParisCharbon_NAME", "Парижский уголь (французская обжарка)", "Paris Charbon (French roast)"),
        ("ParisCharbon_DESC", "Французская обжарка, чёрная, блестящая, с дымом. В Париже с ней подают круассан и вид на бульвар. Здесь подают сухарь и вид на сугроб. Сон не подают вообще. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "French roast: black, glossy, smoky. In Paris it is served with a croissant and a view of the boulevard. Here it comes with a cracker and a view of a snowdrift. Sleep is not served at all. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ParisCharbonCup_NAME", "Парижский уголь (французская обжарка)", "Paris Charbon (French roast)"),
        ("ParisCharbonCup_DESC", "Французская обжарка, чёрная, блестящая, с дымом. В Париже с ней подают круассан и вид на бульвар. Здесь подают сухарь и вид на сугроб. Сон не подают вообще.", "French roast: black, glossy, smoky. In Paris it is served with a croissant and a view of the boulevard. Here it comes with a cracker and a view of a snowdrift. Sleep is not served at all."),
        ("ViennaSalon_NAME", "Венский салон (венская обжарка)", "Vienna Salon (Vienna roast)"),
        ("ViennaSalon_DESC", "Венская обжарка: в кофейнях под неё читают газеты по три часа. Газеты на острове есть, все за один и тот же день. Ты знаешь их наизусть, включая кроссворд. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Vienna roast: in the coffee houses people read newspapers over it for three hours. The island has newspapers, all from the same day. You know them by heart, crossword included. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ViennaSalonCup_NAME", "Венский салон (венская обжарка)", "Vienna Salon (Vienna roast)"),
        ("ViennaSalonCup_DESC", "Венская обжарка: в кофейнях под неё читают газеты по три часа. Газеты на острове есть, все за один и тот же день. Ты знаешь их наизусть, включая кроссворд.", "Vienna roast: in the coffee houses people read newspapers over it for three hours. The island has newspapers, all from the same day. You know them by heart, crossword included."),
        ("CreoleQuarter_NAME", "Креольский квартал (кофе с цикорием по-новоорлеански)", "Creole Quarter (New Orleans coffee with chicory)"),
        ("CreoleQuarter_DESC", "Новоорлеанский кофе с цикорием: под него играют джаз и едят пончики в сахарной пудре. У тебя из джаза скрип двери, из пудры снег. Импровизируй. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "New Orleans coffee with chicory: it goes with jazz and doughnuts under powdered sugar. Your jazz is a creaking door, your powder is snow. Improvise. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CreoleQuarterCup_NAME", "Креольский квартал (кофе с цикорием по-новоорлеански)", "Creole Quarter (New Orleans coffee with chicory)"),
        ("CreoleQuarterCup_DESC", "Новоорлеанский кофе с цикорием: под него играют джаз и едят пончики в сахарной пудре. У тебя из джаза скрип двери, из пудры снег. Импровизируй.", "New Orleans coffee with chicory: it goes with jazz and doughnuts under powdered sugar. Your jazz is a creaking door, your powder is snow. Improvise."),
        ("FjordKokekaffe_NAME", "Фьорд (кокекаффе, кофе для варки)", "Fjord (kokekaffe, boiling coffee)"),
        ("FjordKokekaffe_DESC", "Норвежский кофе для варки в котелке: довёл до кипения, снял, подождал. Норвежцы пьют его на лыжне в минус двадцать и говорят «хорошая погода». Твои люди. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Norwegian boiling coffee for the pot: bring to the boil, take off, wait. Norwegians drink it on the ski trail at twenty below and call it nice weather. Your kind of people. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("FjordKokekaffeCup_NAME", "Фьорд (кокекаффе, кофе для варки)", "Fjord (kokekaffe, boiling coffee)"),
        ("FjordKokekaffeCup_DESC", "Норвежский кофе для варки в котелке: довёл до кипения, снял, подождал. Норвежцы пьют его на лыжне в минус двадцать и говорят «хорошая погода». Твои люди.", "Norwegian boiling coffee for the pot: bring to the boil, take off, wait. Norwegians drink it on the ski trail at twenty below and call it nice weather. Your kind of people."),
        ("CampfireCoffee_NAME", "Костровой кофе (ковбойский кофе)", "Campfire Coffee (cowboy coffee)"),
        ("CampfireCoffee_DESC", "Ковбойский кофе: кинул в котелок, вскипятил, гущу осадил холодной водой. Процеживать через зубы. Ковбой сторожил стадо от волков. Ты сторожишь от волков себя. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Cowboy coffee: throw it in the pot, boil, settle the grounds with cold water. Strain through your teeth. The cowboy guarded the herd from wolves. You guard yourself. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("CampfireCoffeeCup_NAME", "Костровой кофе (ковбойский кофе)", "Campfire Coffee (cowboy coffee)"),
        ("CampfireCoffeeCup_DESC", "Ковбойский кофе: кинул в котелок, вскипятил, гущу осадил холодной водой. Процеживать через зубы. Ковбой сторожил стадо от волков. Ты сторожишь от волков себя.", "Cowboy coffee: throw it in the pot, boil, settle the grounds with cold water. Strain through your teeth. The cowboy guarded the herd from wolves. You guard yourself."),
        ("Kafenio_NAME", "Кафенио (греческий кофе)", "Kafenio (Greek coffee)"),
        ("Kafenio_DESC", "Греческий кофе: в кафенио старики сидят над одной чашкой полдня и решают судьбы мира. Ты сидишь над кружкой и решаешь, идти ли за дровами. Вопрос не менее важный. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Greek coffee: in the kafenio old men sit over one cup for half a day, settling the fate of the world. You sit over a mug settling whether to go for firewood. No less weighty a question. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("KafenioCup_NAME", "Кафенио (греческий кофе)", "Kafenio (Greek coffee)"),
        ("KafenioCup_DESC", "Греческий кофе: в кафенио старики сидят над одной чашкой полдня и решают судьбы мира. Ты сидишь над кружкой и решаешь, идти ли за дровами. Вопрос не менее важный.", "Greek coffee: in the kafenio old men sit over one cup for half a day, settling the fate of the world. You sit over a mug settling whether to go for firewood. No less weighty a question."),
        ("GoldenDallah_NAME", "Золотая далля (арабская кахва)", "Golden Dallah (Arabic qahwa)"),
        ("GoldenDallah_DESC", "Арабская кахва: светлая, с кардамоном, из кофейника с клювом. Гостю наливают трижды, отказываться невежливо. Ты и хозяин, и гость. Не обижай хозяина. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Arabic qahwa: pale, with cardamom, poured from a beaked pot. A guest is served three times and refusing is rude. You are both host and guest. Don't offend the host. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("GoldenDallahCup_NAME", "Золотая далля (арабская кахва)", "Golden Dallah (Arabic qahwa)"),
        ("GoldenDallahCup_DESC", "Арабская кахва: светлая, с кардамоном, из кофейника с клювом. Гостю наливают трижды, отказываться невежливо. Ты и хозяин, и гость. Не обижай хозяина.", "Arabic qahwa: pale, with cardamom, poured from a beaked pot. A guest is served three times and refusing is rude. You are both host and guest. Don't offend the host."),
        ("ClayPot_NAME", "Глиняный горшок (кафе де олья)", "Clay Pot (café de olla)"),
        ("ClayPot_DESC", "Мексиканский кофе, который варят в глиняном горшке с корицей и тростниковым сахаром. Горшка нет. Есть консервная банка, и она старается как может. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Mexican coffee simmered in a clay pot with cinnamon and cane sugar. You have no clay pot. You have a food tin, and it is doing its best. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("ClayPotCup_NAME", "Глиняный горшок (кафе де олья)", "Clay Pot (café de olla)"),
        ("ClayPotCup_DESC", "Мексиканский кофе, который варят в глиняном горшке с корицей и тростниковым сахаром. Горшка нет. Есть консервная банка, и она старается как может.", "Mexican coffee simmered in a clay pot with cinnamon and cane sugar. You have no clay pot. You have a food tin, and it is doing its best."),
        ("DjarPepper_NAME", "Перец Джар (кафе туба)", "Djar Pepper (café Touba)"),
        ("DjarPepper_DESC", "Сенегальский кофе с перцем джар: жжёт язык, прочищает нос, будит совесть. В Дакаре его пьют в жару. Попробуй в мороз: эффект тот же, только ещё и приятно. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Senegalese coffee with djar pepper: burns the tongue, clears the nose, wakes the conscience. In Dakar they drink it in the heat. Try it in the frost: same effect, only pleasant. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("DjarPepperCup_NAME", "Перец Джар (кафе туба)", "Djar Pepper (café Touba)"),
        ("DjarPepperCup_DESC", "Сенегальский кофе с перцем джар: жжёт язык, прочищает нос, будит совесть. В Дакаре его пьют в жару. Попробуй в мороз: эффект тот же, только ещё и приятно.", "Senegalese coffee with djar pepper: burns the tongue, clears the nose, wakes the conscience. In Dakar they drink it in the heat. Try it in the frost: same effect, only pleasant."),
        ("MadrasFilter_NAME", "Мадрасский фильтр (южноиндийский фильтр-кофе)", "Madras Filter (South Indian filter coffee)"),
        ("MadrasFilter_DESC", "Южноиндийский кофе: его переливают из стакана в стакан с метровой высоты, пока не вспенится. Называется «кофе метром». У тебя получится «кофе по полу». Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "South Indian coffee: poured from tumbler to tumbler from a yard up until it froths. They call it 'coffee by the yard'. Yours will be 'coffee by the floor'. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("MadrasFilterCup_NAME", "Мадрасский фильтр (южноиндийский фильтр-кофе)", "Madras Filter (South Indian filter coffee)"),
        ("MadrasFilterCup_DESC", "Южноиндийский кофе: его переливают из стакана в стакан с метровой высоты, пока не вспенится. Называется «кофе метром». У тебя получится «кофе по полу».", "South Indian coffee: poured from tumbler to tumbler from a yard up until it froths. They call it 'coffee by the yard'. Yours will be 'coffee by the floor'."),
        ("QuietNight_NAME", "Тихая ночь (кофе без кофеина)", "Quiet Night (decaf coffee)"),
        ("QuietNight_DESC", "Кофе без кофеина. Вкус есть, запах есть, смысла нет. Зато после него спится. На острове это единственный кофе, который на твоей стороне после заката. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee without caffeine. It has taste, it has smell, it has no point. You do sleep after it, though. The only coffee on the island that is on your side after sundown. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("QuietNightCup_NAME", "Тихая ночь (кофе без кофеина)", "Quiet Night (decaf coffee)"),
        ("QuietNightCup_DESC", "Кофе без кофеина. Вкус есть, запах есть, смысла нет. Зато после него спится. На острове это единственный кофе, который на твоей стороне после заката.", "Coffee without caffeine. It has taste, it has smell, it has no point. You do sleep after it, though. The only coffee on the island that is on your side after sundown."),
        ("HazelGrove_NAME", "Ореховая роща (кофе с ароматом фундука)", "Hazel Grove (hazelnut flavoured coffee)"),
        ("HazelGrove_DESC", "Кофе с запахом фундука. Самого фундука в нём нет. Белка бы обиделась. Белок на острове, кстати, тоже нет, и никто не знает, кого за это благодарить. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee that smells of hazelnut. There is no actual hazelnut in it. A squirrel would be insulted. The island has no squirrels either, by the way, and nobody knows whom to thank. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("HazelGroveCup_NAME", "Ореховая роща (кофе с ароматом фундука)", "Hazel Grove (hazelnut flavoured coffee)"),
        ("HazelGroveCup_DESC", "Кофе с запахом фундука. Самого фундука в нём нет. Белка бы обиделась. Белок на острове, кстати, тоже нет, и никто не знает, кого за это благодарить.", "Coffee that smells of hazelnut. There is no actual hazelnut in it. A squirrel would be insulted. The island has no squirrels either, by the way, and nobody knows whom to thank."),
        ("GoldGranule_NAME", "Золотая гранула (сублимированный кофе)", "Gold Granule (freeze-dried coffee)"),
        ("GoldGranule_DESC", "Сублимированный кофе: его заморозили и высушили в вакууме. Процесс, очень похожий на прогулку до Волчьей горы. Ты и банка прошли через одно и то же. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Freeze-dried coffee: frozen, then dried in a vacuum. A process much like a walk to Timberwolf Mountain. You and the jar have been through the same thing. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("GoldGranuleCup_NAME", "Золотая гранула (сублимированный кофе)", "Gold Granule (freeze-dried coffee)"),
        ("GoldGranuleCup_DESC", "Сублимированный кофе: его заморозили и высушили в вакууме. Процесс, очень похожий на прогулку до Волчьей горы. Ты и банка прошли через одно и то же.", "Freeze-dried coffee: frozen, then dried in a vacuum. A process much like a walk to Timberwolf Mountain. You and the jar have been through the same thing."),
        ("MeridianInstant_NAME", "Меридиан (растворимый кофе в порошке)", "Meridian (instant coffee powder)"),
        ("MeridianInstant_DESC", "Растворимый кофе в порошке, какой брали в экспедиции. Не тонет, не портится, не радует. Полярники уважали его за первые два пункта и прощали третий. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Powdered instant coffee of the kind taken on expeditions. Does not sink, does not spoil, does not delight. Polar crews respected it for the first two and forgave the third. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("MeridianInstantCup_NAME", "Меридиан (растворимый кофе в порошке)", "Meridian (instant coffee powder)"),
        ("MeridianInstantCup_DESC", "Растворимый кофе в порошке, какой брали в экспедиции. Не тонет, не портится, не радует. Полярники уважали его за первые два пункта и прощали третий.", "Powdered instant coffee of the kind taken on expeditions. Does not sink, does not spoil, does not delight. Polar crews respected it for the first two and forgave the third."),
        ("BangaloreBlend_NAME", "Бангалорский купаж (растворимый кофе с цикорием)", "Bangalore Blend (instant coffee with chicory)"),
        ("BangaloreBlend_DESC", "Индийский растворимый с цикорием: его взбивают с сахаром в пену, потом заливают. Взбивать надо минут пять. Заодно согреешься. Двойная польза, одна ложка. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Indian instant with chicory: you beat it with sugar into a foam, then add water. The beating takes five minutes. It warms you up meanwhile. Double the benefit, one spoon. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("BangaloreBlendCup_NAME", "Бангалорский купаж (растворимый кофе с цикорием)", "Bangalore Blend (instant coffee with chicory)"),
        ("BangaloreBlendCup_DESC", "Индийский растворимый с цикорием: его взбивают с сахаром в пену, потом заливают. Взбивать надо минут пять. Заодно согреешься. Двойная польза, одна ложка.", "Indian instant with chicory: you beat it with sugar into a foam, then add water. The beating takes five minutes. It warms you up meanwhile. Double the benefit, one spoon."),
        ("FoamCappuccino_NAME", "Пенка (капучино в пакетиках)", "Foam (instant cappuccino sachets)"),
        ("FoamCappuccino_DESC", "Капучино из пакетика: пенка появляется сама, без бариста и без совести. В Италии за такое лишают гражданства. До Италии далеко, пей спокойно. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Cappuccino from a sachet: the foam appears on its own, with no barista and no shame. In Italy they would revoke your citizenship for it. Italy is far away, drink in peace. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("FoamCappuccinoCup_NAME", "Пенка (капучино в пакетиках)", "Foam (instant cappuccino sachets)"),
        ("FoamCappuccinoCup_DESC", "Капучино из пакетика: пенка появляется сама, без бариста и без совести. В Италии за такое лишают гражданства. До Италии далеко, пей спокойно.", "Cappuccino from a sachet: the foam appears on its own, with no barista and no shame. In Italy they would revoke your citizenship for it. Italy is far away, drink in peace."),
        ("IpohWhite_NAME", "Белый Ипо (малайзийский белый кофе)", "Ipoh White (Malaysian white coffee)"),
        ("IpohWhite_DESC", "Белый кофе из Ипо: зёрна жарят на маргарине, потом добавляют сгущёнку. Звучит как преступление, пьётся как объятие. Объятий на острове не было давно. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "White coffee from Ipoh: the beans are roasted in margarine, then condensed milk goes in. Sounds like a crime, drinks like a hug. The island has been short on hugs for a while. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("IpohWhiteCup_NAME", "Белый Ипо (малайзийский белый кофе)", "Ipoh White (Malaysian white coffee)"),
        ("IpohWhiteCup_DESC", "Белый кофе из Ипо: зёрна жарят на маргарине, потом добавляют сгущёнку. Звучит как преступление, пьётся как объятие. Объятий на острове не было давно.", "White coffee from Ipoh: the beans are roasted in margarine, then condensed milk goes in. Sounds like a crime, drinks like a hug. The island has been short on hugs for a while."),
        ("NanyangKopi_NAME", "Копи-О Наньян (сингапурский копи-о, пакетики)", "Nanyang Kopi-O (Singapore kopi-o bags)"),
        ("NanyangKopi_DESC", "Копи-О: зёрна жарят с сахаром до черноты. Сингапурские грузчики пили его в шесть утра и шли таскать мешки. Мешок у тебя свой, тридцать кило, и он уже ждёт. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Kopi-O: beans roasted with sugar until black. Singapore dockers drank it at six in the morning and went to haul sacks. You have a sack of your own, sixty pounds, and it is waiting. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("NanyangKopiCup_NAME", "Копи-О Наньян (сингапурский копи-о, пакетики)", "Nanyang Kopi-O (Singapore kopi-o bags)"),
        ("NanyangKopiCup_DESC", "Копи-О: зёрна жарят с сахаром до черноты. Сингапурские грузчики пили его в шесть утра и шли таскать мешки. Мешок у тебя свой, тридцать кило, и он уже ждёт.", "Kopi-O: beans roasted with sugar until black. Singapore dockers drank it at six in the morning and went to haul sacks. You have a sack of your own, sixty pounds, and it is waiting."),
        ("MandarinDucks_NAME", "Утки-мандаринки (юаньян, кофе с чаем)", "Mandarin Ducks (yuanyang, coffee with tea)"),
        ("MandarinDucks_DESC", "Юаньян: кофе и чай в одной чашке. Назван в честь уток, которые не расстаются всю жизнь. Идеальный напиток для того, кто не может решить, что заварить. Заварил всё. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Yuanyang: coffee and tea in one cup. Named after ducks that mate for life. The perfect drink for someone who can't decide what to brew. Brewed the lot. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("MandarinDucksCup_NAME", "Утки-мандаринки (юаньян, кофе с чаем)", "Mandarin Ducks (yuanyang, coffee with tea)"),
        ("MandarinDucksCup_DESC", "Юаньян: кофе и чай в одной чашке. Назван в честь уток, которые не расстаются всю жизнь. Идеальный напиток для того, кто не может решить, что заварить. Заварил всё.", "Yuanyang: coffee and tea in one cup. Named after ducks that mate for life. The perfect drink for someone who can't decide what to brew. Brewed the lot."),
        ("SaigonSua_NAME", "Сайгон Сыа (вьетнамский кофе со сгущёнкой)", "Saigon Sữa (Vietnamese milk coffee stick)"),
        ("SaigonSua_DESC", "Вьетнамский кофе со сгущёнкой: густой, сладкий, как десерт. Сгущёнка в составе уже есть. Не надо искать банку, открывать её ножом и резать палец. Прогресс. Готовится на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "Vietnamese coffee with condensed milk: thick, sweet, practically pudding. The condensed milk is already inside. No hunting for a tin, opening it with a knife and cutting your finger. Progress. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("SaigonSuaCup_NAME", "Сайгон Сыа (вьетнамский кофе со сгущёнкой)", "Saigon Sữa (Vietnamese milk coffee stick)"),
        ("SaigonSuaCup_DESC", "Вьетнамский кофе со сгущёнкой: густой, сладкий, как десерт. Сгущёнка в составе уже есть. Не надо искать банку, открывать её ножом и резать палец. Прогресс.", "Vietnamese coffee with condensed milk: thick, sweet, practically pudding. The condensed milk is already inside. No hunting for a tin, opening it with a knife and cutting your finger. Progress."),
        ("KakeruDrip_NAME", "Какэру (дрип-пакеты)", "Kakeru (drip bag coffee)"),
        ("KakeruDrip_DESC", "Японский дрип-пакет: вешаешь ушками на кружку, льёшь воду, получаешь кофе как в кофейне. Маленькое чудо инженерии посреди места, где главный инструмент: лом. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A Japanese drip bag: hook the ears over the mug, pour, get café-grade coffee. A small marvel of engineering in a place where the chief tool is a prybar. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("KakeruDripCup_NAME", "Какэру (дрип-пакеты)", "Kakeru (drip bag coffee)"),
        ("KakeruDripCup_DESC", "Японский дрип-пакет: вешаешь ушками на кружку, льёшь воду, получаешь кофе как в кофейне. Маленькое чудо инженерии посреди места, где главный инструмент: лом.", "A Japanese drip bag: hook the ears over the mug, pour, get café-grade coffee. A small marvel of engineering in a place where the chief tool is a prybar."),
        ("RestStop_NAME", "Привал (кофе в пакетиках)", "Rest Stop (coffee bags)"),
        ("RestStop_DESC", "Кофе в пакетиках, как чай: бросил, залил, сел на пенёк. На большее на привале нет ни сил, ни желания. Пенёк, кстати, потом можно забрать на дрова. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Coffee in bags, like tea: drop, pour, sit on a stump. A rest stop leaves no strength or wish for more. The stump, by the way, can come along as firewood afterwards. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("RestStopCup_NAME", "Привал (кофе в пакетиках)", "Rest Stop (coffee bags)"),
        ("RestStopCup_DESC", "Кофе в пакетиках, как чай: бросил, залил, сел на пенёк. На большее на привале нет ни сил, ни желания. Пенёк, кстати, потом можно забрать на дрова.", "Coffee in bags, like tea: drop, pour, sit on a stump. A rest stop leaves no strength or wish for more. The stump, by the way, can come along as firewood afterwards."),
        ("BivouacEssence_NAME", "Бивуак (кофейная эссенция с цикорием)", "Bivouac (coffee and chicory essence)"),
        ("BivouacEssence_DESC", "Кофейная эссенция с цикорием в бутылке: ложка на кружку кипятка. Солдаты пили её в окопах и писали домой, что всё хорошо. Ты домой не пишешь, но тоже держишься. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee and chicory essence in a bottle: a spoonful to a mug of hot water. Soldiers drank it in the trenches and wrote home that all was well. You don't write home, but you are holding up too. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("BivouacEssenceCup_NAME", "Бивуак (кофейная эссенция с цикорием)", "Bivouac (coffee and chicory essence)"),
        ("BivouacEssenceCup_DESC", "Кофейная эссенция с цикорием в бутылке: ложка на кружку кипятка. Солдаты пили её в окопах и писали домой, что всё хорошо. Ты домой не пишешь, но тоже держишься.", "Coffee and chicory essence in a bottle: a spoonful to a mug of hot water. Soldiers drank it in the trenches and wrote home that all was well. You don't write home, but you are holding up too."),
        ("KuroBlack_NAME", "Куро (чёрный кофе в банке)", "Kuro (canned black coffee)"),
        ("KuroBlack_DESC", "Чёрный кофе в банке из японского автомата. Автомат выдаёт её горячей. Автоматы на острове выдают только эхо и разочарование, так что пей холодным. Пьётся холодным, огонь не нужен.", "Black coffee in a can from a Japanese vending machine. The machine hands it out hot. The machines on the island hand out only echoes and disappointment, so drink it cold. Drunk cold, no fire needed."),
        ("YukiAuLait_NAME", "Юки (кафе-о-ле в банке)", "Yuki (canned café au lait)"),
        ("YukiAuLait_DESC", "«Юки» по-японски «снег». Кофе с молоком в белой банке. Назвать напиток в честь снега мог только человек, которому снег ни разу не падал за шиворот. Пьётся холодным, огонь не нужен.", "'Yuki' is Japanese for snow. Milky coffee in a white can. Only someone who never had snow down the back of their neck could name a drink after it. Drunk cold, no fire needed."),
        ("RoyalMilkTea_NAME", "Королевский (молочный чай в банке)", "Royal (canned royal milk tea)"),
        ("RoyalMilkTea_DESC", "Королевский молочный чай в банке. Королевского в нём название и самомнение. Но открываешь её в рыбацкой будке посреди озера и чувствуешь: трон, пусть и ледяной. Пьётся холодным, огонь не нужен.", "Royal milk tea in a can. The royal part is the name and the attitude. But open it in a fishing hut in the middle of the lake and you feel it: a throne, if an icy one. Drunk cold, no fire needed."),
        ("ColdSencha_NAME", "Холодная сэнтя (зелёный чай в банке)", "Cold Sencha (canned green tea)"),
        ("ColdSencha_DESC", "Холодный зелёный чай в банке, без сахара. Японские служащие пьют его в поезде в семь утра. У тебя ни поезда, ни службы, ни семи утра. Только рельсы и банка. Пьётся холодным, огонь не нужен.", "Cold green tea in a can, no sugar. Japanese office workers drink it on the seven o'clock train. You have no train, no office and no seven o'clock. Just the rails and the can. Drunk cold, no fire needed."),
        ("SheafBarley_NAME", "Сноп (ячменный напиток)", "Sheaf (barley coffee)"),
        ("SheafBarley_DESC", "Ячменный напиток: кофе для тех, у кого кофе нет. Пахнет хлебной коркой. Хлеба ты не видел с самолёта, так что нюхай банку медленно и с закрытыми глазами. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "A barley drink: coffee for people who have no coffee. It smells of bread crust. You haven't seen bread since the plane, so sniff the tin slowly, eyes shut. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SheafBarleyCup_NAME", "Сноп (ячменный напиток)", "Sheaf (barley coffee)"),
        ("SheafBarleyCup_DESC", "Ячменный напиток: кофе для тех, у кого кофе нет. Пахнет хлебной коркой. Хлеба ты не видел с самолёта, так что нюхай банку медленно и с закрытыми глазами.", "A barley drink: coffee for people who have no coffee. It smells of bread crust. You haven't seen bread since the plane, so sniff the tin slowly, eyes shut."),
        ("OrzoTosto_NAME", "Орцо Тосто (итальянский ячменный кофе)", "Orzo Tosto (Italian caffè d'orzo)"),
        ("OrzoTosto_DESC", "Итальянский ячменный «кофе»: его дают детям и тем, кому врач запретил эспрессо. Врача на острове нет, запрещать некому. Но и эспрессо нет. Круг замкнулся. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Italian barley 'coffee': given to children and to those whose doctor has banned espresso. The island has no doctor to ban anything. It has no espresso either. Full circle. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("OrzoTostoCup_NAME", "Орцо Тосто (итальянский ячменный кофе)", "Orzo Tosto (Italian caffè d'orzo)"),
        ("OrzoTostoCup_DESC", "Итальянский ячменный «кофе»: его дают детям и тем, кому врач запретил эспрессо. Врача на острове нет, запрещать некому. Но и эспрессо нет. Круг замкнулся.", "Italian barley 'coffee': given to children and to those whose doctor has banned espresso. The island has no doctor to ban anything. It has no espresso either. Full circle."),
        ("MillersRye_NAME", "Мельник (ржаной кофе)", "Miller's (rye coffee)"),
        ("MillersRye_DESC", "Ржаной кофе: мельник жарил зерно, которое не пошло в муку. Вкус кислого хлеба и упрямства. Мельницы здесь нет, но ветра хватило бы на десять. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Rye coffee: the miller roasted the grain that didn't make flour. It tastes of sour bread and obstinacy. There is no mill here, though there is wind enough for ten. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("MillersRyeCup_NAME", "Мельник (ржаной кофе)", "Miller's (rye coffee)"),
        ("MillersRyeCup_DESC", "Ржаной кофе: мельник жарил зерно, которое не пошло в муку. Вкус кислого хлеба и упрямства. Мельницы здесь нет, но ветра хватило бы на десять.", "Rye coffee: the miller roasted the grain that didn't make flour. It tastes of sour bread and obstinacy. There is no mill here, though there is wind enough for ten."),
        ("Courland_NAME", "Курляндия (кофейный напиток из ячменя, цикория и желудей)", "Courland (coffee drink of barley, chicory and acorns)"),
        ("Courland_DESC", "Ячмень, цикорий и жёлуди. Кофе в составе нет, и пачка этого даже не стесняется. Жёлуди на острове ты уже собирал и молол сам. Тут хотя бы сделали за тебя. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Barley, chicory and acorns. No coffee in it, and the carton isn't even embarrassed. You have already gathered and ground acorns yourself on the island. Here someone did it for you. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CourlandCup_NAME", "Курляндия (кофейный напиток из ячменя, цикория и желудей)", "Courland (coffee drink of barley, chicory and acorns)"),
        ("CourlandCup_DESC", "Ячмень, цикорий и жёлуди. Кофе в составе нет, и пачка этого даже не стесняется. Жёлуди на острове ты уже собирал и молол сам. Тут хотя бы сделали за тебя.", "Barley, chicory and acorns. No coffee in it, and the carton isn't even embarrassed. You have already gathered and ground acorns yourself on the island. Here someone did it for you."),
        ("PastorsMalt_NAME", "Пасторский солод (солодовый кофе)", "Pastor's Malt (malt coffee)"),
        ("PastorsMalt_DESC", "Солодовый кофе: его придумал деревенский пастор, чтобы паства не тратилась на заморское. Полезно, скромно, скучновато. Как проповедь, только тёплая. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Malt coffee: invented by a village pastor so the flock would not waste money on foreign beans. Wholesome, modest, a little dull. Like a sermon, only warm. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("PastorsMaltCup_NAME", "Пасторский солод (солодовый кофе)", "Pastor's Malt (malt coffee)"),
        ("PastorsMaltCup_DESC", "Солодовый кофе: его придумал деревенский пастор, чтобы паства не тратилась на заморское. Полезно, скромно, скучновато. Как проповедь, только тёплая.", "Malt coffee: invented by a village pastor so the flock would not waste money on foreign beans. Wholesome, modest, a little dull. Like a sermon, only warm."),
        ("ViennaFig_NAME", "Венская фига (инжирный кофе)", "Vienna Fig (fig coffee)"),
        ("ViennaFig_DESC", "Жареный инжир, который в Вене подмешивали в кофе для сладости и цвета. Венцы считали это секретом. Секрет лежал в шкафу охотничьего домика. Плохо прятали. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Roasted fig, which the Viennese slipped into coffee for sweetness and colour. They considered it a secret. The secret was sitting in a hunting lodge cupboard. Poorly kept. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("ViennaFigCup_NAME", "Венская фига (инжирный кофе)", "Vienna Fig (fig coffee)"),
        ("ViennaFigCup_DESC", "Жареный инжир, который в Вене подмешивали в кофе для сладости и цвета. Венцы считали это секретом. Секрет лежал в шкафу охотничьего домика. Плохо прятали.", "Roasted fig, which the Viennese slipped into coffee for sweetness and colour. They considered it a secret. The secret was sitting in a hunting lodge cupboard. Poorly kept."),
        ("AlpineLupin_NAME", "Альпийский люпин (люпиновый кофе)", "Alpine Lupin (lupin coffee)"),
        ("AlpineLupin_DESC", "Кофе из люпина: в Альпах его жарят крестьяне, которым до магазина два перевала. Тебе до магазина тоже два перевала, только магазин разграблен, а перевалы настоящие. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Lupin coffee: roasted in the Alps by farmers two passes away from a shop. You are two passes from a shop as well, except the shop is looted and the passes are real. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("AlpineLupinCup_NAME", "Альпийский люпин (люпиновый кофе)", "Alpine Lupin (lupin coffee)"),
        ("AlpineLupinCup_DESC", "Кофе из люпина: в Альпах его жарят крестьяне, которым до магазина два перевала. Тебе до магазина тоже два перевала, только магазин разграблен, а перевалы настоящие.", "Lupin coffee: roasted in the Alps by farmers two passes away from a shop. You are two passes from a shop as well, except the shop is looted and the passes are real."),
        ("DateStone_NAME", "Финиковая косточка (кофе из финиковых косточек)", "Date Stone (date seed coffee)"),
        ("DateStone_DESC", "Кофе из финиковых косточек: бедуины не выбрасывают ничего, даже косточки. В пустыне нечего жечь, на острове нечего есть. Люди крайностей понимают друг друга. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Coffee from date stones: the Bedouin waste nothing, not even the pits. The desert has nothing to burn, the island has nothing to eat. People of extremes understand one another. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("DateStoneCup_NAME", "Финиковая косточка (кофе из финиковых косточек)", "Date Stone (date seed coffee)"),
        ("DateStoneCup_DESC", "Кофе из финиковых косточек: бедуины не выбрасывают ничего, даже косточки. В пустыне нечего жечь, на острове нечего есть. Люди крайностей понимают друг друга.", "Coffee from date stones: the Bedouin waste nothing, not even the pits. The desert has nothing to burn, the island has nothing to eat. People of extremes understand one another."),
        ("CyprusGold_NAME", "Чёрное золото Кипра (кэроб)", "Cyprus Black Gold (carob drink)"),
        ("CyprusGold_DESC", "Кэроб: стручки рожкового дерева, сладкие без сахара. Их семенами когда-то взвешивали золото, отсюда «карат». Золото на острове не в ходу. Взвешивай дрова. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Carob: pods of the locust tree, sweet with no sugar. Their seeds once weighed gold, hence 'carat'. Gold is no currency on the island. Weigh firewood instead. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CyprusGoldCup_NAME", "Чёрное золото Кипра (кэроб)", "Cyprus Black Gold (carob drink)"),
        ("CyprusGoldCup_DESC", "Кэроб: стручки рожкового дерева, сладкие без сахара. Их семенами когда-то взвешивали золото, отсюда «карат». Золото на острове не в ходу. Взвешивай дрова.", "Carob: pods of the locust tree, sweet with no sugar. Their seeds once weighed gold, hence 'carat'. Gold is no currency on the island. Weigh firewood instead."),
        ("ErsatzChickpea_NAME", "Эрзац (нутовый кофе)", "Ersatz (chickpea coffee)"),
        ("ErsatzChickpea_DESC", "Нутовый «кофе»: придумали в годы, когда настоящего не было нигде. Название честное: эрзац. Не притворяется, не извиняется. Горячий, коричневый, и на том спасибо. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Chickpea 'coffee': invented in years when the real thing was nowhere to be had. The name is honest: ersatz. No pretence, no apology. Hot, brown, and thanks for that much. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ErsatzChickpeaCup_NAME", "Эрзац (нутовый кофе)", "Ersatz (chickpea coffee)"),
        ("ErsatzChickpeaCup_DESC", "Нутовый «кофе»: придумали в годы, когда настоящего не было нигде. Название честное: эрзац. Не притворяется, не извиняется. Горячий, коричневый, и на том спасибо.", "Chickpea 'coffee': invented in years when the real thing was nowhere to be had. The name is honest: ersatz. No pretence, no apology. Hot, brown, and thanks for that much."),
        ("YellowGlade_NAME", "Жёлтая поляна (кофе из корня одуванчика)", "Yellow Glade (dandelion root coffee)"),
        ("YellowGlade_DESC", "Кофе из корня одуванчика. Летом поляна жёлтая, осенью корни копают и жарят. Одуванчик пережил всё, включая асфальт. Напиток от того, кто знает толк в выживании. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Coffee from dandelion root. In summer the glade is yellow, in autumn the roots are dug and roasted. The dandelion has survived everything, asphalt included. A drink from a survival expert. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("YellowGladeCup_NAME", "Жёлтая поляна (кофе из корня одуванчика)", "Yellow Glade (dandelion root coffee)"),
        ("YellowGladeCup_DESC", "Кофе из корня одуванчика. Летом поляна жёлтая, осенью корни копают и жарят. Одуванчик пережил всё, включая асфальт. Напиток от того, кто знает толк в выживании.", "Coffee from dandelion root. In summer the glade is yellow, in autumn the roots are dug and roasted. The dandelion has survived everything, asphalt included. A drink from a survival expert."),
        ("PilgrimWheat_NAME", "Пилигрим (напиток из пшеницы и патоки)", "Pilgrim (wheat and molasses drink)"),
        ("PilgrimWheat_DESC", "Жареная пшеница с патокой: напиток переселенцев, у которых кофе кончился на полпути. Они дошли. Не все, конечно. Но те, кто пил горячее, шли дольше. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Roasted wheat with molasses: the drink of settlers whose coffee ran out halfway. They made it. Not all of them, of course. But those who drank something hot walked further. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("PilgrimWheatCup_NAME", "Пилигрим (напиток из пшеницы и патоки)", "Pilgrim (wheat and molasses drink)"),
        ("PilgrimWheatCup_DESC", "Жареная пшеница с патокой: напиток переселенцев, у которых кофе кончился на полпути. Они дошли. Не все, конечно. Но те, кто пил горячее, шли дольше.", "Roasted wheat with molasses: the drink of settlers whose coffee ran out halfway. They made it. Not all of them, of course. But those who drank something hot walked further."),
        ("BogatyrOat_NAME", "Богатырь (толокно)", "Bogatyr (toasted oat flour drink)"),
        ("BogatyrOat_DESC", "Толокно: овсяная мука, которую разводят горячей водой. Богатыри ели и шли на Змея. Змея на острове нет, но медведь не меньше. Сначала поешь, потом геройствуй. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Tolokno: toasted oat flour stirred into hot water. The bogatyrs ate it and went off to fight the dragon. The island has no dragon, but the bear is no smaller. Eat first, play the hero after. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("BogatyrOatCup_NAME", "Богатырь (толокно)", "Bogatyr (toasted oat flour drink)"),
        ("BogatyrOatCup_DESC", "Толокно: овсяная мука, которую разводят горячей водой. Богатыри ели и шли на Змея. Змея на острове нет, но медведь не меньше. Сначала поешь, потом геройствуй.", "Tolokno: toasted oat flour stirred into hot water. The bogatyrs ate it and went off to fight the dragon. The island has no dragon, but the bear is no smaller. Eat first, play the hero after."),
        ("GoldenAnchor_NAME", "Золотой якорь (какао-порошок)", "Golden Anchor (cocoa powder)"),
        ("GoldenAnchor_DESC", "Какао-порошок с якорем на пачке: такое варили на камбузе в ночную вахту. Густое, горькое, на воде. Якорь намекает: выпил, и никуда тебя сегодня не унесёт. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Cocoa powder with an anchor on the box: the kind made in the galley on the night watch. Thick, bitter, on water. The anchor hints: drink up and nothing will carry you off tonight. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("GoldenAnchorCup_NAME", "Золотой якорь (какао-порошок)", "Golden Anchor (cocoa powder)"),
        ("GoldenAnchorCup_DESC", "Какао-порошок с якорем на пачке: такое варили на камбузе в ночную вахту. Густое, горькое, на воде. Якорь намекает: выпил, и никуда тебя сегодня не унесёт.", "Cocoa powder with an anchor on the box: the kind made in the galley on the night watch. Thick, bitter, on water. The anchor hints: drink up and nothing will carry you off tonight."),
        ("DutchMill_NAME", "Голландская мельница (алкализованное какао)", "Dutch Mill (Dutch-process cocoa)"),
        ("DutchMill_DESC", "Голландское какао: тёмное, мягкое, без кислинки. Голландцы отвоевали у моря полстраны и знают, как греться на ветру. Мельница на банке крутится от твоей вьюги. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Dutch cocoa: dark, mellow, no sour edge. The Dutch took half their country back from the sea and know how to keep warm in the wind. The mill on the tin turns in your blizzard. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("DutchMillCup_NAME", "Голландская мельница (алкализованное какао)", "Dutch Mill (Dutch-process cocoa)"),
        ("DutchMillCup_DESC", "Голландское какао: тёмное, мягкое, без кислинки. Голландцы отвоевали у моря полстраны и знают, как греться на ветру. Мельница на банке крутится от твоей вьюги.", "Dutch cocoa: dark, mellow, no sour edge. The Dutch took half their country back from the sea and know how to keep warm in the wind. The mill on the tin turns in your blizzard."),
        ("AlpineChocolate_NAME", "Альпийский (горячий шоколад в пакетике)", "Alpine (hot chocolate sachet)"),
        ("AlpineChocolate_DESC", "Горячий шоколад из пакетика: на картинке шале, лыжники и собака с бочонком. Собака с бочонком к тебе не придёт. Придёт волк, и без бочонка. Пей быстрее. Готовится на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "Hot chocolate from a sachet: the picture shows a chalet, skiers and a dog with a little barrel. No dog with a barrel is coming for you. A wolf is, and without a barrel. Drink faster. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("AlpineChocolateCup_NAME", "Альпийский (горячий шоколад в пакетике)", "Alpine (hot chocolate sachet)"),
        ("AlpineChocolateCup_DESC", "Горячий шоколад из пакетика: на картинке шале, лыжники и собака с бочонком. Собака с бочонком к тебе не придёт. Придёт волк, и без бочонка. Пей быстрее.", "Hot chocolate from a sachet: the picture shows a chalet, skiers and a dog with a little barrel. No dog with a barrel is coming for you. A wolf is, and without a barrel. Drink faster."),
        ("DonaCanela_NAME", "Донья Канела (мексиканский шоколад в таблетках)", "Doña Canela (Mexican table chocolate)"),
        ("DonaCanela_DESC", "Мексиканский шоколад в таблетках, с корицей. Донья на этикетке смотрит строго: взбивать положено деревянной мутовкой. Мутовки нет. Донья недовольна, но шоколад всё равно вкусный. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Mexican chocolate in tablets, with cinnamon. The Doña on the label looks stern: it is meant to be frothed with a wooden whisk. You have no whisk. The Doña disapproves, but the chocolate is good anyway. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("DonaCanelaCup_NAME", "Донья Канела (мексиканский шоколад в таблетках)", "Doña Canela (Mexican table chocolate)"),
        ("DonaCanelaCup_DESC", "Мексиканский шоколад в таблетках, с корицей. Донья на этикетке смотрит строго: взбивать положено деревянной мутовкой. Мутовки нет. Донья недовольна, но шоколад всё равно вкусный.", "Mexican chocolate in tablets, with cinnamon. The Doña on the label looks stern: it is meant to be frothed with a wooden whisk. You have no whisk. The Doña disapproves, but the chocolate is good anyway."),
        ("BatangasTablea_NAME", "Таблея Батангас (филиппинская таблея)", "Batangas Tablea (Philippine tablea)"),
        ("BatangasTablea_DESC", "Филиппинская таблея: чистое тёртое какао, скатанное в таблетки. Горькое, жирное, настоящее. На Филиппинах его пьют после тайфуна. После метели тоже подходит. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Philippine tablea: pure ground cacao rolled into tablets. Bitter, rich, the real thing. In the Philippines they drink it after a typhoon. It works after a blizzard just as well. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("BatangasTableaCup_NAME", "Таблея Батангас (филиппинская таблея)", "Batangas Tablea (Philippine tablea)"),
        ("BatangasTableaCup_DESC", "Филиппинская таблея: чистое тёртое какао, скатанное в таблетки. Горькое, жирное, настоящее. На Филиппинах его пьют после тайфуна. После метели тоже подходит.", "Philippine tablea: pure ground cacao rolled into tablets. Bitter, rich, the real thing. In the Philippines they drink it after a typhoon. It works after a blizzard just as well."),
        ("Churreria_NAME", "Чуррерия (шоколад а-ла-таса)", "Churrería (chocolate a la taza)"),
        ("Churreria_DESC", "Испанский шоколад, густой настолько, что в нём стоит чуррос. Чуррос у тебя нет. Можно макать сухарь, палец или надежду. Стоять будет всё. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Spanish chocolate thick enough to stand a churro in. You have no churros. Dip a cracker, a finger or your hopes. Everything will stand. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("ChurreriaCup_NAME", "Чуррерия (шоколад а-ла-таса)", "Churrería (chocolate a la taza)"),
        ("ChurreriaCup_DESC", "Испанский шоколад, густой настолько, что в нём стоит чуррос. Чуррос у тебя нет. Можно макать сухарь, палец или надежду. Стоять будет всё.", "Spanish chocolate thick enough to stand a churro in. You have no churros. Dip a cracker, a finger or your hopes. Everything will stand."),
        ("CacaoShell_NAME", "Какаовелла (чай из какаовеллы)", "Cacao Shell (cacao husk tea)"),
        ("CacaoShell_DESC", "Чай из шелухи какао-бобов: пахнет шоколадом, а на вкус как намёк на шоколад. Отходы шоколадной фабрики. На острове слово «отходы» давно заменено словом «находка». Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Tea from cacao bean husks: smells like chocolate, tastes like a hint of chocolate. Chocolate factory waste. On the island the word 'waste' was long ago replaced by the word 'find'. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CacaoShellCup_NAME", "Какаовелла (чай из какаовеллы)", "Cacao Shell (cacao husk tea)"),
        ("CacaoShellCup_DESC", "Чай из шелухи какао-бобов: пахнет шоколадом, а на вкус как намёк на шоколад. Отходы шоколадной фабрики. На острове слово «отходы» давно заменено словом «находка».", "Tea from cacao bean husks: smells like chocolate, tastes like a hint of chocolate. Chocolate factory waste. On the island the word 'waste' was long ago replaced by the word 'find'."),
        ("Nightcap_NAME", "Ночной колпак (солодовое молоко)", "Nightcap (malted milk)"),
        ("Nightcap_DESC", "Солодовое молоко: напиток, который пьют в пижаме перед сном. На банке нарисован ночной колпак. Твой ночной колпак: шапка, капюшон и вторая шапка. Спокойной ночи. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Malted milk: the drink you take in pyjamas before bed. There is a nightcap on the jar. Your nightcap is a hat, a hood and a second hat. Sleep tight. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("NightcapCup_NAME", "Ночной колпак (солодовое молоко)", "Nightcap (malted milk)"),
        ("NightcapCup_DESC", "Солодовое молоко: напиток, который пьют в пижаме перед сном. На банке нарисован ночной колпак. Твой ночной колпак: шапка, капюшон и вторая шапка. Спокойной ночи.", "Malted milk: the drink you take in pyjamas before bed. There is a nightcap on the jar. Your nightcap is a hat, a hood and a second hat. Sleep tight."),
        ("ChampionMalt_NAME", "Чемпион (шоколадно-солодовый напиток)", "Champion (chocolate malt drink)"),
        ("ChampionMalt_DESC", "Шоколадно-солодовый напиток чемпионов: на банке бегун рвёт ленточку. Ты тоже бегаешь, в основном от кого-то. Ленточки на финише нет, есть дверь, и её надо успеть закрыть. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "The chocolate malt drink of champions: a runner breasts the tape on the tin. You run too, mostly from something. There is no tape at the finish, only a door you have to shut in time. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ChampionMaltCup_NAME", "Чемпион (шоколадно-солодовый напиток)", "Champion (chocolate malt drink)"),
        ("ChampionMaltCup_DESC", "Шоколадно-солодовый напиток чемпионов: на банке бегун рвёт ленточку. Ты тоже бегаешь, в основном от кого-то. Ленточки на финише нет, есть дверь, и её надо успеть закрыть.", "The chocolate malt drink of champions: a runner breasts the tape on the tin. You run too, mostly from something. There is no tape at the finish, only a door you have to shut in time."),
        ("BosphorusSalep_NAME", "Салеп Босфора (салеп)", "Bosphorus Salep (salep)"),
        ("BosphorusSalep_DESC", "Салеп: густой белый напиток из клубней орхидеи, зимой его продают на стамбульских пристанях. Стамбульская зима: это плюс пять и чайки. Салеп сейчас увидит настоящую. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Salep: a thick white drink made from orchid tubers, sold in winter on the Istanbul ferry piers. An Istanbul winter is five above with seagulls. The salep is about to meet a real one. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("BosphorusSalepCup_NAME", "Салеп Босфора (салеп)", "Bosphorus Salep (salep)"),
        ("BosphorusSalepCup_DESC", "Салеп: густой белый напиток из клубней орхидеи, зимой его продают на стамбульских пристанях. Стамбульская зима: это плюс пять и чайки. Салеп сейчас увидит настоящую.", "Salep: a thick white drink made from orchid tubers, sold in winter on the Istanbul ferry piers. An Istanbul winter is five above with seagulls. The salep is about to meet a real one."),
        ("FairSbiten_NAME", "Ярмарочный сбитень (сбитень, концентрат)", "Fair Sbiten (sbiten concentrate)"),
        ("FairSbiten_DESC", "Сбитень: мёд, пряности и травы, главный горячий напиток до того, как появился чай. На ярмарке его разливали из медного бака. Ярмарки нет, зато ты и продавец, и очередь. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Sbiten: honey, spices and herbs, the chief hot drink before tea arrived. At the fair it was poured from a copper urn. There is no fair, but you are both the seller and the queue. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("FairSbitenCup_NAME", "Ярмарочный сбитень (сбитень, концентрат)", "Fair Sbiten (sbiten concentrate)"),
        ("FairSbitenCup_DESC", "Сбитень: мёд, пряности и травы, главный горячий напиток до того, как появился чай. На ярмарке его разливали из медного бака. Ярмарки нет, зато ты и продавец, и очередь.", "Sbiten: honey, spices and herbs, the chief hot drink before tea arrived. At the fair it was poured from a copper urn. There is no fair, but you are both the seller and the queue."),
        ("CranberryKissel_NAME", "Клюквенный брикет (кисель в брикете)", "Cranberry Brick (kissel briquette)"),
        ("CranberryKissel_DESC", "Кисель в брикете: школьники грызли его сухим, хотя на пачке написано «варить». Ты взрослый, одинокий, на острове. Никто не увидит. Но лучше всё-таки свари. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 4.", "Kissel in a brick: schoolchildren gnawed it dry though the wrapper says 'boil'. You are grown up, alone, on an island. Nobody will see. Still, better boil it. Brew it over a fire: put it in a pot with water. Servings: 4."),
        ("CranberryKisselCup_NAME", "Клюквенный брикет (кисель в брикете)", "Cranberry Brick (kissel briquette)"),
        ("CranberryKisselCup_DESC", "Кисель в брикете: школьники грызли его сухим, хотя на пачке написано «варить». Ты взрослый, одинокий, на острове. Никто не увидит. Но лучше всё-таки свари.", "Kissel in a brick: schoolchildren gnawed it dry though the wrapper says 'boil'. You are grown up, alone, on an island. Nobody will see. Still, better boil it."),
        ("TarahumaraPinole_NAME", "Пиноле тараумара (пиноле)", "Tarahumara Pinole (pinole)"),
        ("TarahumaraPinole_DESC", "Пиноле: жареная кукурузная мука. Индейцы тараумара пьют её и бегут сто километров по горам в сандалиях. Ты в трёх парах носков прошёл два и сел. Есть куда расти. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Pinole: toasted corn flour. The Tarahumara drink it and run sixty miles through the mountains in sandals. You did a mile and a half in three pairs of socks and sat down. Room to grow. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("TarahumaraPinoleCup_NAME", "Пиноле тараумара (пиноле)", "Tarahumara Pinole (pinole)"),
        ("TarahumaraPinoleCup_DESC", "Пиноле: жареная кукурузная мука. Индейцы тараумара пьют её и бегут сто километров по горам в сандалиях. Ты в трёх парах носков прошёл два и сел. Есть куда расти.", "Pinole: toasted corn flour. The Tarahumara drink it and run sixty miles through the mountains in sandals. You did a mile and a half in three pairs of socks and sat down. Room to grow."),
        ("GoaChaiLatte_NAME", "Гоа (чай-латте, сухая смесь)", "Goa (chai latte mix)"),
        ("GoaChaiLatte_DESC", "Чай-латте, сухая смесь: чай, молоко, пряности, осталось добавить воду и пляж. Воду ты растопишь. Пляж на острове есть, но на нём лежит лёд и дохлый кит. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Chai latte, dry mix: tea, milk, spices, just add water and a beach. The water you can melt. The island does have a beach, but it has ice and a dead whale on it. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("GoaChaiLatteCup_NAME", "Гоа (чай-латте, сухая смесь)", "Goa (chai latte mix)"),
        ("GoaChaiLatteCup_DESC", "Чай-латте, сухая смесь: чай, молоко, пряности, осталось добавить воду и пляж. Воду ты растопишь. Пляж на острове есть, но на нём лежит лёд и дохлый кит.", "Chai latte, dry mix: tea, milk, spices, just add water and a beach. The water you can melt. The island does have a beach, but it has ice and a dead whale on it."),
        ("UjiMatchaLatte_NAME", "Удзи (матча-латте в стиках)", "Uji (matcha latte sticks)"),
        ("UjiMatchaLatte_DESC", "Матча-латте в стиках: зелёное, сладкое, молочное. В Киото за ним стоит очередь из людей с телефонами. У тебя ни очереди, ни телефона. Зато и фотографировать не надо, можно сразу пить. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Matcha latte in sticks: green, sweet, milky. In Kyoto people queue for it, phones in hand. You have no queue and no phone. No need to photograph it either, you can just drink. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("UjiMatchaLatteCup_NAME", "Удзи (матча-латте в стиках)", "Uji (matcha latte sticks)"),
        ("UjiMatchaLatteCup_DESC", "Матча-латте в стиках: зелёное, сладкое, молочное. В Киото за ним стоит очередь из людей с телефонами. У тебя ни очереди, ни телефона. Зато и фотографировать не надо, можно сразу пить.", "Matcha latte in sticks: green, sweet, milky. In Kyoto people queue for it, phones in hand. You have no queue and no phone. No need to photograph it either, you can just drink."),
        ("HaldiGold_NAME", "Халди (золотое молоко с куркумой)", "Haldi (turmeric golden milk)"),
        ("HaldiGold_DESC", "Золотое молоко с куркумой: индийские бабушки дают его от всего, от кашля до разбитого сердца. Жёлтое пятно на кружке останется навсегда. Как память о бабушках. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Golden milk with turmeric: Indian grandmothers prescribe it for everything from a cough to a broken heart. The yellow stain on the mug is permanent. A keepsake from the grandmothers. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("HaldiGoldCup_NAME", "Халди (золотое молоко с куркумой)", "Haldi (turmeric golden milk)"),
        ("HaldiGoldCup_DESC", "Золотое молоко с куркумой: индийские бабушки дают его от всего, от кашля до разбитого сердца. Жёлтое пятно на кружке останется навсегда. Как память о бабушках.", "Golden milk with turmeric: Indian grandmothers prescribe it for everything from a cough to a broken heart. The yellow stain on the mug is permanent. A keepsake from the grandmothers."),
        ("LhasaPoCha_NAME", "Лхаса (тибетский чай с маслом)", "Lhasa (Tibetan butter tea)"),
        ("LhasaPoCha_DESC", "Тибетский чай с маслом и солью. Первая мысль: зачем. Вторая, после часа на ветру: ещё. Тибетцы пьют по сорок чашек в день и живут там, где другим нечем дышать. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Tibetan tea with butter and salt. First thought: why. Second thought, after an hour in the wind: more. Tibetans drink forty cups a day and live where others can't breathe. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("LhasaPoChaCup_NAME", "Лхаса (тибетский чай с маслом)", "Lhasa (Tibetan butter tea)"),
        ("LhasaPoChaCup_DESC", "Тибетский чай с маслом и солью. Первая мысль: зачем. Вторая, после часа на ветру: ещё. Тибетцы пьют по сорок чашек в день и живут там, где другим нечем дышать.", "Tibetan tea with butter and salt. First thought: why. Second thought, after an hour in the wind: more. Tibetans drink forty cups a day and live where others can't breathe."),
        ("SteppeSuutei_NAME", "Степняк (монгольский сутэй цай)", "Steppe Rider (Mongolian suutei tsai)"),
        ("SteppeSuutei_DESC", "Монгольский сутэй цай: чай, молоко, соль, иногда жир. Степняк пьёт его в юрте, пока снаружи минус сорок. Наконец-то рецепт от людей, которые понимают твою погоду. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Mongolian suutei tsai: tea, milk, salt, sometimes fat. The herdsman drinks it in his yurt while it is forty below outside. At last a recipe from people who understand your weather. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("SteppeSuuteiCup_NAME", "Степняк (монгольский сутэй цай)", "Steppe Rider (Mongolian suutei tsai)"),
        ("SteppeSuuteiCup_DESC", "Монгольский сутэй цай: чай, молоко, соль, иногда жир. Степняк пьёт его в юрте, пока снаружи минус сорок. Наконец-то рецепт от людей, которые понимают твою погоду.", "Mongolian suutei tsai: tea, milk, salt, sometimes fat. The herdsman drinks it in his yurt while it is forty below outside. At last a recipe from people who understand your weather."),
        ("GoheungYuja_NAME", "Юдзу Кохына (юджа-ча, цитроновый чай)", "Goheung Yuja (yuja-cha citron tea)"),
        ("GoheungYuja_DESC", "Корейский цитрон в меду: ложка на кружку кипятка, и в хижине пахнет так, будто кто-то чистит мандарины. Никто не чистит. Ты один. Но запах честно старается. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Korean citron in honey: a spoonful to a mug of hot water and the cabin smells as if someone were peeling tangerines. Nobody is. You are alone. But the smell is doing its honest best. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("GoheungYujaCup_NAME", "Юдзу Кохына (юджа-ча, цитроновый чай)", "Goheung Yuja (yuja-cha citron tea)"),
        ("GoheungYujaCup_DESC", "Корейский цитрон в меду: ложка на кружку кипятка, и в хижине пахнет так, будто кто-то чистит мандарины. Никто не чистит. Ты один. Но запах честно старается.", "Korean citron in honey: a spoonful to a mug of hot water and the cabin smells as if someone were peeling tangerines. Nobody is. You are alone. But the smell is doing its honest best."),
        ("Ssanghwa_NAME", "Ссанхва (ссанхва-ча, корейский сбор)", "Ssanghwa (ssanghwa-cha herbal tonic)"),
        ("Ssanghwa_DESC", "Ссанхва-ча: девять корней и трав, тёмный, горько-сладкий. В Корее его пьют, когда сил нет вообще. Судя по тому, как ты поднимался на этот холм, тебе двойную порцию. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Ssanghwa-cha: nine roots and herbs, dark and bittersweet. In Korea they drink it when there is no strength left at all. Judging by how you climbed that hill, make yours a double. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("SsanghwaCup_NAME", "Ссанхва (ссанхва-ча, корейский сбор)", "Ssanghwa (ssanghwa-cha herbal tonic)"),
        ("SsanghwaCup_DESC", "Ссанхва-ча: девять корней и трав, тёмный, горько-сладкий. В Корее его пьют, когда сил нет вообще. Судя по тому, как ты поднимался на этот холм, тебе двойную порцию.", "Ssanghwa-cha: nine roots and herbs, dark and bittersweet. In Korea they drink it when there is no strength left at all. Judging by how you climbed that hill, make yours a double."),
        ("FiveFlavours_NAME", "Пять вкусов (омиджа-ча, лимонник)", "Five Flavours (omija-cha, schisandra tea)"),
        ("FiveFlavours_DESC", "Ягоды лимонника: сладкие, кислые, горькие, солёные и острые сразу. Пять вкусов в одной кружке. На острове обычно один вкус, «консервы», так что держись за стул. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Schisandra berries: sweet, sour, bitter, salty and pungent all at once. Five flavours in one mug. The island usually offers one flavour, 'tinned', so hold on to your chair. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("FiveFlavoursCup_NAME", "Пять вкусов (омиджа-ча, лимонник)", "Five Flavours (omija-cha, schisandra tea)"),
        ("FiveFlavoursCup_DESC", "Ягоды лимонника: сладкие, кислые, горькие, солёные и острые сразу. Пять вкусов в одной кружке. На острове обычно один вкус, «консервы», так что держись за стул.", "Schisandra berries: sweet, sour, bitter, salty and pungent all at once. Five flavours in one mug. The island usually offers one flavour, 'tinned', so hold on to your chair."),
        ("PeakLemonTea_NAME", "Виктория-пик (гранулированный чай с лимоном)", "Victoria Peak (instant lemon tea granules)"),
        ("PeakLemonTea_DESC", "Гранулированный чай с лимоном: в Гонконге его пьют в кафе под вентилятором. Лимона в нём нет, чая немного, зато сладко и жёлто. Вентилятор тебе заменит сквозняк. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Granulated lemon tea: in Hong Kong it is drunk in cafés under a ceiling fan. It contains no lemon and not much tea, but it is sweet and yellow. The draught will be your fan. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("PeakLemonTeaCup_NAME", "Виктория-пик (гранулированный чай с лимоном)", "Victoria Peak (instant lemon tea granules)"),
        ("PeakLemonTeaCup_DESC", "Гранулированный чай с лимоном: в Гонконге его пьют в кафе под вентилятором. Лимона в нём нет, чая немного, зато сладко и жёлто. Вентилятор тебе заменит сквозняк.", "Granulated lemon tea: in Hong Kong it is drunk in cafés under a ceiling fan. It contains no lemon and not much tea, but it is sweet and yellow. The draught will be your fan."),
        ("CascaraRoja_NAME", "Каскара Роха (каскара, кофейная ягода)", "Cascara Roja (cascara, coffee cherry tea)"),
        ("CascaraRoja_DESC", "Каскара: сушёная мякоть кофейной ягоды. Зерно уехало в кофейни, шкурка досталась фермерам. На вкус как шиповник с изюмом. На острове шкурки тоже никто не выбрасывает. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Cascara: the dried flesh of the coffee cherry. The bean went off to the cafés, the skin stayed with the farmers. It tastes of rosehip and raisins. Nobody throws skins away on the island either. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CascaraRojaCup_NAME", "Каскара Роха (каскара, кофейная ягода)", "Cascara Roja (cascara, coffee cherry tea)"),
        ("CascaraRojaCup_DESC", "Каскара: сушёная мякоть кофейной ягоды. Зерно уехало в кофейни, шкурка досталась фермерам. На вкус как шиповник с изюмом. На острове шкурки тоже никто не выбрасывает.", "Cascara: the dried flesh of the coffee cherry. The bean went off to the cafés, the skin stayed with the farmers. It tastes of rosehip and raisins. Nobody throws skins away on the island either."),
        ("SanaaQishr_NAME", "Кишр Саны (кишр, кофейная шелуха с имбирём)", "Sana'a Qishr (qishr, coffee husks with ginger)"),
        ("SanaaQishr_DESC", "Кишр: йеменцы продали зерно всему миру, а сами пьют шелуху с имбирём. И считают, что выиграли. Попробуешь в мороз и согласишься: имбирь греет до пяток. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Qishr: the Yemenis sold the beans to the whole world and drink the husks with ginger themselves. And reckon they got the better deal. Try it in the frost and you will agree: the ginger warms you to the heels. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("SanaaQishrCup_NAME", "Кишр Саны (кишр, кофейная шелуха с имбирём)", "Sana'a Qishr (qishr, coffee husks with ginger)"),
        ("SanaaQishrCup_DESC", "Кишр: йеменцы продали зерно всему миру, а сами пьют шелуху с имбирём. И считают, что выиграли. Попробуешь в мороз и согласишься: имбирь греет до пяток.", "Qishr: the Yemenis sold the beans to the whole world and drink the husks with ginger themselves. And reckon they got the better deal. Try it in the frost and you will agree: the ginger warms you to the heels."),
        ("AmazonEye_NAME", "Глаз Амазонки (гуарана, порошок)", "Amazon Eye (guarana powder)"),
        ("AmazonEye_DESC", "Семена гуараны похожи на глаза, и по легенде это глаза лесного духа, который видит всё. Кофеина втрое больше, чем в кофе. После кружки ты тоже видишь всё. И не моргаешь. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Guarana seeds look like eyes, and legend says they are the eyes of a forest spirit who sees everything. Three times the caffeine of coffee. After a cup you see everything too. Without blinking. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("AmazonEyeCup_NAME", "Глаз Амазонки (гуарана, порошок)", "Amazon Eye (guarana powder)"),
        ("AmazonEyeCup_DESC", "Семена гуараны похожи на глаза, и по легенде это глаза лесного духа, который видит всё. Кофеина втрое больше, чем в кофе. После кружки ты тоже видишь всё. И не моргаешь.", "Guarana seeds look like eyes, and legend says they are the eyes of a forest spirit who sees everything. Three times the caffeine of coffee. After a cup you see everything too. Without blinking."),
        ("GrenadierBeefTea_NAME", "Гренадер (мясной чай, говяжий экстракт)", "Grenadier (beef tea extract)"),
        ("GrenadierBeefTea_DESC", "Мясной чай: говяжий экстракт, ложка на кружку кипятка. Им поили солдат, полярников и больных. Ты подходишь по всем трём пунктам сразу, так что тебе полагается добавка. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Beef tea: beef extract, a spoonful to a mug of hot water. It was fed to soldiers, polar explorers and invalids. You qualify on all three counts at once, so you are due seconds. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("GrenadierBeefTeaCup_NAME", "Гренадер (мясной чай, говяжий экстракт)", "Grenadier (beef tea extract)"),
        ("GrenadierBeefTeaCup_DESC", "Мясной чай: говяжий экстракт, ложка на кружку кипятка. Им поили солдат, полярников и больных. Ты подходишь по всем трём пунктам сразу, так что тебе полагается добавка.", "Beef tea: beef extract, a spoonful to a mug of hot water. It was fed to soldiers, polar explorers and invalids. You qualify on all three counts at once, so you are due seconds."),
        ("KelpTea_NAME", "Морской лист (кобутя, чай из ламинарии)", "Sea Leaf (kobucha, kelp tea)"),
        ("KelpTea_DESC", "Чай из ламинарии: солёный, морской, на вкус как суп, который стесняется. Японцы пьют его для здоровья. Море у тебя рядом, но оно замёрзло и пахнет китом. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Kelp tea: salty, briny, tasting like a soup that is shy. The Japanese drink it for their health. You have a sea nearby, but it is frozen and smells of whale. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("KelpTeaCup_NAME", "Морской лист (кобутя, чай из ламинарии)", "Sea Leaf (kobucha, kelp tea)"),
        ("KelpTeaCup_DESC", "Чай из ламинарии: солёный, морской, на вкус как суп, который стесняется. Японцы пьют его для здоровья. Море у тебя рядом, но оно замёрзло и пахнет китом.", "Kelp tea: salty, briny, tasting like a soup that is shy. The Japanese drink it for their health. You have a sea nearby, but it is frozen and smells of whale."),
        ("SakuraSalt_NAME", "Сакура в соли (сакура-ю, чай из цветков сакуры)", "Salted Sakura (sakurayu, cherry blossom tea)"),
        ("SakuraSalt_DESC", "Цветки сакуры в соли: в кипятке распускаются, как на ветке. Подают на свадьбах, на счастье. Свадеб на острове не предвидится. Выпей за то, что дожил до вечера. Тоже счастье. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Cherry blossoms in salt: in hot water they open as if on the branch. Served at weddings, for luck. No weddings are expected on the island. Drink to having lived until evening. That is luck too. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SakuraSaltCup_NAME", "Сакура в соли (сакура-ю, чай из цветков сакуры)", "Salted Sakura (sakurayu, cherry blossom tea)"),
        ("SakuraSaltCup_DESC", "Цветки сакуры в соли: в кипятке распускаются, как на ветке. Подают на свадьбах, на счастье. Свадеб на острове не предвидится. Выпей за то, что дожил до вечера. Тоже счастье.", "Cherry blossoms in salt: in hot water they open as if on the branch. Served at weddings, for luck. No weddings are expected on the island. Drink to having lived until evening. That is luck too."),
        ("RossoBar_NAME", "Россо Бар (итальянский эспрессо)", "Rosso Bar (Italian espresso)"),
        ("RossoBar_DESC", "Эспрессо как в баре у вокзала: красная банка, густая пенка, три глотка. Бармен кивает и не задаёт вопросов. На острове вопросов тоже никто не задаёт. Некому. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Espresso like at the bar by the station: red tin, thick crema, three sips. The barman nods and asks no questions. Nobody asks questions on the island either. There is nobody. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("RossoBarCup_NAME", "Россо Бар (итальянский эспрессо)", "Rosso Bar (Italian espresso)"),
        ("RossoBarCup_DESC", "Эспрессо как в баре у вокзала: красная банка, густая пенка, три глотка. Бармен кивает и не задаёт вопросов. На острове вопросов тоже никто не задаёт. Некому.", "Espresso like at the bar by the station: red tin, thick crema, three sips. The barman nods and asks no questions. Nobody asks questions on the island either. There is nobody."),
        ("OroMoka_NAME", "Оро Мока (молотый для гейзерной кофеварки)", "Oro Moka (ground for the moka pot)"),
        ("OroMoka_DESC", "Помол для гейзерной кофеварки: она булькает и фыркает на плите, как довольный зверь. Довольных зверей на острове больше нет, так что звук уникальный. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Ground for the moka pot: it gurgles and snorts on the stove like a contented animal. The island has no other contented animals, so the sound is one of a kind. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("OroMokaCup_NAME", "Оро Мока (молотый для гейзерной кофеварки)", "Oro Moka (ground for the moka pot)"),
        ("OroMokaCup_DESC", "Помол для гейзерной кофеварки: она булькает и фыркает на плите, как довольный зверь. Довольных зверей на острове больше нет, так что звук уникальный.", "Ground for the moka pot: it gurgles and snorts on the stove like a contented animal. The island has no other contented animals, so the sound is one of a kind."),
        ("DinerRed_NAME", "Красная банка (американский молотый)", "Big Red Can (American ground coffee)"),
        ("DinerRed_DESC", "Большая красная банка из любой американской закусочной. Официантка подливает его бесконечно. Здесь подливаешь себе сам, и «бесконечно» кончается на дне банки. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "The big red can from every American diner. The waitress keeps refilling it forever. Here you do your own refills, and forever ends at the bottom of the can. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("DinerRedCup_NAME", "Красная банка (американский молотый)", "Big Red Can (American ground coffee)"),
        ("DinerRedCup_DESC", "Большая красная банка из любой американской закусочной. Официантка подливает его бесконечно. Здесь подливаешь себе сам, и «бесконечно» кончается на дне банки.", "The big red can from every American diner. The waitress keeps refilling it forever. Here you do your own refills, and forever ends at the bottom of the can."),
        ("BluePercolator_NAME", "Синий перколятор (кофе для перколятора)", "Blue Percolator (percolator grind)"),
        ("BluePercolator_DESC", "Кофе для перколятора: синий эмалированный кофейник у костра, булькает в стеклянной крышечке. Вкус детства в походе. Тогда медведи были только в мультиках. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 12.", "Coffee for the percolator: a blue enamel pot by the fire, bubbling in its little glass knob. The taste of childhood camping trips. Back then bears lived only in cartoons. Brew it over a fire: put it in a pot with water. Servings: 12."),
        ("BluePercolatorCup_NAME", "Синий перколятор (кофе для перколятора)", "Blue Percolator (percolator grind)"),
        ("BluePercolatorCup_DESC", "Кофе для перколятора: синий эмалированный кофейник у костра, булькает в стеклянной крышечке. Вкус детства в походе. Тогда медведи были только в мультиках.", "Coffee for the percolator: a blue enamel pot by the fire, bubbling in its little glass knob. The taste of childhood camping trips. Back then bears lived only in cartoons."),
        ("HanoiThreeInOne_NAME", "Ханой 3 в 1 (вьетнамский кофе 3 в 1)", "Hanoi 3-in-1 (Vietnamese 3-in-1 coffee)"),
        ("HanoiThreeInOne_DESC", "Ханойский 3 в 1: сладкий настолько, что ложка задумывается. Вьетнамцы пьют его, сидя на крошечных табуретках у дороги. Табуретку ты вчера сжёг. Пей стоя. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Hanoi 3-in-1: sweet enough to give the spoon pause. The Vietnamese drink it perched on tiny stools by the road. You burned the stool yesterday. Drink standing. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("HanoiThreeInOneCup_NAME", "Ханой 3 в 1 (вьетнамский кофе 3 в 1)", "Hanoi 3-in-1 (Vietnamese 3-in-1 coffee)"),
        ("HanoiThreeInOneCup_DESC", "Ханойский 3 в 1: сладкий настолько, что ложка задумывается. Вьетнамцы пьют его, сидя на крошечных табуретках у дороги. Табуретку ты вчера сжёг. Пей стоя.", "Hanoi 3-in-1: sweet enough to give the spoon pause. The Vietnamese drink it perched on tiny stools by the road. You burned the stool yesterday. Drink standing."),
        ("HavanaOscuro_NAME", "Гавана Оскуро (кубинский тёмный молотый)", "Havana Oscuro (Cuban dark ground coffee)"),
        ("HavanaOscuro_DESC", "Гаванская тёмная обжарка: под неё играют в домино и спорят до утра. Домино нет, спорить не с кем, но до утра ты после неё досидишь гарантированно. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Havana dark roast: it goes with dominoes and arguing until dawn. You have no dominoes and nobody to argue with, but after this you will make it to dawn, guaranteed. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("HavanaOscuroCup_NAME", "Гавана Оскуро (кубинский тёмный молотый)", "Havana Oscuro (Cuban dark ground coffee)"),
        ("HavanaOscuroCup_DESC", "Гаванская тёмная обжарка: под неё играют в домино и спорят до утра. Домино нет, спорить не с кем, но до утра ты после неё досидишь гарантированно.", "Havana dark roast: it goes with dominoes and arguing until dawn. You have no dominoes and nobody to argue with, but after this you will make it to dawn, guaranteed."),
        ("BrownTin_NAME", "Коричневая жестянка (индийский растворимый порошок)", "The Brown Tin (Indian instant powder)"),
        ("BrownTin_DESC", "Индийский растворимый порошок в коричневой жестянке, которую бабушки потом полвека используют под пуговицы. Допьёшь: клади туда рыболовные крючки. Традиция. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Indian instant powder in a brown tin that grandmothers then use for buttons for half a century. When it is empty, keep your fish hooks in it. Tradition. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("BrownTinCup_NAME", "Коричневая жестянка (индийский растворимый порошок)", "The Brown Tin (Indian instant powder)"),
        ("BrownTinCup_DESC", "Индийский растворимый порошок в коричневой жестянке, которую бабушки потом полвека используют под пуговицы. Допьёшь: клади туда рыболовные крючки. Традиция.", "Indian instant powder in a brown tin that grandmothers then use for buttons for half a century. When it is empty, keep your fish hooks in it. Tradition."),
        ("PeoplesBlend_NAME", "Народный (кофейный напиток с цикорием)", "People's Blend (coffee drink with chicory)"),
        ("PeoplesBlend_DESC", "Кофейный напиток «Народный»: кофе в нём процентов десять, остальное цикорий и вера в лучшее. Народ пил и не жаловался. Народу на острове сейчас ровно один, и он тоже не жалуется. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "The 'People's Blend' coffee drink: about ten per cent coffee, the rest chicory and faith in better days. The people drank it without complaint. The people on the island now number exactly one, also not complaining. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("PeoplesBlendCup_NAME", "Народный (кофейный напиток с цикорием)", "People's Blend (coffee drink with chicory)"),
        ("PeoplesBlendCup_DESC", "Кофейный напиток «Народный»: кофе в нём процентов десять, остальное цикорий и вера в лучшее. Народ пил и не жаловался. Народу на острове сейчас ровно один, и он тоже не жалуется.", "The 'People's Blend' coffee drink: about ten per cent coffee, the rest chicory and faith in better days. The people drank it without complaint. The people on the island now number exactly one, also not complaining."),
        ("RationFive_NAME", "Паёк №5 (кофе в таблетках)", "Ration No. 5 (coffee tablets)"),
        ("RationFive_DESC", "Кофе в таблетках из пайка: можно растворить, можно сгрызть на ходу. Второй способ придумали те, у кого не было времени на костёр. Ты их отлично понимаешь. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Coffee tablets from a ration pack: dissolve one or chew it on the move. The second method was invented by people with no time for a fire. You understand them perfectly. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("RationFiveCup_NAME", "Паёк №5 (кофе в таблетках)", "Ration No. 5 (coffee tablets)"),
        ("RationFiveCup_DESC", "Кофе в таблетках из пайка: можно растворить, можно сгрызть на ходу. Второй способ придумали те, у кого не было времени на костёр. Ты их отлично понимаешь.", "Coffee tablets from a ration pack: dissolve one or chew it on the move. The second method was invented by people with no time for a fire. You understand them perfectly."),
        ("CremaPod_NAME", "Крема Чалда (кофе в чалдах)", "Crema Pod (coffee pods)"),
        ("CremaPod_DESC", "Кофе в чалдах: бумажные таблетки для кофемашины. Кофемашина стоит на чьей-то кухне и без света не работает. В ночь сияния можно попробовать. Но рядом заискрит и тостер. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Coffee pods: paper discs for an espresso machine. The machine sits in a kitchen and won't run without power. You could try on an aurora night. But the toaster next to it will spark too. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("CremaPodCup_NAME", "Крема Чалда (кофе в чалдах)", "Crema Pod (coffee pods)"),
        ("CremaPodCup_DESC", "Кофе в чалдах: бумажные таблетки для кофемашины. Кофемашина стоит на чьей-то кухне и без света не работает. В ночь сияния можно попробовать. Но рядом заискрит и тостер.", "Coffee pods: paper discs for an espresso machine. The machine sits in a kitchen and won't run without power. You could try on an aurora night. But the toaster next to it will spark too."),
        ("CopperCezve_NAME", "Медная джезва (кофе по-турецки, помол в пыль)", "Copper Cezve (Turkish coffee, ground to dust)"),
        ("CopperCezve_DESC", "Помол в пыль для джезвы. Варят на песке, не дают закипеть, потом гадают на гуще. Гуща на дне твоей кружки всегда показывает одно и то же: снег и дальнюю дорогу. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Ground to dust for the cezve. Brewed on hot sand, never allowed to boil, and then the grounds tell your fortune. Yours always show the same thing: snow and a long road. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CopperCezveCup_NAME", "Медная джезва (кофе по-турецки, помол в пыль)", "Copper Cezve (Turkish coffee, ground to dust)"),
        ("CopperCezveCup_DESC", "Помол в пыль для джезвы. Варят на песке, не дают закипеть, потом гадают на гуще. Гуща на дне твоей кружки всегда показывает одно и то же: снег и дальнюю дорогу.", "Ground to dust for the cezve. Brewed on hot sand, never allowed to boil, and then the grounds tell your fortune. Yours always show the same thing: snow and a long road."),
        ("MochaJava_NAME", "Мокко-Ява (старейший купаж мира)", "Mocha Java (the world's oldest blend)"),
        ("MochaJava_DESC", "Старейший купаж в мире: йеменский мокко плюс яванский. Триста лет его никто не смог улучшить. На острове тоже ничего не улучшается, но там это заслуга, а тут погода. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "The oldest blend in the world: Yemeni mocha plus Java. Nobody has managed to improve it in three hundred years. Nothing improves on the island either, but there it is merit and here it is the weather. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("MochaJavaCup_NAME", "Мокко-Ява (старейший купаж мира)", "Mocha Java (the world's oldest blend)"),
        ("MochaJavaCup_DESC", "Старейший купаж в мире: йеменский мокко плюс яванский. Триста лет его никто не смог улучшить. На острове тоже ничего не улучшается, но там это заслуга, а тут погода.", "The oldest blend in the world: Yemeni mocha plus Java. Nobody has managed to improve it in three hundred years. Nothing improves on the island either, but there it is merit and here it is the weather."),
        ("IrishCreamBean_NAME", "Ирландские сливки (ароматизированный кофе)", "Irish Cream Roast (flavoured coffee)"),
        ("IrishCreamBean_DESC", "Кофе с запахом ирландского ликёра. Самого ликёра в нём ноль. Обман, но тёплый и добрый. Настоящую бутылку кто-то наверняка спрятал в подвале. Ищи. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee that smells of Irish cream liqueur. Actual liqueur content: zero. A lie, but a warm and kindly one. Someone surely hid a real bottle in a cellar. Keep looking. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("IrishCreamBeanCup_NAME", "Ирландские сливки (ароматизированный кофе)", "Irish Cream Roast (flavoured coffee)"),
        ("IrishCreamBeanCup_DESC", "Кофе с запахом ирландского ликёра. Самого ликёра в нём ноль. Обман, но тёплый и добрый. Настоящую бутылку кто-то наверняка спрятал в подвале. Ищи.", "Coffee that smells of Irish cream liqueur. Actual liqueur content: zero. A lie, but a warm and kindly one. Someone surely hid a real bottle in a cellar. Keep looking."),
        ("CowAndBean_NAME", "Бурёнка и зерно (кофе со сгущённым молоком)", "Cow & Bean (coffee with condensed milk)"),
        ("CowAndBean_DESC", "Кофе со сгущёнкой в одной банке: ложка на кружку, и готово. На этикетке корова, довольная жизнью. Она не знает, что стало с оленями на этом острове. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Coffee and condensed milk in a single tin: a spoonful to a mug and done. The label shows a cow content with life. She has no idea what happens to the deer on this island. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("CowAndBeanCup_NAME", "Бурёнка и зерно (кофе со сгущённым молоком)", "Cow & Bean (coffee with condensed milk)"),
        ("CowAndBeanCup_DESC", "Кофе со сгущёнкой в одной банке: ложка на кружку, и готово. На этикетке корова, довольная жизнью. Она не знает, что стало с оленями на этом острове.", "Coffee and condensed milk in a single tin: a spoonful to a mug and done. The label shows a cow content with life. She has no idea what happens to the deer on this island."),
        ("DoubleCharge_NAME", "Двойной заряд (двойной эспрессо в банке)", "Double Charge (canned double espresso)"),
        ("DoubleCharge_DESC", "Двойной эспрессо в банке. Для тех, кому надо было проснуться ещё вчера. Открываешь: сердце стучит в ушах, руки готовы рубить лес. Спать не предлагать. Пьётся холодным, огонь не нужен.", "A double espresso in a can. For those who needed to be awake since yesterday. Crack it open: heart pounding in your ears, hands ready to fell a forest. Sleep is off the menu. Drunk cold, no fire needed."),
        ("TheVeryOne_NAME", "Тот самый (индийский чёрный байховый)", "The Very One (Indian black leaf tea)"),
        ("TheVeryOne_DESC", "Тот самый чай, за которым стояли в очереди, а потом заваривали по три раза. На пачке слон. Слон видел многое, но чтобы пачку нашли на замёрзшем острове: такое впервые. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "The very tea people queued for and then brewed three times over. There is an elephant on the packet. The elephant has seen a lot, but being found on a frozen island is a first. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("TheVeryOneCup_NAME", "Тот самый (индийский чёрный байховый)", "The Very One (Indian black leaf tea)"),
        ("TheVeryOneCup_DESC", "Тот самый чай, за которым стояли в очереди, а потом заваривали по три раза. На пачке слон. Слон видел многое, но чтобы пачку нашли на замёрзшем острове: такое впервые.", "The very tea people queued for and then brewed three times over. There is an elephant on the packet. The elephant has seen a lot, but being found on a frozen island is a first."),
        ("TeaNo36_NAME", "Чай №36 (купаж грузинского и индийского)", "Tea No. 36 (Georgian and Indian blend)"),
        ("TeaNo36_DESC", "Чай №36: грузинский пополам с индийским. Что стало с первыми тридцатью пятью, история молчит. Заваривай крепче и не задавай вопросов, как было принято. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Tea No. 36: half Georgian, half Indian. What became of the first thirty-five, history does not say. Brew it strong and ask no questions, as was the custom. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("TeaNo36Cup_NAME", "Чай №36 (купаж грузинского и индийского)", "Tea No. 36 (Georgian and Indian blend)"),
        ("TeaNo36Cup_DESC", "Чай №36: грузинский пополам с индийским. Что стало с первыми тридцатью пятью, история молчит. Заваривай крепче и не задавай вопросов, как было принято.", "Tea No. 36: half Georgian, half Indian. What became of the first thirty-five, history does not say. Brew it strong and ask no questions, as was the custom."),
        ("GoldPennant_NAME", "Золотой флажок (чёрный чай в пакетиках)", "Gold Pennant (black tea bags)"),
        ("GoldPennant_DESC", "Пакетики с жёлтым флажком на нитке. Такой чай лежит в любой гостинице мира, от Дубая до Милтона. Постояльцы уехали, флажок остался. Капитуляции не будет. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Bags with a yellow tag on a string. This tea sits in every hotel in the world, from Dubai to Milton. The guests left, the flag stayed. There will be no surrender. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("GoldPennantCup_NAME", "Золотой флажок (чёрный чай в пакетиках)", "Gold Pennant (black tea bags)"),
        ("GoldPennantCup_DESC", "Пакетики с жёлтым флажком на нитке. Такой чай лежит в любой гостинице мира, от Дубая до Милтона. Постояльцы уехали, флажок остался. Капитуляции не будет.", "Bags with a yellow tag on a string. This tea sits in every hotel in the world, from Dubai to Milton. The guests left, the flag stayed. There will be no surrender."),
        ("DalesBrew_NAME", "Долины (крепкий английский купаж)", "Dales Brew (strong English blend)"),
        ("DalesBrew_DESC", "Крепкий купаж из английских долин, где дождь идёт вбок, а овцы не обращают внимания. Там чаем лечат всё, от простуды до плохих новостей. Новости у тебя плохие. Лечись. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "A strong blend from the English dales, where the rain falls sideways and the sheep pay no mind. Tea cures everything there, from a cold to bad news. Your news is bad. Take the cure. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("DalesBrewCup_NAME", "Долины (крепкий английский купаж)", "Dales Brew (strong English blend)"),
        ("DalesBrewCup_DESC", "Крепкий купаж из английских долин, где дождь идёт вбок, а овцы не обращают внимания. Там чаем лечат всё, от простуды до плохих новостей. Новости у тебя плохие. Лечись.", "A strong blend from the English dales, where the rain falls sideways and the sheep pay no mind. Tea cures everything there, from a cold to bad news. Your news is bad. Take the cure."),
        ("BuildersBrew_NAME", "Чай строителя (очень крепкий чай с молоком)", "Builder's Brew (very strong tea with milk)"),
        ("BuildersBrew_DESC", "Чай строителя: два пакетика, молоко, заваривать, пока не станет цвета кирпича. Пьют на лесах в любую погоду. Починил на верстаке топор: заслужил кружку. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Builder's tea: two bags, milk, brewed until it is the colour of brick. Drunk on the scaffolding in all weathers. Mended your hatchet at the workbench? You have earned a mug. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("BuildersBrewCup_NAME", "Чай строителя (очень крепкий чай с молоком)", "Builder's Brew (very strong tea with milk)"),
        ("BuildersBrewCup_DESC", "Чай строителя: два пакетика, молоко, заваривать, пока не станет цвета кирпича. Пьют на лесах в любую погоду. Починил на верстаке топор: заслужил кружку.", "Builder's tea: two bags, milk, brewed until it is the colour of brick. Drunk on the scaffolding in all weathers. Mended your hatchet at the workbench? You have earned a mug."),
        ("LadyOrange_NAME", "Леди Апельсин (чёрный с цедрой и бергамотом)", "Lady Orange (black with citrus peel and bergamot)"),
        ("LadyOrange_DESC", "Чай для леди: бергамот, апельсиновая цедра, фарфор. Леди пьёт его, отставив мизинец. Ты пьёшь, отставив обмороженный мизинец. Манеры есть манеры. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "A tea for a lady: bergamot, orange peel, bone china. The lady drinks with her little finger raised. You drink with your frostbitten little finger raised. Manners are manners. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("LadyOrangeCup_NAME", "Леди Апельсин (чёрный с цедрой и бергамотом)", "Lady Orange (black with citrus peel and bergamot)"),
        ("LadyOrangeCup_DESC", "Чай для леди: бергамот, апельсиновая цедра, фарфор. Леди пьёт его, отставив мизинец. Ты пьёшь, отставив обмороженный мизинец. Манеры есть манеры.", "A tea for a lady: bergamot, orange peel, bone china. The lady drinks with her little finger raised. You drink with your frostbitten little finger raised. Manners are manners."),
        ("SaharaCamel_NAME", "Верблюд Сахары (зелёный «порох»)", "Sahara Camel (gunpowder green tea)"),
        ("SaharaCamel_DESC", "Зелёный «порох», любимый чай Сахары: его варят на углях с мятой и горой сахара. Верблюд на пачке не пил две недели и спокоен. Бери пример. Хотя нет, пей. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Green gunpowder, the favourite tea of the Sahara: boiled on coals with mint and a heap of sugar. The camel on the box hasn't had a drink in two weeks and is calm. Follow its example. Actually no, drink. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("SaharaCamelCup_NAME", "Верблюд Сахары (зелёный «порох»)", "Sahara Camel (gunpowder green tea)"),
        ("SaharaCamelCup_DESC", "Зелёный «порох», любимый чай Сахары: его варят на углях с мятой и горой сахара. Верблюд на пачке не пил две недели и спокоен. Бери пример. Хотя нет, пей.", "Green gunpowder, the favourite tea of the Sahara: boiled on coals with mint and a heap of sugar. The camel on the box hasn't had a drink in two weeks and is calm. Follow its example. Actually no, drink."),
        ("MugiCan_NAME", "Муги (холодный ячменный чай)", "Mugi (cold barley tea)"),
        ("MugiCan_DESC", "Холодный ячменный чай в банке: в Японии им спасаются от жары. От жары. Перечитай это слово. Теперь посмотри в окно. Теперь выпей, пока не замёрзло. Пьётся холодным, огонь не нужен.", "Cold barley tea in a can: in Japan it saves people from the heat. The heat. Read that word again. Now look out of the window. Now drink it before it freezes. Drunk cold, no fire needed."),
        ("VendingOolong_NAME", "Чёрный улун (холодный улун в банке)", "Black Oolong (canned cold oolong)"),
        ("VendingOolong_DESC", "Чёрный улун из автомата: тёмный, терпкий, без сахара. На банке написано, что он помогает после жирной еды. Последней жирной едой был медведь. Проверим. Пьётся холодным, огонь не нужен.", "Black oolong from a vending machine: dark, astringent, sugar-free. The can says it helps after fatty food. Your last fatty food was a bear. Let's find out. Drunk cold, no fire needed."),
        ("SouthernSweet_NAME", "Южный сладкий (холодный сладкий чай)", "Southern Sweet (sweet iced tea)"),
        ("SouthernSweet_DESC", "Сладкий холодный чай с американского Юга: пьют на веранде в качалке, обмахиваясь газетой. Веранда у тебя есть. Качалка сгорела в печке. Обмахиваться не требуется. Пьётся холодным, огонь не нужен.", "Sweet iced tea from the American South: drunk in a rocking chair on the porch, fanning yourself with a newspaper. You have a porch. The rocking chair went into the stove. No fanning required. Drunk cold, no fire needed."),
        ("TaigaBlend_NAME", "Таёжный сбор (брусничный лист, смородина, хвоя)", "Taiga Blend (lingonberry leaf, currant, pine needles)"),
        ("TaigaBlend_DESC", "Брусничный лист, смородина и хвоя: тайга в мешочке. Пахнет так, как лес вокруг тебя пах бы, если бы оттаял. Витамины прилагаются, комары нет. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Lingonberry leaf, currant and pine needles: the taiga in a pouch. It smells the way the forest around you would if it ever thawed. Vitamins included, mosquitoes not. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("TaigaBlendCup_NAME", "Таёжный сбор (брусничный лист, смородина, хвоя)", "Taiga Blend (lingonberry leaf, currant, pine needles)"),
        ("TaigaBlendCup_DESC", "Брусничный лист, смородина и хвоя: тайга в мешочке. Пахнет так, как лес вокруг тебя пах бы, если бы оттаял. Витамины прилагаются, комары нет.", "Lingonberry leaf, currant and pine needles: the taiga in a pouch. It smells the way the forest around you would if it ever thawed. Vitamins included, mosquitoes not."),
        ("BirchMushroom_NAME", "Берёзовый гриб (чага)", "Birch Mushroom (chaga)"),
        ("BirchMushroom_DESC", "Чага: чёрный нарост на берёзе, который выглядит как ошибка природы. Сибиряки пьют её всю жизнь и переживают всех. Берёз тут полно. Ты смотришь на них по-новому. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Chaga: a black growth on a birch that looks like a mistake of nature. Siberians drink it all their lives and outlive everyone. There are birches all around. You see them in a new light. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("BirchMushroomCup_NAME", "Берёзовый гриб (чага)", "Birch Mushroom (chaga)"),
        ("BirchMushroomCup_DESC", "Чага: чёрный нарост на берёзе, который выглядит как ошибка природы. Сибиряки пьют её всю жизнь и переживают всех. Берёз тут полно. Ты смотришь на них по-новому.", "Chaga: a black growth on a birch that looks like a mistake of nature. Siberians drink it all their lives and outlive everyone. There are birches all around. You see them in a new light."),
        ("ScarletHip_NAME", "Алая ягода (плоды шиповника)", "Scarlet Hip (rosehip)"),
        ("ScarletHip_DESC", "Плоды шиповника: витамина С больше, чем в лимоне. Шиповник растёт и на острове, но там его надо собирать, колоться и чистить. А тут кто-то уже пострадал за тебя. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Rose hips: more vitamin C than a lemon. Rose hips grow on the island too, but those you have to pick, get pricked by and clean. Here somebody has already suffered for you. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("ScarletHipCup_NAME", "Алая ягода (плоды шиповника)", "Scarlet Hip (rosehip)"),
        ("ScarletHipCup_DESC", "Плоды шиповника: витамина С больше, чем в лимоне. Шиповник растёт и на острове, но там его надо собирать, колоться и чистить. А тут кто-то уже пострадал за тебя.", "Rose hips: more vitamin C than a lemon. Rose hips grow on the island too, but those you have to pick, get pricked by and clean. Here somebody has already suffered for you."),
        ("ForestBerry_NAME", "Лесная ягода (фруктовый чай в пакетиках)", "Forest Berry (fruit tea bags)"),
        ("ForestBerry_DESC", "Фруктовый чай: на коробке малина, черника и земляника. Внутри в основном каркаде и яблочная кожура. Маркетологи пережили катастрофу? Нет. А их ложь пережила. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Fruit tea: the box shows raspberries, blueberries and wild strawberries. Inside it is mostly hibiscus and apple peel. Did the marketers survive the disaster? No. Their lies did. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("ForestBerryCup_NAME", "Лесная ягода (фруктовый чай в пакетиках)", "Forest Berry (fruit tea bags)"),
        ("ForestBerryCup_DESC", "Фруктовый чай: на коробке малина, черника и земляника. Внутри в основном каркаде и яблочная кожура. Маркетологи пережили катастрофу? Нет. А их ложь пережила.", "Fruit tea: the box shows raspberries, blueberries and wild strawberries. Inside it is mostly hibiscus and apple peel. Did the marketers survive the disaster? No. Their lies did."),
        ("RosarioCocido_NAME", "Росарио (мате в пакетиках)", "Rosario (mate cocido bags)"),
        ("RosarioCocido_DESC", "Мате в пакетиках: аргентинцы пьют его на завтрак, когда лень возиться с калебасой. Лень на острове наказуема, но не в этом случае. Тут лень одобрена. Заваривается на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Mate in tea bags: Argentines have it at breakfast when they can't be bothered with the gourd. Laziness is punishable on the island, but not in this case. This laziness is approved. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("RosarioCocidoCup_NAME", "Росарио (мате в пакетиках)", "Rosario (mate cocido bags)"),
        ("RosarioCocidoCup_DESC", "Мате в пакетиках: аргентинцы пьют его на завтрак, когда лень возиться с калебасой. Лень на острове наказуема, но не в этом случае. Тут лень одобрена.", "Mate in tea bags: Argentines have it at breakfast when they can't be bothered with the gourd. Laziness is punishable on the island, but not in this case. This laziness is approved."),
        ("QuickCocoa_NAME", "Шустрик (быстрорастворимое какао)", "Quickie (instant cocoa)"),
        ("QuickCocoa_DESC", "Быстрое какао: насыпал, размешал, готово. Заяц на банке обещает, что комочков не будет. Заяц врёт. Впрочем, здешние зайцы тоже не подарок: попробуй поймай. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Quick cocoa: spoon, stir, done. The rabbit on the jar promises no lumps. The rabbit lies. Then again the local rabbits are no gift either: try catching one. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("QuickCocoaCup_NAME", "Шустрик (быстрорастворимое какао)", "Quickie (instant cocoa)"),
        ("QuickCocoaCup_DESC", "Быстрое какао: насыпал, размешал, готово. Заяц на банке обещает, что комочков не будет. Заяц врёт. Впрочем, здешние зайцы тоже не подарок: попробуй поймай.", "Quick cocoa: spoon, stir, done. The rabbit on the jar promises no lumps. The rabbit lies. Then again the local rabbits are no gift either: try catching one."),
        ("SilverLabel_NAME", "Серебряный ярлык (какао-порошок)", "Silver Label (cocoa powder)"),
        ("SilverLabel_DESC", "Какао-порошок с серебряным ярлыком: варить на молоке, помешивая, не отходить от плиты. Молока нет, плита дровяная, отходить и так некуда. Два условия из трёх. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Cocoa powder with a silver label: simmer in milk, stirring, never leave the stove. You have no milk, the stove burns wood and there is nowhere to go anyway. Two conditions out of three. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("SilverLabelCup_NAME", "Серебряный ярлык (какао-порошок)", "Silver Label (cocoa powder)"),
        ("SilverLabelCup_DESC", "Какао-порошок с серебряным ярлыком: варить на молоке, помешивая, не отходить от плиты. Молока нет, плита дровяная, отходить и так некуда. Два условия из трёх.", "Cocoa powder with a silver label: simmer in milk, stirring, never leave the stove. You have no milk, the stove burns wood and there is nowhere to go anyway. Two conditions out of three."),
        ("ChristmasMarket_NAME", "Рождественская ярмарка (пряности для глинтвейна)", "Christmas Market (mulling spices)"),
        ("ChristmasMarket_DESC", "Пряности для глинтвейна: корица, гвоздика, бадьян, апельсиновая корка. Вина нет, поэтому получается горячий компот с запахом праздника. Ёлок вокруг хоть отбавляй. Готовится на огне: положи в котелок или кастрюлю с водой. Хватает на один раз.", "Mulling spices: cinnamon, clove, star anise, orange peel. There is no wine, so you get a hot punch that smells of the holidays. Christmas trees you have in any quantity. Brew it over a fire: put it in a pot with water. Enough for one cup."),
        ("ChristmasMarketCup_NAME", "Рождественская ярмарка (пряности для глинтвейна)", "Christmas Market (mulling spices)"),
        ("ChristmasMarketCup_DESC", "Пряности для глинтвейна: корица, гвоздика, бадьян, апельсиновая корка. Вина нет, поэтому получается горячий компот с запахом праздника. Ёлок вокруг хоть отбавляй.", "Mulling spices: cinnamon, clove, star anise, orange peel. There is no wine, so you get a hot punch that smells of the holidays. Christmas trees you have in any quantity."),
        ("OrchardCider_NAME", "Садовый сидр (горячий яблочный напиток)", "Orchard Cider (hot apple cider mix)"),
        ("OrchardCider_DESC", "Горячий яблочный напиток: пахнет садом в октябре и пирогом на подоконнике. Сад под снегом, пирог в прошлом, подоконник ты пустил на растопку. Запах остался. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 10.", "Hot apple drink: smells of an orchard in October and a pie on the windowsill. The orchard is under snow, the pie is in the past and the windowsill went for kindling. The smell remains. Brew it over a fire: put it in a pot with water. Servings: 10."),
        ("OrchardCiderCup_NAME", "Садовый сидр (горячий яблочный напиток)", "Orchard Cider (hot apple cider mix)"),
        ("OrchardCiderCup_DESC", "Горячий яблочный напиток: пахнет садом в октябре и пирогом на подоконнике. Сад под снегом, пирог в прошлом, подоконник ты пустил на растопку. Запах остался.", "Hot apple drink: smells of an orchard in October and a pie on the windowsill. The orchard is under snow, the pie is in the past and the windowsill went for kindling. The smell remains."),
        ("GoldenRooster_NAME", "Золотой петушок (куриный бульон в кубиках)", "Golden Rooster (chicken stock cubes)"),
        ("GoldenRooster_DESC", "Куриный бульон в кубике: курицы в нём примерно столько же, сколько петуха в названии. Но горячий, солёный и пахнет обедом. После недели на рогозе: почти ресторан. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 5.", "Chicken stock in a cube: it holds about as much chicken as the name holds rooster. But it is hot, salty and smells of dinner. After a week on cattails it is nearly a restaurant. Brew it over a fire: put it in a pot with water. Servings: 5."),
        ("GoldenRoosterCup_NAME", "Золотой петушок (куриный бульон в кубиках)", "Golden Rooster (chicken stock cubes)"),
        ("GoldenRoosterCup_DESC", "Куриный бульон в кубике: курицы в нём примерно столько же, сколько петуха в названии. Но горячий, солёный и пахнет обедом. После недели на рогозе: почти ресторан.", "Chicken stock in a cube: it holds about as much chicken as the name holds rooster. But it is hot, salty and smells of dinner. After a week on cattails it is nearly a restaurant."),
        ("GingerLemon_NAME", "Имбирь и лимон (гранулированный имбирный напиток)", "Ginger & Lemon (ginger drink granules)"),
        ("GingerLemon_DESC", "Гранулы имбиря с лимоном: ложка в кипяток, и горло горит так, что про мороз забываешь. В Азии этим лечат простуду. На острове простуды нет, есть сразу гипотермия. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 6.", "Ginger and lemon granules: a spoonful in hot water and your throat burns so much you forget the frost. In Asia this treats a cold. The island doesn't do colds, it goes straight to hypothermia. Brew it over a fire: put it in a pot with water. Servings: 6."),
        ("GingerLemonCup_NAME", "Имбирь и лимон (гранулированный имбирный напиток)", "Ginger & Lemon (ginger drink granules)"),
        ("GingerLemonCup_DESC", "Гранулы имбиря с лимоном: ложка в кипяток, и горло горит так, что про мороз забываешь. В Азии этим лечат простуду. На острове простуды нет, есть сразу гипотермия.", "Ginger and lemon granules: a spoonful in hot water and your throat burns so much you forget the frost. In Asia this treats a cold. The island doesn't do colds, it goes straight to hypothermia."),
        ("BlueRoot_NAME", "Синий корень (жидкий экстракт цикория)", "Blue Root (liquid chicory extract)"),
        ("BlueRoot_DESC", "Жидкий цикорий в бутылке: чёрный, тягучий, ложка на кружку. Выглядит как дёготь, пахнет жжёным сахаром. Если прольёшь на снег, волк понюхает и уйдёт в недоумении. Готовится на огне: положи в котелок или кастрюлю с водой. Порций: 8.", "Liquid chicory in a bottle: black, syrupy, a spoonful to a mug. It looks like tar and smells of burnt sugar. Spill it on the snow and a wolf will sniff it and leave, puzzled. Brew it over a fire: put it in a pot with water. Servings: 8."),
        ("BlueRootCup_NAME", "Синий корень (жидкий экстракт цикория)", "Blue Root (liquid chicory extract)"),
        ("BlueRootCup_DESC", "Жидкий цикорий в бутылке: чёрный, тягучий, ложка на кружку. Выглядит как дёготь, пахнет жжёным сахаром. Если прольёшь на снег, волк понюхает и уйдёт в недоумении.", "Liquid chicory in a bottle: black, syrupy, a spoonful to a mug. It looks like tar and smells of burnt sugar. Spill it on the snow and a wolf will sniff it and leave, puzzled."),
    };
}
